// Bo de on 155 cau CNXHKH - sach do HUB. Dap an giu theo tai lieu goc; giai thich la noi dung bien soan bo sung.
window.CNXH_SACH_DO_HUB_155=[{"id":"SACH-DO-HUB-Q001","chapter":0,"number":1,"question":"Theo nghĩa rộng, CNXH khoa học luận giải sự chuyển biến tất yếu của xã hội loài người từ CNTB lên CNXH và CNCS trên những giác độ nào?","options":[{"id":"SACH-DO-HUB-Q001-O1","text":"Triết học và kinh tế học chính trị"},{"id":"SACH-DO-HUB-Q001-O2","text":"Kinh tế học chính trị và chính trị - xã hội"},{"id":"SACH-DO-HUB-Q001-O3","text":"Triết học và chính trị - xã hội"},{"id":"SACH-DO-HUB-Q001-O4","text":"Triết học, kinh tế học chính trị và chính trị - xã hội"}],"correctOptionId":"SACH-DO-HUB-Q001-O4","source":"Sách đỏ HUB (tài liệu lưu hành nội bộ)","explanation":"Theo nghĩa rộng, việc giải thích quá trình chuyển biến từ chủ nghĩa tư bản lên chủ nghĩa xã hội và chủ nghĩa cộng sản cần kết hợp cả ba bình diện. Triết học nêu quy luật phát triển xã hội; kinh tế chính trị phân tích cơ sở kinh tế; chính trị - xã hội làm rõ chủ thể và con đường biến đổi.","topic":"Đề ôn theo sách đỏ HUB","examCode":"SACH-DO-HUB","answerStatus":"marked","basis":"Đáp án theo sách đỏ HUB"},{"id":"SACH-DO-HUB-Q002","chapter":0,"number":2,"question":"Chọn phương án đúng về những tiền đề khoa học tự nhiên là cơ sở phương pháp luận cho các nhà sáng lập CNXH khoa học:","options":[{"id":"SACH-DO-HUB-Q002-O1","text":"Định luật Bernoulli, Thuyết Vạn vật hấp dẫn và Thuyết Nhật tâm"},{"id":"SACH-DO-HUB-Q002-O2","text":"Học thuyết Tiến hóa, Định luật Bảo toàn và chuyển hóa năng lượng, Học thuyết Tế bào"},{"id":"SACH-DO-HUB-Q002-O3","text":"Thuyết Di truyền, Định đề Euclide và Học thuyết Tiến hóa"},{"id":"SACH-DO-HUB-Q002-O4","text":"Thuyết Vạn vật hấp dẫn, Định luật Bảo toàn chuyển hóa năng lượng, Định luật Bernoulli"}],"correctOptionId":"SACH-DO-HUB-Q002-O2","source":"Sách đỏ HUB (tài liệu lưu hành nội bộ)","explanation":"Ba thành tựu này giúp hình thành thế giới quan khoa học thế kỷ XIX: thuyết tế bào giải thích tính thống nhất của sự sống, thuyết tiến hóa chỉ ra sự biến đổi của sinh giới, còn định luật bảo toàn và chuyển hóa năng lượng cho thấy tính liên hệ trong tự nhiên. Chúng tạo nền tảng phương pháp luận cho tư duy duy vật.","topic":"Đề ôn theo sách đỏ HUB","examCode":"SACH-DO-HUB","answerStatus":"marked","basis":"Đáp án theo sách đỏ HUB"},{"id":"SACH-DO-HUB-Q003","chapter":0,"number":3,"question":"Theo Lênin, nhiệm vụ cơ bản của chuyên chính vô sản là:","options":[{"id":"SACH-DO-HUB-Q003-O1","text":"Phát triển kinh tế thị trường"},{"id":"SACH-DO-HUB-Q003-O2","text":"Quốc hữu hóa tư liệu sản xuất chủ yếu"},{"id":"SACH-DO-HUB-Q003-O3","text":"Thủ tiêu mọi chế độ người bóc lột người"},{"id":"SACH-DO-HUB-Q003-O4","text":"Đây lùi chủ nghĩa cá nhân, cơ hội, tham nhũng, quan liêu, lãng phí, tiêu cực"}],"correctOptionId":"SACH-DO-HUB-Q003-O3","source":"Sách đỏ HUB (tài liệu lưu hành nội bộ)","explanation":"Theo cách trình bày của chủ nghĩa Mác - Lênin, chuyên chính vô sản không chỉ thay đổi bộ máy quyền lực mà còn nhằm xóa bỏ những quan hệ xã hội dựa trên bóc lột. Vì vậy, thủ tiêu chế độ người bóc lột người được coi là nhiệm vụ cơ bản, có tính mục tiêu.","topic":"Đề ôn theo sách đỏ HUB","examCode":"SACH-DO-HUB","answerStatus":"marked","basis":"Đáp án theo sách đỏ HUB"},{"id":"SACH-DO-HUB-Q004","chapter":0,"number":4,"question":"Ba đại biểu của tư tưởng CNXH không tưởng - phê phán là:","options":[{"id":"SACH-DO-HUB-Q004-O1","text":"Saint Simon, Charles Fourier và Robert Owen"},{"id":"SACH-DO-HUB-Q004-O2","text":"Hegel, Feuerbach và Kant"},{"id":"SACH-DO-HUB-Q004-O3","text":"Adam Smith, David Ricardo và William Petty"},{"id":"SACH-DO-HUB-Q004-O4","text":"Thomas More, Tommaso Campanella, Gerade Wilstanley"}],"correctOptionId":"SACH-DO-HUB-Q004-O1","source":"Sách đỏ HUB (tài liệu lưu hành nội bộ)","explanation":"Saint-Simon, Charles Fourier và Robert Owen là ba đại biểu tiêu biểu của chủ nghĩa xã hội không tưởng - phê phán ở thế kỷ XIX. Họ phê phán bất công của xã hội tư bản và đề xuất mô hình xã hội tốt đẹp hơn, nhưng chưa xác định được đầy đủ lực lượng và con đường hiện thực hóa.","topic":"Đề ôn theo sách đỏ HUB","examCode":"SACH-DO-HUB","answerStatus":"marked","basis":"Đáp án theo sách đỏ HUB"},{"id":"SACH-DO-HUB-Q005","chapter":0,"number":5,"question":"Trước khi có CNXH khoa học, phong trào đấu tranh của giai cấp vô sản mang tính chất:","options":[{"id":"SACH-DO-HUB-Q005-O1","text":"Chính trị"},{"id":"SACH-DO-HUB-Q005-O2","text":"Tự giác"},{"id":"SACH-DO-HUB-Q005-O3","text":"Triệt dé"},{"id":"SACH-DO-HUB-Q005-O4","text":"Tự phát"}],"correctOptionId":"SACH-DO-HUB-Q005-O4","source":"Sách đỏ HUB (tài liệu lưu hành nội bộ)","explanation":"Trước khi có lý luận chủ nghĩa xã hội khoa học và tổ chức chính trị dẫn dắt, các cuộc đấu tranh của công nhân thường bùng phát từ những bất mãn trước mắt, thiếu mục tiêu và phương pháp thống nhất. Đó là tính tự phát, trái với hoạt động tự giác dựa trên nhận thức lý luận.","topic":"Đề ôn theo sách đỏ HUB","examCode":"SACH-DO-HUB","answerStatus":"marked","basis":"Đáp án theo sách đỏ HUB"},{"id":"SACH-DO-HUB-Q006","chapter":0,"number":6,"question":"CNXH khoa học hình thành từ điều kiện kinh tế - xã hội nào?","options":[{"id":"SACH-DO-HUB-Q006-O1","text":"Sự ra đời Đảng Cộng sản"},{"id":"SACH-DO-HUB-Q006-O2","text":"Sự phát triển phương thức sản xuất tư bản và sự lớn mạnh của giai cấp công nhân"},{"id":"SACH-DO-HUB-Q006-O3","text":"Sự ủng hộ của giai cấp nông dân và tầng lớp trí thức đối với giai cấp công nhân"},{"id":"SACH-DO-HUB-Q006-O4","text":"Giai cấp công nhân giác ngộ về sứ mệnh lịch sử"}],"correctOptionId":"SACH-DO-HUB-Q006-O2","source":"Sách đỏ HUB (tài liệu lưu hành nội bộ)","explanation":"Sự phát triển của đại công nghiệp tư bản chủ nghĩa tập trung đông đảo công nhân, làm bộc lộ mâu thuẫn giữa lao động và tư bản. Đồng thời, giai cấp công nhân trưởng thành thành một lực lượng xã hội, tạo điều kiện kinh tế - xã hội trực tiếp cho sự ra đời của chủ nghĩa xã hội khoa học.","topic":"Đề ôn theo sách đỏ HUB","examCode":"SACH-DO-HUB","answerStatus":"marked","basis":"Đáp án theo sách đỏ HUB"},{"id":"SACH-DO-HUB-Q007","chapter":0,"number":7,"question":"Với phát kiến khoa học nào, C. Mác và Ph. Ăngghen đã luận giải sứ mệnh lịch sử của giai cấp công nhân?","options":[{"id":"SACH-DO-HUB-Q007-O1","text":"Tính hai mặt của lao động và Học thuyết giá trị - lao động"},{"id":"SACH-DO-HUB-Q007-O2","text":"Học thuyết về CNTB độc quyền và CNTB độc quyén nha nước"},{"id":"SACH-DO-HUB-Q007-O3","text":"Chủ nghĩa duy vật lịch sử và Học thuyết giá trị thặng dư"},{"id":"SACH-DO-HUB-Q007-O4","text":"Phép biện chứng duy vật và Học thuyết hình thái kinh tế - xã hội"}],"correctOptionId":"SACH-DO-HUB-Q007-O3","source":"Sách đỏ HUB (tài liệu lưu hành nội bộ)","explanation":"Chủ nghĩa duy vật lịch sử lý giải vai trò của các giai cấp từ điều kiện sản xuất và quan hệ xã hội; học thuyết giá trị thặng dư làm rõ cơ chế bóc lột lao động làm thuê. Kết hợp hai phát kiến giúp Mác và Ăngghen luận chứng địa vị và sứ mệnh lịch sử của giai cấp công nhân.","topic":"Đề ôn theo sách đỏ HUB","examCode":"SACH-DO-HUB","answerStatus":"marked","basis":"Đáp án theo sách đỏ HUB"},{"id":"SACH-DO-HUB-Q008","chapter":0,"number":8,"question":"Tư tưởng CNXH bắt đầu hình thành bởi điều kiện kinh tế nào?","options":[{"id":"SACH-DO-HUB-Q008-O1","text":"Sự xuất hiện chế độ tư hữu tư liệu sản xuất"},{"id":"SACH-DO-HUB-Q008-O2","text":"Sự xuất hiện sở hữu nhà nước"},{"id":"SACH-DO-HUB-Q008-O3","text":"Sự xuất hiện của ngành nông nghiệp"},{"id":"SACH-DO-HUB-Q008-O4","text":"Sự xuất hiện nền sản xuất đại công nghiệp"}],"correctOptionId":"SACH-DO-HUB-Q008-O1","source":"Sách đỏ HUB (tài liệu lưu hành nội bộ)","explanation":"Khi tư liệu sản xuất trở thành sở hữu tư nhân, xã hội xuất hiện sự phân hóa về tài sản và lợi ích, làm nảy sinh bất bình đẳng và quan hệ bóc lột. Từ thực tế đó mới hình thành khát vọng về một cộng đồng công bằng hơn, là nguồn gốc xa của tư tưởng xã hội chủ nghĩa.","topic":"Đề ôn theo sách đỏ HUB","examCode":"SACH-DO-HUB","answerStatus":"marked","basis":"Đáp án theo sách đỏ HUB"},{"id":"SACH-DO-HUB-Q009","chapter":0,"number":9,"question":"Tư tưởng CNXH bat đầu xuất hiện ở hình thái kinh tế - xã hội nào?","options":[{"id":"SACH-DO-HUB-Q009-O1","text":"Tư bản chủ nghĩa"},{"id":"SACH-DO-HUB-Q009-O2","text":"Công xã nguyên thủy"},{"id":"SACH-DO-HUB-Q009-O3","text":"Phong kiến"},{"id":"SACH-DO-HUB-Q009-O4","text":"Chiếm hữu nô lệ"}],"correctOptionId":"SACH-DO-HUB-Q009-O4","source":"Sách đỏ HUB (tài liệu lưu hành nội bộ)","explanation":"Trong cách phân kỳ lịch sử của giáo trình, xã hội chiếm hữu nô lệ đã có đối kháng rõ nét giữa chủ nô và nô lệ. Sự bất công ấy làm nảy sinh những tư tưởng phản kháng và mong muốn một xã hội không áp bức, được xem là những biểu hiện sớm của tư tưởng xã hội chủ nghĩa.","topic":"Đề ôn theo sách đỏ HUB","examCode":"SACH-DO-HUB","answerStatus":"marked","basis":"Đáp án theo sách đỏ HUB"},{"id":"SACH-DO-HUB-Q010","chapter":0,"number":10,"question":"Hạn chế cơ bản của các nhà tư tưởng CNXH không tưởng - phê phán là:","options":[{"id":"SACH-DO-HUB-Q010-O1","text":"Yêu cầu xóa bỏ sự đối lập giữa lao động chân tay và lao động trí óc"},{"id":"SACH-DO-HUB-Q010-O2","text":"Không phát hiện ra lực lượng xã hội tiên phong thực hiện cách mạng xã hội"},{"id":"SACH-DO-HUB-Q010-O3","text":"Không phê phán, không lên án chế độ quân chủ chuyên chế và chế độ tư bản chủ nghĩa"},{"id":"SACH-DO-HUB-Q010-O4","text":"Mong muốn thực hiện chế độ bình quân trong phân phối"}],"correctOptionId":"SACH-DO-HUB-Q010-O2","source":"Sách đỏ HUB (tài liệu lưu hành nội bộ)","explanation":"Các nhà xã hội chủ nghĩa không tưởng phê phán sâu sắc xã hội tư bản nhưng chưa nhận ra giai cấp công nhân là lực lượng xã hội có khả năng tổ chức và thực hiện sự biến đổi cách mạng. Thiếu chủ thể lịch sử rõ ràng khiến những dự án cải tạo xã hội của họ chưa có cơ sở thực hiện vững chắc.","topic":"Đề ôn theo sách đỏ HUB","examCode":"SACH-DO-HUB","answerStatus":"marked","basis":"Đáp án theo sách đỏ HUB"},{"id":"SACH-DO-HUB-Q011","chapter":0,"number":11,"question":"Về giác độ thực tiễn, công lao của Lênin trong việc vận dụng và phát triển CNXH khoa học là:","options":[{"id":"SACH-DO-HUB-Q011-O1","text":"Đề xuất tư tưởng về đập tan bộ máy nhà nước tư sản, thiết lập chuyên chính vô sản"},{"id":"SACH-DO-HUB-Q011-O2","text":"Phát triển chủ nghĩa xã hội không tưởng thành chủ nghĩa xã hội khoa học"},{"id":"SACH-DO-HUB-Q011-O3","text":"Xây dựng chủ nghĩa xã hội hiện thực"},{"id":"SACH-DO-HUB-Q011-O4","text":"Thừa nhận Công xã Pari là một hình thái nhà nước của giai cấp công nhân"}],"correctOptionId":"SACH-DO-HUB-Q011-O3","source":"Sách đỏ HUB (tài liệu lưu hành nội bộ)","explanation":"Lênin vận dụng lý luận Mác vào điều kiện nước Nga, lãnh đạo Cách mạng Tháng Mười năm 1917 và việc xây dựng nhà nước xã hội chủ nghĩa đầu tiên. Vì vậy, đóng góp nổi bật xét từ thực tiễn là biến tư tưởng và lý luận thành quá trình xây dựng chủ nghĩa xã hội hiện thực.","topic":"Đề ôn theo sách đỏ HUB","examCode":"SACH-DO-HUB","answerStatus":"marked","basis":"Đáp án theo sách đỏ HUB"},{"id":"SACH-DO-HUB-Q012","chapter":0,"number":12,"question":"Về việc thực hiện sứ mệnh lịch sử của giai cấp vô sản, quan điểm của C. Mác & Ph. Ăngghen trong tác phầm Tuyên ngôn Đảng Cộng sản (1848) là gì?","options":[{"id":"SACH-DO-HUB-Q012-O1","text":"Giai cấp vô sản không thể hoàn thành sứ mệnh lịch sử nếu không tổ chức ra chính đảng của giai cấp mình"},{"id":"SACH-DO-HUB-Q012-O2","text":"Giai cấp vô sản không cần bất cứ chính đảng nào để hoàn thành sứ mệnh lịch sử."},{"id":"SACH-DO-HUB-Q012-O3","text":"Giai cấp vô sản hoàn toàn độc lập và không cần sự hỗ trợ tir bat kỳ tổ chức nao."},{"id":"SACH-DO-HUB-Q012-O4","text":"Giai cấp vô sản chỉ cần thực hiện cuộc cách mạng mà không cần sự hướng dẫn cua bat kỳ đảng nao."}],"correctOptionId":"SACH-DO-HUB-Q012-O1","source":"Sách đỏ HUB (tài liệu lưu hành nội bộ)","explanation":"Theo Mác và Ăngghen, giai cấp vô sản muốn hành động thành lực lượng chính trị độc lập cần có chính đảng tổ chức, giác ngộ và dẫn dắt. Chính đảng giúp thống nhất mục tiêu, chương trình và hành động của công nhân trong việc thực hiện sứ mệnh lịch sử.","topic":"Đề ôn theo sách đỏ HUB","examCode":"SACH-DO-HUB","answerStatus":"marked","basis":"Đáp án theo sách đỏ HUB"},{"id":"SACH-DO-HUB-Q013","chapter":0,"number":13,"question":"Quan diém triết học nào đã giúp CNXH khoa học vượt qua được tính chất không tưởng, thần bí, duy tâm của các tư tưởng CNXH trước đó?","options":[{"id":"SACH-DO-HUB-Q013-O1","text":"Duy tâm siêu hình"},{"id":"SACH-DO-HUB-Q013-O2","text":"Duy vật siêu hình"},{"id":"SACH-DO-HUB-Q013-O3","text":"Duy tâm biện chứng"},{"id":"SACH-DO-HUB-Q013-O4","text":"Duy vật lịch sử"}],"correctOptionId":"SACH-DO-HUB-Q013-O4","source":"Sách đỏ HUB (tài liệu lưu hành nội bộ)","explanation":"Chủ nghĩa duy vật lịch sử giải thích sự vận động của xã hội dựa trên điều kiện sinh hoạt vật chất, lực lượng sản xuất, quan hệ sản xuất và đấu tranh giai cấp. Nhờ cách tiếp cận này, lý tưởng xã hội chủ nghĩa được đặt trên cơ sở phân tích quy luật lịch sử thay cho sự tưởng tượng thuần túy.","topic":"Đề ôn theo sách đỏ HUB","examCode":"SACH-DO-HUB","answerStatus":"marked","basis":"Đáp án theo sách đỏ HUB"},{"id":"SACH-DO-HUB-Q014","chapter":0,"number":14,"question":"CNXH khoa học đã làm sáng tỏ vai trò lịch sử toàn thế giới của giai cấp nào?","options":[{"id":"SACH-DO-HUB-Q014-O1","text":"Giai cấp nông dân"},{"id":"SACH-DO-HUB-Q014-O2","text":"Giai cấp công nhân"},{"id":"SACH-DO-HUB-Q014-O3","text":"Giai cấp tư sản"},{"id":"SACH-DO-HUB-Q014-O4","text":"Giai cấp chủ nô"}],"correctOptionId":"SACH-DO-HUB-Q014-O2","source":"Sách đỏ HUB (tài liệu lưu hành nội bộ)","explanation":"Chủ nghĩa xã hội khoa học chỉ ra giai cấp công nhân có vị trí gắn với lực lượng sản xuất hiện đại và lợi ích căn bản đối lập với quan hệ bóc lột tư bản. Vì vậy, giai cấp này được xác định là chủ thể mang sứ mệnh lịch sử trong quá trình chuyển biến xã hội.","topic":"Đề ôn theo sách đỏ HUB","examCode":"SACH-DO-HUB","answerStatus":"marked","basis":"Đáp án theo sách đỏ HUB"},{"id":"SACH-DO-HUB-Q015","chapter":0,"number":15,"question":"Trong CNTB, mâu thuẫn về mặt kinh tế đã biểu hiện ra thành mâu thuẫn chính trị giữa:","options":[{"id":"SACH-DO-HUB-Q015-O1","text":"Giai cấp tư sản với giai cấp nông dân"},{"id":"SACH-DO-HUB-Q015-O2","text":"Giai cấp tư sản với tầng lớp tiểu tư sản"},{"id":"SACH-DO-HUB-Q015-O3","text":"Giai cấp tư sản với giai cấp công nhân"},{"id":"SACH-DO-HUB-Q015-O4","text":"Giai cấp tư sản với giai cấp địa chủ"}],"correctOptionId":"SACH-DO-HUB-Q015-O3","source":"Sách đỏ HUB (tài liệu lưu hành nội bộ)","explanation":"Mâu thuẫn kinh tế cơ bản giữa tính chất xã hội hóa của sản xuất và sự chiếm hữu tư nhân tư bản chủ nghĩa biểu hiện trực tiếp qua quan hệ giữa người sở hữu tư bản và người bán sức lao động. Khi phát triển thành đấu tranh về quyền lực và chế độ xã hội, nó trở thành mâu thuẫn chính trị giữa tư sản và công nhân.","topic":"Đề ôn theo sách đỏ HUB","examCode":"SACH-DO-HUB","answerStatus":"marked","basis":"Đáp án theo sách đỏ HUB"},{"id":"SACH-DO-HUB-Q016","chapter":0,"number":16,"question":"Chọn phương án đúng cho cụm từ còn thiếu: “[.........] có thể thắng lợi ở một số nước hay thậm chí ở một nước riêng lẻ, nơi chủ nghĩa tư bản chưa phải là phát triển nhất, nhưng là khâu yếu nhất trong sợi dây chuyền tư bản chủ nghĩa” (Lênin: Toàn tập. Tập 26. Nxb Tiến bộ, Mat-xco-va, 1980, tr.447)","options":[{"id":"SACH-DO-HUB-Q016-O1","text":"Cách mạng vô sản"},{"id":"SACH-DO-HUB-Q016-O2","text":"Cách mạng tư sản"},{"id":"SACH-DO-HUB-Q016-O3","text":"Cách mạng khoa học - kỹ thuật"},{"id":"SACH-DO-HUB-Q016-O4","text":"Cách mạng nông nghiệp"}],"correctOptionId":"SACH-DO-HUB-Q016-O1","source":"Sách đỏ HUB (tài liệu lưu hành nội bộ)","explanation":"Lênin nhấn mạnh sự phát triển không đều của chủ nghĩa tư bản giữa các nước; vì thế cách mạng vô sản không nhất thiết phải thắng lợi đồng thời ở mọi quốc gia. Nó có thể giành thắng lợi trước ở một hoặc một số nước có điều kiện và tương quan lực lượng thuận lợi.","topic":"Đề ôn theo sách đỏ HUB","examCode":"SACH-DO-HUB","answerStatus":"marked","basis":"Đáp án theo sách đỏ HUB"},{"id":"SACH-DO-HUB-Q017","chapter":0,"number":17,"question":"Luận chứng một cách khoa học tính tất yếu về mặt lịch sử sự thay thế của CNTB bằng CNCS với sứ mệnh lịch sử của giai cấp công nhân, là nhiệm vụ cơ bản của:","options":[{"id":"SACH-DO-HUB-Q017-O1","text":"Chủ nghĩa xã hội không tưởng"},{"id":"SACH-DO-HUB-Q017-O2","text":"Chủ nghĩa hiện sinh"},{"id":"SACH-DO-HUB-Q017-O3","text":"Chủ nghĩa tân tự do"},{"id":"SACH-DO-HUB-Q017-O4","text":"Chủ nghĩa xã hội khoa học"}],"correctOptionId":"SACH-DO-HUB-Q017-O4","source":"Sách đỏ HUB (tài liệu lưu hành nội bộ)","explanation":"Chủ nghĩa xã hội khoa học nghiên cứu quy luật và điều kiện chính trị - xã hội của quá trình thay thế chủ nghĩa tư bản bằng xã hội mới, đồng thời làm rõ sứ mệnh lịch sử của giai cấp công nhân. Đây chính là nhiệm vụ lý luận trung tâm phân biệt nó với các trào lưu xã hội chủ nghĩa không tưởng.","topic":"Đề ôn theo sách đỏ HUB","examCode":"SACH-DO-HUB","answerStatus":"marked","basis":"Đáp án theo sách đỏ HUB"},{"id":"SACH-DO-HUB-Q018","chapter":0,"number":18,"question":"Đối tượng nghiên cứu của CNXH khoa học là:","options":[{"id":"SACH-DO-HUB-Q018-O1","text":"những quy luật hình thành và phát triển của các hình thái kinh tế - xã hội"},{"id":"SACH-DO-HUB-Q018-O2","text":"những quy luật và tính quy luật chính trị - xã hội của quá trình phái sinh, hình thành và phát triển hình thai kinh tê - xã hội cộng san chủ nghĩa"},{"id":"SACH-DO-HUB-Q018-O3","text":"những quy luật và tính quy luật kinh tế của quá trình phát sinh, hình thành và phát triển hình thái kinh tê - xã hội tư bản chủ nghĩa"},{"id":"SACH-DO-HUB-Q018-O4","text":"những quy luật và tính quy luật của tự nhiên và tư duy"}],"correctOptionId":"SACH-DO-HUB-Q018-O2","source":"Sách đỏ HUB (tài liệu lưu hành nội bộ)","explanation":"Đối tượng của chủ nghĩa xã hội khoa học tập trung vào các quy luật mang tính chính trị - xã hội trong quá trình ra đời và phát triển hình thái kinh tế - xã hội cộng sản chủ nghĩa. Nó nghiên cứu chủ thể, điều kiện, động lực và con đường xây dựng xã hội mới, chứ không nghiên cứu mọi quy luật tự nhiên.","topic":"Đề ôn theo sách đỏ HUB","examCode":"SACH-DO-HUB","answerStatus":"marked","basis":"Đáp án theo sách đỏ HUB"},{"id":"SACH-DO-HUB-Q019","chapter":0,"number":19,"question":"Phạm trù cơ bản nhất của CNXH khoa học là:","options":[{"id":"SACH-DO-HUB-Q019-O1","text":"Chuyên chính vô sản"},{"id":"SACH-DO-HUB-Q019-O2","text":"Chủ nghĩa quốc tế vô sản"},{"id":"SACH-DO-HUB-Q019-O3","text":"Sứ mệnh lịch sử của giai cấp công nhân"},{"id":"SACH-DO-HUB-Q019-O4","text":"Dân tộc và Tôn giáo"}],"correctOptionId":"SACH-DO-HUB-Q019-O3","source":"Sách đỏ HUB (tài liệu lưu hành nội bộ)","explanation":"Khái niệm sứ mệnh lịch sử của giai cấp công nhân kết nối những vấn đề cốt lõi như chủ thể cách mạng, vai trò của Đảng Cộng sản, liên minh giai cấp và mục tiêu xây dựng xã hội mới. Vì vậy, đây là phạm trù trung tâm của môn chủ nghĩa xã hội khoa học.","topic":"Đề ôn theo sách đỏ HUB","examCode":"SACH-DO-HUB","answerStatus":"marked","basis":"Đáp án theo sách đỏ HUB"},{"id":"SACH-DO-HUB-Q020","chapter":0,"number":20,"question":"Bộ phận nào thể hiện tập trung nhất tính chính trị - thực tiễn sinh động của chủ nghĩa Mác — Lênin?","options":[{"id":"SACH-DO-HUB-Q020-O1","text":"Chủ nghĩa xã hội khoa học"},{"id":"SACH-DO-HUB-Q020-O2","text":"Triết học"},{"id":"SACH-DO-HUB-Q020-O3","text":"Kinh tế chính trị"},{"id":"SACH-DO-HUB-Q020-O4","text":"Triết học và Kinh tế chính trị"}],"correctOptionId":"SACH-DO-HUB-Q020-O1","source":"Sách đỏ HUB (tài liệu lưu hành nội bộ)","explanation":"Trong ba bộ phận cấu thành của chủ nghĩa Mác - Lênin, chủ nghĩa xã hội khoa học tập trung trực tiếp vào mục tiêu, lực lượng, phương pháp và quá trình cải biến xã hội. Do gắn chặt với hoạt động cách mạng và xây dựng chế độ mới, nó biểu hiện rõ nhất tính chính trị và thực tiễn.","topic":"Đề ôn theo sách đỏ HUB","examCode":"SACH-DO-HUB","answerStatus":"marked","basis":"Đáp án theo sách đỏ HUB"},{"id":"SACH-DO-HUB-Q021","chapter":0,"number":21,"question":"Chọn phương án đúng cho cụm từ còn thiếu: “ [.........] là sản phẩm của sự kết hợp chủ nghĩa Mác — Lênin với phong trào công nhân trong cuộc đấu tranh thực hiện sứ mệnh lịch sử của giai cầp công nhân”","options":[{"id":"SACH-DO-HUB-Q021-O1","text":"Đảng Cộng sản"},{"id":"SACH-DO-HUB-Q021-O2","text":"Giai cấp tư sản"},{"id":"SACH-DO-HUB-Q021-O3","text":"Đảng chính trị"},{"id":"SACH-DO-HUB-Q021-O4","text":"Giai cấp công nhân"}],"correctOptionId":"SACH-DO-HUB-Q021-O1","source":"Sách đỏ HUB (tài liệu lưu hành nội bộ)","explanation":"Đảng Cộng sản được hình thành khi lý luận Mác - Lênin gắn với phong trào công nhân, tạo cơ sở tư tưởng và tổ chức cho cuộc đấu tranh thực hiện sứ mệnh lịch sử. Chính sự kết hợp giữa lý luận và phong trào thực tiễn tạo ra một chính đảng của giai cấp công nhân.","topic":"Đề ôn theo sách đỏ HUB","examCode":"SACH-DO-HUB","answerStatus":"marked","basis":"Đáp án theo sách đỏ HUB"},{"id":"SACH-DO-HUB-Q022","chapter":0,"number":22,"question":"Giai cấp công nhân bắt đầu hình thành và phát triển mạnh trong xã hội nào?","options":[{"id":"SACH-DO-HUB-Q022-O1","text":"Xã hội phong kiến"},{"id":"SACH-DO-HUB-Q022-O2","text":"Xã hội tư bản chủ nghĩa"},{"id":"SACH-DO-HUB-Q022-O3","text":"Xã hội chiếm hữu nô lệ"},{"id":"SACH-DO-HUB-Q022-O4","text":"Xã hội xã hội chủ nghĩa"}],"correctOptionId":"SACH-DO-HUB-Q022-O2","source":"Sách đỏ HUB (tài liệu lưu hành nội bộ)","explanation":"Đại công nghiệp trong xã hội tư bản làm xuất hiện một lực lượng đông đảo người lao động làm thuê, làm việc trong các nhà máy và không sở hữu tư liệu sản xuất chủ yếu. Do đó, giai cấp công nhân hiện đại hình thành và phát triển mạnh cùng với chủ nghĩa tư bản.","topic":"Đề ôn theo sách đỏ HUB","examCode":"SACH-DO-HUB","answerStatus":"marked","basis":"Đáp án theo sách đỏ HUB"},{"id":"SACH-DO-HUB-Q023","chapter":0,"number":23,"question":"Theo C. Mác & Ph. Ăngghen, hai phương diện cơ bản xác định giai cấp công nhân là:","options":[{"id":"SACH-DO-HUB-Q023-O1","text":"chính trị - xã hội và văn hóa — xã hội"},{"id":"SACH-DO-HUB-Q023-O2","text":"kinh tế - xã hội và văn hóa — xã hội"},{"id":"SACH-DO-HUB-Q023-O3","text":"kinh tế - xã hội và chính trị - xã hội"},{"id":"SACH-DO-HUB-Q023-O4","text":"chính trị - xã hội và an ninh — xã hội"}],"correctOptionId":"SACH-DO-HUB-Q023-O3","source":"Sách đỏ HUB (tài liệu lưu hành nội bộ)","explanation":"Phương diện kinh tế - xã hội xác định công nhân qua vị trí trong nền sản xuất công nghiệp và quan hệ với tư liệu sản xuất; phương diện chính trị - xã hội xét địa vị, lợi ích và quan hệ của họ với giai cấp tư sản. Cả hai mới phản ánh đầy đủ đặc trưng giai cấp công nhân.","topic":"Đề ôn theo sách đỏ HUB","examCode":"SACH-DO-HUB","answerStatus":"marked","basis":"Đáp án theo sách đỏ HUB"},{"id":"SACH-DO-HUB-Q024","chapter":0,"number":24,"question":"“Giai cấp công nhân là những người trực tiếp hoặc gián tiếp vận hành các công cụ sản xuất có tính chất công nghiệp ngày càng hiện đại và xã hội hóa cao”. Đây là nội dung thuộc phương diện nào trong hai phương diện xác định giai cấp công nhân?","options":[{"id":"SACH-DO-HUB-Q024-O1","text":"Anninh - xã hội"},{"id":"SACH-DO-HUB-Q024-O2","text":"Chính trị — xã hội"},{"id":"SACH-DO-HUB-Q024-O3","text":"Văn hóa — xã hội"},{"id":"SACH-DO-HUB-Q024-O4","text":"Kinh tế- xã hội"}],"correctOptionId":"SACH-DO-HUB-Q024-O4","source":"Sách đỏ HUB (tài liệu lưu hành nội bộ)","explanation":"Câu mô tả công nhân qua việc trực tiếp hoặc gián tiếp vận hành những công cụ sản xuất công nghiệp hiện đại. Nó nói đến cách lao động và vị trí trong lực lượng sản xuất, nên thuộc phương diện kinh tế - xã hội.","topic":"Đề ôn theo sách đỏ HUB","examCode":"SACH-DO-HUB","answerStatus":"marked","basis":"Đáp án theo sách đỏ HUB"},{"id":"SACH-DO-HUB-Q025","chapter":0,"number":25,"question":"“Giai cấp công nhân là những người lao động không có sở hữu tư liệu sản xuất chủ yếu của xã hội, phải bán sức lao động cho nhà tư bản và bị chủ tư bản bóc lột giá trị thặng dư”. Đây là nội dung thuộc phương diện nào trong hai phương diện xác định giai cấp công nhân?","options":[{"id":"SACH-DO-HUB-Q025-O1","text":"Chính trị - xã hội"},{"id":"SACH-DO-HUB-Q025-O2","text":"Kinh tế — xã hội"},{"id":"SACH-DO-HUB-Q025-O3","text":"Văn hóa — xã hội"},{"id":"SACH-DO-HUB-Q025-O4","text":"An ninh - xã hội"}],"correctOptionId":"SACH-DO-HUB-Q025-O1","source":"Sách đỏ HUB (tài liệu lưu hành nội bộ)","explanation":"Việc không sở hữu các tư liệu sản xuất chủ yếu, phải bán sức lao động và chịu sự chiếm đoạt giá trị thặng dư cho thấy quan hệ lợi ích đối kháng giữa công nhân và tư bản. Đó là cơ sở làm rõ địa vị chính trị - xã hội của giai cấp công nhân trong chủ nghĩa tư bản.","topic":"Đề ôn theo sách đỏ HUB","examCode":"SACH-DO-HUB","answerStatus":"marked","basis":"Đáp án theo sách đỏ HUB"},{"id":"SACH-DO-HUB-Q026","chapter":0,"number":26,"question":"Điều kiện khách quan quy định sứ mệnh lịch sử của giai cấp công nhân là:","options":[{"id":"SACH-DO-HUB-Q026-O1","text":"Đảng Cộng sản lãnh đạo"},{"id":"SACH-DO-HUB-Q026-O2","text":"Địa vị kinh tế - xã hội và địa vị chính trị - xã hội"},{"id":"SACH-DO-HUB-Q026-O3","text":"Bản thân giai cấp công nhân phát triển về số lượng và chất lượng"},{"id":"SACH-DO-HUB-Q026-O4","text":"Giai cấp công nhân có đồng minh tự nhiên là giai cấp nông dân"}],"correctOptionId":"SACH-DO-HUB-Q026-O2","source":"Sách đỏ HUB (tài liệu lưu hành nội bộ)","explanation":"Địa vị kinh tế - xã hội của công nhân gắn với lực lượng sản xuất hiện đại; địa vị chính trị - xã hội gắn với lợi ích và quan hệ giai cấp của họ. Hai phương diện khách quan này giải thích vì sao chủ nghĩa Mác - Lênin xác định giai cấp công nhân mang sứ mệnh lịch sử.","topic":"Đề ôn theo sách đỏ HUB","examCode":"SACH-DO-HUB","answerStatus":"marked","basis":"Đáp án theo sách đỏ HUB"},{"id":"SACH-DO-HUB-Q027","chapter":0,"number":27,"question":"Đảng Cộng sản mang bản chất của giai cấp nào?","options":[{"id":"SACH-DO-HUB-Q027-O1","text":"Giai cấp nông dân"},{"id":"SACH-DO-HUB-Q027-O2","text":"Giai cấp tư sản"},{"id":"SACH-DO-HUB-Q027-O3","text":"Giai cấp công nhân"},{"id":"SACH-DO-HUB-Q027-O4","text":"Đội ngũ doanh nhân"}],"correctOptionId":"SACH-DO-HUB-Q027-O3","source":"Sách đỏ HUB (tài liệu lưu hành nội bộ)","explanation":"Theo chủ nghĩa Mác - Lênin, Đảng Cộng sản là đội tiên phong chính trị của giai cấp công nhân, lấy hệ tư tưởng và lợi ích căn bản của giai cấp này làm nền tảng. Việc đại diện lợi ích rộng lớn của người lao động không làm thay đổi bản chất giai cấp công nhân của Đảng.","topic":"Đề ôn theo sách đỏ HUB","examCode":"SACH-DO-HUB","answerStatus":"marked","basis":"Đáp án theo sách đỏ HUB"},{"id":"SACH-DO-HUB-Q028","chapter":0,"number":28,"question":"Theo chủ nghĩa Mác — Lênin, quy luật chung cho sự ra đời của Đảng Cộng sản là sự kết hợp giữa:","options":[{"id":"SACH-DO-HUB-Q028-O1","text":"Chủ nghĩa Mác — Lênin với phong trào nông dân"},{"id":"SACH-DO-HUB-Q028-O2","text":"Chủ nghĩa Mác — Lênin với phong trào dân tộc"},{"id":"SACH-DO-HUB-Q028-O3","text":"Chủ nghĩa Mác — Lênin với phong trào yêu nước"},{"id":"SACH-DO-HUB-Q028-O4","text":"Chủ nghĩa Mác — Lênin với phong trào công nhân"}],"correctOptionId":"SACH-DO-HUB-Q028-O4","source":"Sách đỏ HUB (tài liệu lưu hành nội bộ)","explanation":"Quy luật chung là sự kết hợp lý luận chủ nghĩa Mác - Lênin với phong trào công nhân: lý luận cung cấp định hướng, còn phong trào cung cấp cơ sở xã hội và thực tiễn. Nhờ đó hình thành tổ chức chính trị có chương trình và mục tiêu cách mạng rõ ràng.","topic":"Đề ôn theo sách đỏ HUB","examCode":"SACH-DO-HUB","answerStatus":"marked","basis":"Đáp án theo sách đỏ HUB"},{"id":"SACH-DO-HUB-Q029","chapter":0,"number":29,"question":"Nhân tố chủ quan tiên quyết để giai cấp công nhân thực hiện thành công sứ mệnh lịch sử là:","options":[{"id":"SACH-DO-HUB-Q029-O1","text":"Đảng Cộng sản lãnh đạo"},{"id":"SACH-DO-HUB-Q029-O2","text":"Địa vị kinh tế - xã hội của giai cấp công nhân quy định"},{"id":"SACH-DO-HUB-Q029-O3","text":"Địa vị chính trị - xã hội của giai cấp công nhân quy định"},{"id":"SACH-DO-HUB-Q029-O4","text":"Giai cấp công nhân có đồng minh tự nhiên là giai cấp nông dân"}],"correctOptionId":"SACH-DO-HUB-Q029-O1","source":"Sách đỏ HUB (tài liệu lưu hành nội bộ)","explanation":"Đảng Cộng sản giữ vai trò tổ chức, giáo dục, đề ra đường lối và tập hợp lực lượng cho giai cấp công nhân. Vì thế, sự lãnh đạo của Đảng được coi là điều kiện chủ quan tiên quyết để thực hiện sứ mệnh lịch sử, khác với những điều kiện khách quan về vị trí kinh tế - xã hội.","topic":"Đề ôn theo sách đỏ HUB","examCode":"SACH-DO-HUB","answerStatus":"marked","basis":"Đáp án theo sách đỏ HUB"},{"id":"SACH-DO-HUB-Q030","chapter":0,"number":30,"question":"Trong thời đại ngày nay, quá trình nào vẫn là cơ sở khách quan để giai cấp công nhân hiện đại phát triển mạnh mẽ cả về số lượng lẫn chất lượng?","options":[{"id":"SACH-DO-HUB-Q030-O1","text":"Xây dựng nông thôn mới"},{"id":"SACH-DO-HUB-Q030-O2","text":"Công nghiệp hóa"},{"id":"SACH-DO-HUB-Q030-O3","text":"Cổ phần hóa"},{"id":"SACH-DO-HUB-Q030-O4","text":"Quốc hữu hóa"}],"correctOptionId":"SACH-DO-HUB-Q030-O2","source":"Sách đỏ HUB (tài liệu lưu hành nội bộ)","explanation":"Công nghiệp hóa làm mở rộng nền sản xuất công nghiệp, ứng dụng máy móc và công nghệ, từ đó biến đổi cả số lượng lẫn trình độ của đội ngũ công nhân. Dù hình thức lao động hiện đại thay đổi, công nghiệp hóa vẫn là cơ sở khách quan quan trọng cho sự phát triển giai cấp này.","topic":"Đề ôn theo sách đỏ HUB","examCode":"SACH-DO-HUB","answerStatus":"marked","basis":"Đáp án theo sách đỏ HUB"},{"id":"SACH-DO-HUB-Q031","chapter":0,"number":31,"question":"Luận điểm nào là đặc trưng riêng có của giai cấp công nhân Việt Nam?","options":[{"id":"SACH-DO-HUB-Q031-O1","text":"Có lãnh tụ dan dat phong trào đấu tranh"},{"id":"SACH-DO-HUB-Q031-O2","text":"Sớm tập hợp được quần chúng nhân dân"},{"id":"SACH-DO-HUB-Q031-O3","text":"Ra đời trước cả giai cấp tư sản Việt Nam"},{"id":"SACH-DO-HUB-Q031-O4","text":"Có tinh thần yêu nước"}],"correctOptionId":"SACH-DO-HUB-Q031-O3","source":"Sách đỏ HUB (tài liệu lưu hành nội bộ)","explanation":"Ở Việt Nam thời thuộc địa, giai cấp công nhân xuất hiện trong quá trình khai thác thuộc địa và phát triển sớm hơn giai cấp tư sản dân tộc. Trình tự ra đời này là nét đặc thù lịch sử của giai cấp công nhân Việt Nam so với nhiều nước tư bản phương Tây.","topic":"Đề ôn theo sách đỏ HUB","examCode":"SACH-DO-HUB","answerStatus":"marked","basis":"Đáp án theo sách đỏ HUB"},{"id":"SACH-DO-HUB-Q032","chapter":0,"number":32,"question":"Đảng Cộng sản Việt Nam là sản phẩm của sự kết hợp các nhân tố nào?","options":[{"id":"SACH-DO-HUB-Q032-O1","text":"Chủ nghĩa Mác — Lênin với phong trào nông dân và phong trào yêu nước ở Việt Nam"},{"id":"SACH-DO-HUB-Q032-O2","text":"Chủ nghĩa Mác — Lênin với phong trào công nhân ở Việt Nam"},{"id":"SACH-DO-HUB-Q032-O3","text":"Chủ nghĩa Mác — Lênin với phong trào yêu nước Việt Nam"},{"id":"SACH-DO-HUB-Q032-O4","text":"Chủ nghĩa Mác — Lênin với phong trào công nhân và phong trào yêu nước ở Việt Nam"}],"correctOptionId":"SACH-DO-HUB-Q032-O4","source":"Sách đỏ HUB (tài liệu lưu hành nội bộ)","explanation":"Đảng Cộng sản Việt Nam ra đời từ sự gắn kết ba yếu tố: chủ nghĩa Mác - Lênin, phong trào công nhân và phong trào yêu nước. Yếu tố yêu nước phản ánh hoàn cảnh dân tộc bị đô hộ và truyền thống đấu tranh giành độc lập của Việt Nam.","topic":"Đề ôn theo sách đỏ HUB","examCode":"SACH-DO-HUB","answerStatus":"marked","basis":"Đáp án theo sách đỏ HUB"},{"id":"SACH-DO-HUB-Q033","chapter":0,"number":33,"question":"Chọn phương án đúng cho cụm từ còn thiếu: “Trong công trường thủ công và trong nghề thủ công, người công nhân sử dụng công cụ của mình, còn trong công xưởng thì người công nhân phải [......]”","options":[{"id":"SACH-DO-HUB-Q033-O1","text":"Phục vụ máy móc"},{"id":"SACH-DO-HUB-Q033-O2","text":"Thuê tư liệu sản xuất của giai cấp tư sản"},{"id":"SACH-DO-HUB-Q033-O3","text":"Thuê đất đai của địa chủ"},{"id":"SACH-DO-HUB-Q033-O4","text":"Đóng góp tư liệu sản xuất"}],"correctOptionId":"SACH-DO-HUB-Q033-O1","source":"Sách đỏ HUB (tài liệu lưu hành nội bộ)","explanation":"Trong sản xuất thủ công, người thợ chủ động điều khiển công cụ; khi sản xuất bằng máy móc trong công xưởng, nhịp độ và thao tác lao động bị chi phối bởi hệ thống máy. Vì vậy, cụm “phục vụ máy móc” thể hiện sự thay đổi vị trí của người lao động trong nền đại công nghiệp.","topic":"Đề ôn theo sách đỏ HUB","examCode":"SACH-DO-HUB","answerStatus":"marked","basis":"Đáp án theo sách đỏ HUB"},{"id":"SACH-DO-HUB-Q034","chapter":0,"number":34,"question":"Chọn phương án đúng cho cụm từ còn thiếu: “Giai cấp công nhân là một tập đoàn xã hội ôn định, hình thành và phát triển cùng với quá trình của nền công nghiệp hiện đại, với nhịp độ phát triển của lực lượng sản xuất có tính chất [........] ngày càng cao”","options":[{"id":"SACH-DO-HUB-Q034-O1","text":"Ban cùng hóa, chuyên môn hóa"},{"id":"SACH-DO-HUB-Q034-O2","text":"Tư nhân hóa, trí thức hóa"},{"id":"SACH-DO-HUB-Q034-O3","text":"Quốc hữu hoa, tri thức hóa"},{"id":"SACH-DO-HUB-Q034-O4","text":"Xã hội hóa, trí tué hóa"}],"correctOptionId":"SACH-DO-HUB-Q034-O4","source":"Sách đỏ HUB (tài liệu lưu hành nội bộ)","explanation":"Sản xuất công nghiệp hiện đại ngày càng mang tính liên kết, hợp tác trên quy mô xã hội và đòi hỏi lao động có tri thức, kỹ năng cao hơn. Hai xu hướng “xã hội hóa” và “trí tuệ hóa” vì vậy phản ánh đặc điểm phát triển của lực lượng sản xuất và giai cấp công nhân.","topic":"Đề ôn theo sách đỏ HUB","examCode":"SACH-DO-HUB","answerStatus":"marked","basis":"Đáp án theo sách đỏ HUB"},{"id":"SACH-DO-HUB-Q035","chapter":0,"number":35,"question":"Chủ nghĩa Mác — Lênin là hệ tư tưởng của giai cấp nào?","options":[{"id":"SACH-DO-HUB-Q035-O1","text":"Giai cấp tư sản"},{"id":"SACH-DO-HUB-Q035-O2","text":"Giai cấp nông dân"},{"id":"SACH-DO-HUB-Q035-O3","text":"Giai cấp công nhân"},{"id":"SACH-DO-HUB-Q035-O4","text":"Tầng lớp trí thức"}],"correctOptionId":"SACH-DO-HUB-Q035-O3","source":"Sách đỏ HUB (tài liệu lưu hành nội bộ)","explanation":"Theo giáo trình chủ nghĩa xã hội khoa học, chủ nghĩa Mác - Lênin là thế giới quan và phương pháp luận lý luận của giai cấp công nhân. Nó lý giải địa vị, lợi ích và con đường giải phóng của giai cấp này.","topic":"Đề ôn theo sách đỏ HUB","examCode":"SACH-DO-HUB","answerStatus":"marked","basis":"Đáp án theo sách đỏ HUB"},{"id":"SACH-DO-HUB-Q036","chapter":0,"number":36,"question":"Sứ mệnh xóa bỏ chủ nghĩa tư bản, xây dựng CNXH và CNCS là của giai cấp nào?","options":[{"id":"SACH-DO-HUB-Q036-O1","text":"Giai cấp nông nhân"},{"id":"SACH-DO-HUB-Q036-O2","text":"Giai cấp công dân"},{"id":"SACH-DO-HUB-Q036-O3","text":"Giai cấp tư sản"},{"id":"SACH-DO-HUB-Q036-O4","text":"Tầng lớp trí thức"}],"correctOptionId":"SACH-DO-HUB-Q036-O2","source":"Sách đỏ HUB (tài liệu lưu hành nội bộ)","explanation":"Theo nội dung lý luận được hỏi, lực lượng mang sứ mệnh xóa bỏ quan hệ bóc lột tư bản chủ nghĩa và xây dựng chủ nghĩa xã hội, chủ nghĩa cộng sản là giai cấp công nhân. Sách đỏ đánh dấu phương án B; cách ghi “giai cấp công dân” trong phương án cần được đọc theo đúng bản gốc khi sử dụng đáp án.","topic":"Đề ôn theo sách đỏ HUB","examCode":"SACH-DO-HUB","answerStatus":"marked","basis":"Đáp án theo sách đỏ HUB"},{"id":"SACH-DO-HUB-Q037","chapter":0,"number":37,"question":"“Điểm chủ yếu trong học thuyết Mác là ở chỗ nó làm sáng rõ vai trò lịch sử thế giới của giai cấp vô sản là người xây dựng xã hội xã hội chủ nghĩa” là nhận định của ai?","options":[{"id":"SACH-DO-HUB-Q037-O1","text":"Lênin"},{"id":"SACH-DO-HUB-Q037-O2","text":"Ph. Ăngghen"},{"id":"SACH-DO-HUB-Q037-O3","text":"C. Mác"},{"id":"SACH-DO-HUB-Q037-O4","text":"Hồ Chi Minh"}],"correctOptionId":"SACH-DO-HUB-Q037-O1","source":"Sách đỏ HUB (tài liệu lưu hành nội bộ)","explanation":"Lênin đánh giá đóng góp nổi bật của học thuyết Mác là làm sáng tỏ vai trò lịch sử thế giới của giai cấp vô sản. Vì vậy, phát biểu trích dẫn trong câu được gắn với nhận định của Lênin về chủ nghĩa Mác.","topic":"Đề ôn theo sách đỏ HUB","examCode":"SACH-DO-HUB","answerStatus":"marked","basis":"Đáp án theo sách đỏ HUB"},{"id":"SACH-DO-HUB-Q038","chapter":0,"number":38,"question":"Theo quan điểm của chủ nghĩa Mác — Lênin, luận điểm nào sau đây nói về bản chất của giai cấp tư sản?","options":[{"id":"SACH-DO-HUB-Q038-O1","text":"thực hiện chính sách an sinh xã hội"},{"id":"SACH-DO-HUB-Q038-O2","text":"tích cực áp dụng tiến bộ khoa học kỹ thuật và công nghệ"},{"id":"SACH-DO-HUB-Q038-O3","text":"đôi mới phương pháp quản lý"},{"id":"SACH-DO-HUB-Q038-O4","text":"bóc lột giá trị thặng dư"}],"correctOptionId":"SACH-DO-HUB-Q038-O4","source":"Sách đỏ HUB (tài liệu lưu hành nội bộ)","explanation":"Theo học thuyết giá trị thặng dư của Mác, nhà tư bản sở hữu tư liệu sản xuất và chiếm đoạt phần giá trị do lao động làm thuê tạo ra vượt quá giá trị sức lao động. Bóc lột giá trị thặng dư là đặc trưng bản chất được nêu ở đây.","topic":"Đề ôn theo sách đỏ HUB","examCode":"SACH-DO-HUB","answerStatus":"marked","basis":"Đáp án theo sách đỏ HUB"},{"id":"SACH-DO-HUB-Q039","chapter":0,"number":39,"question":"Chọn phương án đúng cho cụm từ còn thiếu: “Tat cả các giai cấp khác đều suy tàn và tiêu vong cùng với sự phát triển của đại công nghiệp, còn giai cấp vô sản lại là [.........] của bản thân nên đại công nghiệp” (C. Mác — Ph. Ăngghen: Toàn tập. Tập 4. Nxb. Chính trị quốc gia Sự thật, Hà Nội, 1995, tr.610):","options":[{"id":"SACH-DO-HUB-Q039-O1","text":"Tính chất"},{"id":"SACH-DO-HUB-Q039-O2","text":"Sản phẩm"},{"id":"SACH-DO-HUB-Q039-O3","text":"Lực lượng"},{"id":"SACH-DO-HUB-Q039-O4","text":"Sự phát triển"}],"correctOptionId":"SACH-DO-HUB-Q039-O2","source":"Sách đỏ HUB (tài liệu lưu hành nội bộ)","explanation":"Trong Tuyên ngôn của Đảng Cộng sản, Mác và Ăngghen xem giai cấp vô sản là “sản phẩm” của nền đại công nghiệp vì chính quá trình phát triển sản xuất tư bản chủ nghĩa tạo ra và mở rộng đội ngũ công nhân công nghiệp.","topic":"Đề ôn theo sách đỏ HUB","examCode":"SACH-DO-HUB","answerStatus":"marked","basis":"Đáp án theo sách đỏ HUB"},{"id":"SACH-DO-HUB-Q040","chapter":0,"number":40,"question":"Chọn phương án KHÔNG ĐÚNG về đặc điểm của giai cấp công nhân?","options":[{"id":"SACH-DO-HUB-Q040-O1","text":"Có lợi ích cơ bản đối lập trực tiếp với lợi ích cơ bản của giai cấp tư sản"},{"id":"SACH-DO-HUB-Q040-O2","text":"Có bản chất quốc tế và bản sắc dân tộc"},{"id":"SACH-DO-HUB-Q040-O3","text":"Có phương thức lao động manh mún, nhỏ lẻ, lạc hậu"},{"id":"SACH-DO-HUB-Q040-O4","text":"Có hệ tư tưởng là chủ nghĩa Mác — Lênin"}],"correctOptionId":"SACH-DO-HUB-Q040-O3","source":"Sách đỏ HUB (tài liệu lưu hành nội bộ)","explanation":"Phương thức lao động manh mún, nhỏ lẻ, lạc hậu không mô tả đặc trưng của giai cấp công nhân hiện đại, vốn gắn với sản xuất công nghiệp có tính tổ chức, xã hội hóa và công nghệ cao. Vì câu hỏi yêu cầu chọn nhận định KHÔNG đúng nên C là đáp án của sách.","topic":"Đề ôn theo sách đỏ HUB","examCode":"SACH-DO-HUB","answerStatus":"marked","basis":"Đáp án theo sách đỏ HUB"},{"id":"SACH-DO-HUB-Q041","chapter":0,"number":41,"question":"Giai cấp công nhân thông qua con đường nào để giải phóng mình và giải phóng nhân dân lao động?","options":[{"id":"SACH-DO-HUB-Q041-O1","text":"Bãi công"},{"id":"SACH-DO-HUB-Q041-O2","text":"Đấu tranh nghị viện"},{"id":"SACH-DO-HUB-Q041-O3","text":"Biểu tình"},{"id":"SACH-DO-HUB-Q041-O4","text":"Cách mạng xã hội chủ nghĩa"}],"correctOptionId":"SACH-DO-HUB-Q041-O4","source":"Sách đỏ HUB (tài liệu lưu hành nội bộ)","explanation":"Theo lý luận Mác - Lênin, việc giải phóng giai cấp công nhân gắn với thay đổi tận gốc quan hệ sản xuất và quyền lực chính trị, chứ không chỉ đòi cải thiện từng điều kiện lao động. Vì vậy, cách mạng xã hội chủ nghĩa được xác định là con đường căn bản.","topic":"Đề ôn theo sách đỏ HUB","examCode":"SACH-DO-HUB","answerStatus":"marked","basis":"Đáp án theo sách đỏ HUB"},{"id":"SACH-DO-HUB-Q042","chapter":0,"number":42,"question":"Giai cấp công nhân là người lao động gắn với nền sản xuất:","options":[{"id":"SACH-DO-HUB-Q042-O1","text":"Công nghiệp hiện đại"},{"id":"SACH-DO-HUB-Q042-O2","text":"Thủ công nghiệp"},{"id":"SACH-DO-HUB-Q042-O3","text":"Nông nghiệp"},{"id":"SACH-DO-HUB-Q042-O4","text":"Đại nông nghiệp"}],"correctOptionId":"SACH-DO-HUB-Q042-O1","source":"Sách đỏ HUB (tài liệu lưu hành nội bộ)","explanation":"Giai cấp công nhân hiện đại gắn liền với quá trình sản xuất công nghiệp sử dụng máy móc và công nghệ, có tính tổ chức và xã hội hóa cao. Đây là tiêu chí về phương thức lao động phân biệt họ với người lao động thủ công hay nông nghiệp truyền thống.","topic":"Đề ôn theo sách đỏ HUB","examCode":"SACH-DO-HUB","answerStatus":"marked","basis":"Đáp án theo sách đỏ HUB"},{"id":"SACH-DO-HUB-Q043","chapter":0,"number":43,"question":"Trong CNTB, giai cấp duy nhất không có lợi ích riêng với nghĩa tư hữu là giai cấp nào?","options":[{"id":"SACH-DO-HUB-Q043-O1","text":"Địa chủ"},{"id":"SACH-DO-HUB-Q043-O2","text":"Vô sản"},{"id":"SACH-DO-HUB-Q043-O3","text":"Tư sản"},{"id":"SACH-DO-HUB-Q043-O4","text":"Nông dân"}],"correctOptionId":"SACH-DO-HUB-Q043-O2","source":"Sách đỏ HUB (tài liệu lưu hành nội bộ)","explanation":"Theo quan điểm của Mác, giai cấp vô sản không sở hữu tư liệu sản xuất chủ yếu và không có lợi ích duy trì chế độ tư hữu tư bản chủ nghĩa. Vì vậy, việc giải phóng giai cấp này gắn với thay đổi chế độ sở hữu và quan hệ sản xuất hiện có.","topic":"Đề ôn theo sách đỏ HUB","examCode":"SACH-DO-HUB","answerStatus":"marked","basis":"Đáp án theo sách đỏ HUB"},{"id":"SACH-DO-HUB-Q044","chapter":0,"number":44,"question":"“Thực hiện dân chủ, công bằng, bình đẳng và tiến bộ xã hội theo lý tưởng và mục tiêu của chủ nghĩa xã hội” - là sứ mệnh lịch sử của giai cấp công nhân thuộc nội dung:","options":[{"id":"SACH-DO-HUB-Q044-O1","text":"Văn hóa, tư tưởng"},{"id":"SACH-DO-HUB-Q044-O2","text":"Kinh tế"},{"id":"SACH-DO-HUB-Q044-O3","text":"Chính trị - xã hội"},{"id":"SACH-DO-HUB-Q044-O4","text":"Quốc phòng, an ninh"}],"correctOptionId":"SACH-DO-HUB-Q044-O3","source":"Sách đỏ HUB (tài liệu lưu hành nội bộ)","explanation":"Các mục tiêu dân chủ, công bằng, bình đẳng và tiến bộ xã hội liên quan trực tiếp tới tổ chức quyền lực và quan hệ giữa các giai cấp, nhóm xã hội. Do đó, câu hỏi xếp nội dung này vào phương diện chính trị - xã hội của sứ mệnh lịch sử.","topic":"Đề ôn theo sách đỏ HUB","examCode":"SACH-DO-HUB","answerStatus":"marked","basis":"Đáp án theo sách đỏ HUB"},{"id":"SACH-DO-HUB-Q045","chapter":0,"number":45,"question":"Tập trung xây dựng hệ giá trị mới: lao động, công bằng, dân chủ, bình đẳng và tự do - là sứ mệnh lịch sử của giai cấp công nhân thuộc nội dung:","options":[{"id":"SACH-DO-HUB-Q045-O1","text":"Quốc phòng, an ninh"},{"id":"SACH-DO-HUB-Q045-O2","text":"Kinh tế"},{"id":"SACH-DO-HUB-Q045-O3","text":"Chính trị - xã hội"},{"id":"SACH-DO-HUB-Q045-O4","text":"Văn hóa, tư tưởng"}],"correctOptionId":"SACH-DO-HUB-Q045-O4","source":"Sách đỏ HUB (tài liệu lưu hành nội bộ)","explanation":"Việc xây dựng hệ giá trị lao động, công bằng, dân chủ, bình đẳng và tự do chủ yếu là định hướng các chuẩn mực, niềm tin và lối sống xã hội. Vì vậy, đây thuộc phương diện văn hóa - tư tưởng của sứ mệnh lịch sử giai cấp công nhân.","topic":"Đề ôn theo sách đỏ HUB","examCode":"SACH-DO-HUB","answerStatus":"marked","basis":"Đáp án theo sách đỏ HUB"},{"id":"SACH-DO-HUB-Q046","chapter":0,"number":46,"question":"Theo Các Mác, những người vô sản có thể hành động với tư cách là một giai cấp khi nào?","options":[{"id":"SACH-DO-HUB-Q046-O1","text":"Khi đạt tới sự giác độ về địa vị lịch sử của khả năng hành động chính trị"},{"id":"SACH-DO-HUB-Q046-O2","text":"Khi thiết lập chính quyền chuyên chính vô sản"},{"id":"SACH-DO-HUB-Q046-O3","text":"Khi đã liên kết với giai cấp nông dân và tầng lớp trí thức"},{"id":"SACH-DO-HUB-Q046-O4","text":"Khi giành lấy toàn bộ tư liệu sản xuất của giai cấp tư sản"}],"correctOptionId":"SACH-DO-HUB-Q046-O1","source":"Sách đỏ HUB (tài liệu lưu hành nội bộ)","explanation":"Một tập hợp người lao động chỉ trở thành giai cấp có khả năng hành động chính trị độc lập khi ý thức được địa vị, lợi ích và vai trò lịch sử chung. Sự giác ngộ này cho phép họ tổ chức đấu tranh như một lực lượng giai cấp, thay vì hành động riêng lẻ.","topic":"Đề ôn theo sách đỏ HUB","examCode":"SACH-DO-HUB","answerStatus":"marked","basis":"Đáp án theo sách đỏ HUB"},{"id":"SACH-DO-HUB-Q047","chapter":0,"number":47,"question":"Nguyên nhân cơ bản làm cho giai cấp nông dân không thể đảm nhận sứ mệnh lịch sử chuyên biên từ xã hội TBCN lên xã hội XHCN?","options":[{"id":"SACH-DO-HUB-Q047-O1","text":"Họ mang tính tư hữu cao"},{"id":"SACH-DO-HUB-Q047-O2","text":"Họ không đại diện cho phương thức sản xuất tiến bộ"},{"id":"SACH-DO-HUB-Q047-O3","text":"Họ không có hệ tư tưởng riêng độc lập"},{"id":"SACH-DO-HUB-Q047-O4","text":"Họ không có chính đảng riêng độc lập"}],"correctOptionId":"SACH-DO-HUB-Q047-O2","source":"Sách đỏ HUB (tài liệu lưu hành nội bộ)","explanation":"Theo lập luận của giáo trình, giai cấp nông dân gắn chủ yếu với nền sản xuất nhỏ, không đại diện cho phương thức sản xuất công nghiệp tiến bộ giữ vai trò trung tâm trong quá trình thay thế chủ nghĩa tư bản. Vì thế, họ không được xác định là lực lượng tự mình đảm nhận sứ mệnh lịch sử ấy.","topic":"Đề ôn theo sách đỏ HUB","examCode":"SACH-DO-HUB","answerStatus":"marked","basis":"Đáp án theo sách đỏ HUB"},{"id":"SACH-DO-HUB-Q048","chapter":0,"number":48,"question":"Giai cấp nào ở Việt Nam ra đời và phát triển gắn liền với chính sách khai thác thuộc địa của thực dân Pháp ở Việt Nam?","options":[{"id":"SACH-DO-HUB-Q048-O1","text":"Nông dân"},{"id":"SACH-DO-HUB-Q048-O2","text":"Địa chủ"},{"id":"SACH-DO-HUB-Q048-O3","text":"Công nhân"},{"id":"SACH-DO-HUB-Q048-O4","text":"Tư sản"}],"correctOptionId":"SACH-DO-HUB-Q048-O3","source":"Sách đỏ HUB (tài liệu lưu hành nội bộ)","explanation":"Chính sách khai thác thuộc địa của thực dân Pháp đã mở mỏ, đồn điền, nhà máy, đường sắt và cơ sở công nghiệp ở Việt Nam. Quá trình đó tạo ra đội ngũ lao động làm thuê công nghiệp, làm hình thành và phát triển giai cấp công nhân Việt Nam.","topic":"Đề ôn theo sách đỏ HUB","examCode":"SACH-DO-HUB","answerStatus":"marked","basis":"Đáp án theo sách đỏ HUB"},{"id":"SACH-DO-HUB-Q049","chapter":0,"number":49,"question":"Chọn phương án KHÔNG ĐÚNG về đặc điểm của giai cấp công nhân Việt Nam:","options":[{"id":"SACH-DO-HUB-Q049-O1","text":"Có truyền thống yêu nước"},{"id":"SACH-DO-HUB-Q049-O2","text":"Phần lớn xuất thân từ nông dân"},{"id":"SACH-DO-HUB-Q049-O3","text":"Chịu ba tầng áp bức bóc lột"},{"id":"SACH-DO-HUB-Q049-O4","text":"Ra đời sau giai cấp tư sản dân tộc"}],"correctOptionId":"SACH-DO-HUB-Q049-O4","source":"Sách đỏ HUB (tài liệu lưu hành nội bộ)","explanation":"Đặc điểm lịch sử của Việt Nam là giai cấp công nhân ra đời sớm hơn giai cấp tư sản dân tộc. Do vậy, phát biểu “ra đời sau giai cấp tư sản dân tộc” trái với thực tế được trình bày trong giáo trình; câu hỏi yêu cầu chọn phát biểu KHÔNG đúng.","topic":"Đề ôn theo sách đỏ HUB","examCode":"SACH-DO-HUB","answerStatus":"marked","basis":"Đáp án theo sách đỏ HUB"},{"id":"SACH-DO-HUB-Q050","chapter":0,"number":50,"question":"Trong bối cảnh hiện nay, điểm then chốt để thực hiện thành công sứ mệnh lịch sử của giai cấp công nhân Việt Nam là:","options":[{"id":"SACH-DO-HUB-Q050-O1","text":"Xây dựng, chỉnh đốn Đảng Cộng sản Việt Nam thực sự trong sạch, vững mạnh"},{"id":"SACH-DO-HUB-Q050-O2","text":"Đa dạng hóa cơ cấu nghề nghiệp của giai cấp công nhân"},{"id":"SACH-DO-HUB-Q050-O3","text":"Xây dựng nền kinh tế tri thức"},{"id":"SACH-DO-HUB-Q050-O4","text":"Đa dạng hóa cơ cấu trình độ học vấn và tay nghề bậc thợ của giai cấp công nhân"}],"correctOptionId":"SACH-DO-HUB-Q050-O1","source":"Sách đỏ HUB (tài liệu lưu hành nội bộ)","explanation":"Sứ mệnh lịch sử cần sự lãnh đạo có tổ chức, đường lối và năng lực tập hợp lực lượng. Vì vậy, việc xây dựng, chỉnh đốn Đảng Cộng sản Việt Nam trong sạch, vững mạnh được xem là điểm then chốt bảo đảm vai trò lãnh đạo trong bối cảnh hiện nay.","topic":"Đề ôn theo sách đỏ HUB","examCode":"SACH-DO-HUB","answerStatus":"marked","basis":"Đáp án theo sách đỏ HUB"},{"id":"SACH-DO-HUB-Q051","chapter":0,"number":51,"question":"Đặc điểm nổi bật và bao trùm của thời kỳ quá độ lên CNXH là:","options":[{"id":"SACH-DO-HUB-Q051-O1","text":"Kết cấu giai cấp trong xã hội đa dạng và phức tạp."},{"id":"SACH-DO-HUB-Q051-O2","text":"Tồn tại những yếu tố của xã hội cũ bên cạnh những nhân tố mới của chủ nghĩa xã hội"},{"id":"SACH-DO-HUB-Q051-O3","text":"Tồn tại nhiều yếu tố văn hóa và tư tưởng khác nhau."},{"id":"SACH-DO-HUB-Q051-O4","text":"Tồn tại một nền kinh tế nhiều thành phần"}],"correctOptionId":"SACH-DO-HUB-Q051-O2","source":"Sách đỏ HUB (tài liệu lưu hành nội bộ)","explanation":"Thời kỳ quá độ chưa phải xã hội mới hoàn chỉnh: những quan hệ, tập quán và cơ cấu từ xã hội cũ vẫn tồn tại bên cạnh những yếu tố xã hội chủ nghĩa đang hình thành. Tính đan xen giữa “cũ” và “mới” là đặc điểm bao trùm của thời kỳ này.","topic":"Đề ôn theo sách đỏ HUB","examCode":"SACH-DO-HUB","answerStatus":"marked","basis":"Đáp án theo sách đỏ HUB"},{"id":"SACH-DO-HUB-Q052","chapter":0,"number":52,"question":"Phân phối theo lao động là hình thức phân phối cơ bản của xã hội nào?","options":[{"id":"SACH-DO-HUB-Q052-O1","text":"cộng sản chủ nghĩa"},{"id":"SACH-DO-HUB-Q052-O2","text":"tư bản chủ nghĩa"},{"id":"SACH-DO-HUB-Q052-O3","text":"xã hội chủ nghĩa"},{"id":"SACH-DO-HUB-Q052-O4","text":"chiếm hữu nô lệ"}],"correctOptionId":"SACH-DO-HUB-Q052-O3","source":"Sách đỏ HUB (tài liệu lưu hành nội bộ)","explanation":"Trong giai đoạn xã hội chủ nghĩa, lao động vẫn là thước đo quan trọng để phân phối một phần kết quả sản xuất theo đóng góp của mỗi người. Do đó, phân phối theo lao động được xem là nguyên tắc phân phối cơ bản, khác nguyên tắc hưởng theo nhu cầu ở giai đoạn cộng sản chủ nghĩa phát triển cao.","topic":"Đề ôn theo sách đỏ HUB","examCode":"SACH-DO-HUB","answerStatus":"marked","basis":"Đáp án theo sách đỏ HUB"},{"id":"SACH-DO-HUB-Q053","chapter":0,"number":53,"question":"Theo Lênin, hình thái kinh tế - xã hội cộng sản chủ nghĩa có những thời kỳ nào:","options":[{"id":"SACH-DO-HUB-Q053-O1","text":"Chủ nghĩa xã hội và cộng sản chủ nghĩa"},{"id":"SACH-DO-HUB-Q053-O2","text":"Quá độ lên chủ nghĩa xã hội và chủ nghĩa cộng sản"},{"id":"SACH-DO-HUB-Q053-O3","text":"Quá độ lên chủ nghĩa xã hội, chủ nghĩa xã hội giai đoạn thấp, chủ nghĩa xã hội phát triển cao và cộng sản chủ nghĩa"},{"id":"SACH-DO-HUB-Q053-O4","text":"Quá độ lên chủ nghĩa xã hội, chủ nghĩa xã hội và chủ nghĩa cộng sản"}],"correctOptionId":"SACH-DO-HUB-Q053-O4","source":"Sách đỏ HUB (tài liệu lưu hành nội bộ)","explanation":"Theo cách phân chia trong câu hỏi, tiến trình hình thái kinh tế - xã hội cộng sản chủ nghĩa được trình bày qua thời kỳ quá độ, giai đoạn xã hội chủ nghĩa và giai đoạn cộng sản chủ nghĩa. Cách chia này làm rõ sự chuyển tiếp và phát triển dần của chế độ mới.","topic":"Đề ôn theo sách đỏ HUB","examCode":"SACH-DO-HUB","answerStatus":"marked","basis":"Đáp án theo sách đỏ HUB"},{"id":"SACH-DO-HUB-Q054","chapter":0,"number":54,"question":"Thời kỳ quá độ lên CNXH bắt đầu khi:","options":[{"id":"SACH-DO-HUB-Q054-O1","text":"Giai cấp công nhân và nhân dân lao động giành được chính quyền nhà nước"},{"id":"SACH-DO-HUB-Q054-O2","text":"Diễn ra cuộc cách mạng dân chủ tư sản kiểu mới"},{"id":"SACH-DO-HUB-Q054-O3","text":"Có đấu tranh giai cấp"},{"id":"SACH-DO-HUB-Q054-O4","text":"Nền sản xuất hàng hóa ra đời"}],"correctOptionId":"SACH-DO-HUB-Q054-O1","source":"Sách đỏ HUB (tài liệu lưu hành nội bộ)","explanation":"Khi giai cấp công nhân và nhân dân lao động giành được chính quyền nhà nước, họ có công cụ quyền lực để bắt đầu cải biến quan hệ kinh tế, chính trị và xã hội. Vì vậy, mốc giành chính quyền được coi là điểm mở đầu thời kỳ quá độ lên chủ nghĩa xã hội.","topic":"Đề ôn theo sách đỏ HUB","examCode":"SACH-DO-HUB","answerStatus":"marked","basis":"Đáp án theo sách đỏ HUB"},{"id":"SACH-DO-HUB-Q055","chapter":0,"number":55,"question":"Thời kỳ quá độ lên CNXH ở Việt Nam là bước quá độ:","options":[{"id":"SACH-DO-HUB-Q055-O1","text":"Trực tiếp, từ chế độ tư bản chủ nghĩa lên chế độ xã hội chủ nghĩa"},{"id":"SACH-DO-HUB-Q055-O2","text":"Gián tiếp, bỏ qua chế độ tư bản chủ nghĩa tiến lên chủ nghĩa xã hội"},{"id":"SACH-DO-HUB-Q055-O3","text":"Gián tiếp, bỏ qua chế độ phong kiến tiến lên chế độ xã hội chủ nghĩa"},{"id":"SACH-DO-HUB-Q055-O4","text":"Trực tiếp, từ chế độ phong kiến tiến lên chế độ xã hội chủ nghĩa."}],"correctOptionId":"SACH-DO-HUB-Q055-O2","source":"Sách đỏ HUB (tài liệu lưu hành nội bộ)","explanation":"Theo định hướng được trình bày trong giáo trình, Việt Nam quá độ lên chủ nghĩa xã hội từ nền sản xuất còn thấp, không trải qua việc xác lập đầy đủ chế độ tư bản chủ nghĩa với tư cách chế độ xã hội thống trị. Đây được gọi là bước quá độ gián tiếp, bỏ qua chế độ tư bản chủ nghĩa.","topic":"Đề ôn theo sách đỏ HUB","examCode":"SACH-DO-HUB","answerStatus":"marked","basis":"Đáp án theo sách đỏ HUB"},{"id":"SACH-DO-HUB-Q056","chapter":0,"number":56,"question":"Tiền đề kinh tế - xã hội dẫn tới sự sụp đổ không thể tránh khỏi của CNTB và sự ra đời của CNXH là:","options":[{"id":"SACH-DO-HUB-Q056-O1","text":"Quá trình công hữu hóa các tư liệu sản xuất chủ yếu"},{"id":"SACH-DO-HUB-Q056-O2","text":"Sự hình thành quan hệ sản xuất xã hội chủ nghĩa"},{"id":"SACH-DO-HUB-Q056-O3","text":"Sự phát triển của lực lượng sản xuất và sự trưởng thành của giai cấp công nhân"},{"id":"SACH-DO-HUB-Q056-O4","text":"Sự hình thành nền chuyên chính cách mạng của giai cấp vô sản"}],"correctOptionId":"SACH-DO-HUB-Q056-O3","source":"Sách đỏ HUB (tài liệu lưu hành nội bộ)","explanation":"Khi lực lượng sản xuất phát triển, mâu thuẫn với quan hệ sản xuất tư bản chủ nghĩa ngày càng bộc lộ; đồng thời giai cấp công nhân trưởng thành về số lượng, tổ chức và ý thức. Theo lý luận Mác - Lênin, đây là tiền đề kinh tế - xã hội quan trọng cho sự chuyển biến sang xã hội mới.","topic":"Đề ôn theo sách đỏ HUB","examCode":"SACH-DO-HUB","answerStatus":"marked","basis":"Đáp án theo sách đỏ HUB"},{"id":"SACH-DO-HUB-Q057","chapter":0,"number":57,"question":"Thời kỳ quá độ lên CNXH ở miền Bắc nước ta bắt đầu từ năm:","options":[{"id":"SACH-DO-HUB-Q057-O1","text":"1975"},{"id":"SACH-DO-HUB-Q057-O2","text":"1945"},{"id":"SACH-DO-HUB-Q057-O3","text":"1930"},{"id":"SACH-DO-HUB-Q057-O4","text":"1954"}],"correctOptionId":"SACH-DO-HUB-Q057-O4","source":"Sách đỏ HUB (tài liệu lưu hành nội bộ)","explanation":"Năm 1954, sau Hiệp định Genève và việc miền Bắc được giải phóng, miền Bắc Việt Nam bắt đầu bước vào thời kỳ quá độ lên chủ nghĩa xã hội. Mốc này chỉ áp dụng cho miền Bắc, khác với mốc năm 1975 xét trên phạm vi cả nước.","topic":"Đề ôn theo sách đỏ HUB","examCode":"SACH-DO-HUB","answerStatus":"marked","basis":"Đáp án theo sách đỏ HUB"},{"id":"SACH-DO-HUB-Q058","chapter":0,"number":58,"question":"Thời kỳ quá độ lên CNXH ở Việt Nam được diễn ra trong cả nước bắt đầu từ năm:","options":[{"id":"SACH-DO-HUB-Q058-O1","text":"1945"},{"id":"SACH-DO-HUB-Q058-O2","text":"1975"},{"id":"SACH-DO-HUB-Q058-O3","text":"1954"},{"id":"SACH-DO-HUB-Q058-O4","text":"1930"}],"correctOptionId":"SACH-DO-HUB-Q058-O2","source":"Sách đỏ HUB (tài liệu lưu hành nội bộ)","explanation":"Năm 1975, đất nước thống nhất về mặt lãnh thổ sau thắng lợi của cuộc kháng chiến chống Mỹ. Theo cách xác định của tài liệu, từ mốc này nhiệm vụ quá độ lên chủ nghĩa xã hội được đặt ra trên phạm vi cả nước, thay vì chỉ miền Bắc.","topic":"Đề ôn theo sách đỏ HUB","examCode":"SACH-DO-HUB","answerStatus":"marked","basis":"Đáp án theo sách đỏ HUB"},{"id":"SACH-DO-HUB-Q059","chapter":0,"number":59,"question":"Theo Lênin, mục đích cao nhất, cuối cùng của những cải tạo XHCN là thực hiện nguyên tắc:","options":[{"id":"SACH-DO-HUB-Q059-O1","text":"Làm theo năng lực, hưởng theo nhu cầu"},{"id":"SACH-DO-HUB-Q059-O2","text":"Lam theo năng lực, hưởng theo lao động"},{"id":"SACH-DO-HUB-Q059-O3","text":"Làm theo năng lực, hưởng theo tài san đóng góp"},{"id":"SACH-DO-HUB-Q059-O4","text":"Làm theo năng lực, hưởng theo nguồn gốc xuất thân"}],"correctOptionId":"SACH-DO-HUB-Q059-O1","source":"Sách đỏ HUB (tài liệu lưu hành nội bộ)","explanation":"Nguyên tắc “làm theo năng lực, hưởng theo nhu cầu” thể hiện mục tiêu phân phối ở trình độ phát triển cao của xã hội cộng sản, khi năng lực sản xuất đủ để đáp ứng những nhu cầu chính đáng. Vì vậy, Lênin xem đây là đích hướng tới của quá trình cải tạo xã hội chủ nghĩa.","topic":"Đề ôn theo sách đỏ HUB","examCode":"SACH-DO-HUB","answerStatus":"marked","basis":"Đáp án theo sách đỏ HUB"},{"id":"SACH-DO-HUB-Q060","chapter":0,"number":60,"question":"Chọn phương án đúng cho cụm từ còn thiếu: “cuộc cách mạng của giai cấp vô sản đang có tất cả những triệu chứng là sắp nổ ra, sẽ chỉ có thể cải tạo xã hội hiện nay một cách dần dần, và chỉ khi nào đã tạo nên được một khối lượng [......] cần thiết cho việc cải tạo đó thì khi ấy mới thủ tiêu được chế độ tư hữu” (C. Mác & Ph. Ăngghen: Toàn tập. Tập 4. Nxb. Chính trị quốc gia, Hà Nội, 2002, tr.469)","options":[{"id":"SACH-DO-HUB-Q060-O1","text":"Tư liệu tiêu dùng"},{"id":"SACH-DO-HUB-Q060-O2","text":"Tư liệu sản xuất"},{"id":"SACH-DO-HUB-Q060-O3","text":"Giá tri thang dư"},{"id":"SACH-DO-HUB-Q060-O4","text":"Giá tri sức lao động"}],"correctOptionId":"SACH-DO-HUB-Q060-O2","source":"Sách đỏ HUB (tài liệu lưu hành nội bộ)","explanation":"Đoạn trích nói đến việc chỉ có thể thủ tiêu chế độ tư hữu khi đã tạo ra một khối lượng điều kiện vật chất cần thiết. “Tư liệu sản xuất” là máy móc, công cụ, nhà xưởng và phương tiện phục vụ sản xuất, nên phù hợp với ý rằng cần xây dựng cơ sở sản xuất vật chất trước khi cải biến chế độ sở hữu.","topic":"Đề ôn theo sách đỏ HUB","examCode":"SACH-DO-HUB","answerStatus":"marked","basis":"Đáp án theo sách đỏ HUB"},{"id":"SACH-DO-HUB-Q061","chapter":0,"number":61,"question":"Đặc trưng thể hiện thuộc tính bản chất của CNXH là:","options":[{"id":"SACH-DO-HUB-Q061-O1","text":"Chế độ xã hội do nhân dân lao động làm chủ"},{"id":"SACH-DO-HUB-Q061-O2","text":"Giải phóng giai cấp, giải phóng dân tộc, giải phóng xã hội, giải phóng con người, tạo điều kiện để con người phát triển toàn diện"},{"id":"SACH-DO-HUB-Q061-O3","text":"Có nền kinh tế phát triển cao dựa trên lực lượng sản xuất hiện đại và chế độ công hữu về tư liệu sản xuất chủ yếu"},{"id":"SACH-DO-HUB-Q061-O4","text":"Có nhà nước kiểu mới mang bản chất giai cấp công nhân, đại biểu cho lợi ích, quyền lực và ý chí của nhân dân lao động"}],"correctOptionId":"SACH-DO-HUB-Q061-O1","source":"Sách đỏ HUB (tài liệu lưu hành nội bộ)","explanation":"Điểm cốt lõi trong quan niệm xã hội chủ nghĩa của giáo trình là nhân dân lao động trở thành chủ thể của quyền lực và đời sống xã hội. Vì vậy, “chế độ xã hội do nhân dân lao động làm chủ” được chọn để thể hiện thuộc tính bản chất mang tính tổng quát.","topic":"Đề ôn theo sách đỏ HUB","examCode":"SACH-DO-HUB","answerStatus":"marked","basis":"Đáp án theo sách đỏ HUB"},{"id":"SACH-DO-HUB-Q062","chapter":0,"number":62,"question":"Đặc trưng về phương diện kinh tế của CNXH là:","options":[{"id":"SACH-DO-HUB-Q062-O1","text":"Chế độ xã hội do nhân dân lao động làm chủ"},{"id":"SACH-DO-HUB-Q062-O2","text":"Giải phóng giai cấp, giải phóng dân tộc, giải phóng xã hội, giải phóng con người, tạo điều kiện để con người phát triển toàn diện"},{"id":"SACH-DO-HUB-Q062-O3","text":"Có nén kinh tế phát triển cao dựa trên lực lượng sản xuất hiện đại và chế độ công hữu về tư liệu sản xuất chủ yếu"},{"id":"SACH-DO-HUB-Q062-O4","text":"Có nhà nước kiểu mới mang bản chất giai cấp công nhân, đại biểu cho lợi ích, quyền lực và ý chí của nhân dân lao động"}],"correctOptionId":"SACH-DO-HUB-Q062-O3","source":"Sách đỏ HUB (tài liệu lưu hành nội bộ)","explanation":"Xét riêng phương diện kinh tế, chủ nghĩa xã hội được mô tả qua lực lượng sản xuất hiện đại và chế độ công hữu đối với tư liệu sản xuất chủ yếu. Một vế phản ánh trình độ phát triển sản xuất, vế còn lại phản ánh nền tảng quan hệ sở hữu của chế độ xã hội.","topic":"Đề ôn theo sách đỏ HUB","examCode":"SACH-DO-HUB","answerStatus":"marked","basis":"Đáp án theo sách đỏ HUB"},{"id":"SACH-DO-HUB-Q063","chapter":0,"number":63,"question":"Đặc điểm lớn nhất của thời kỳ quá độ lên CNXH ở nước ta là:","options":[{"id":"SACH-DO-HUB-Q063-O1","text":"Lực lượng sản xuất chưa phát triển"},{"id":"SACH-DO-HUB-Q063-O2","text":"Từ một nền sản xuất nhỏ là phổ biến quá độ lên chủ nghĩa xã hội không qua chế độ tư bản chủ nghĩa"},{"id":"SACH-DO-HUB-Q063-O3","text":"Nhiều thành phần xã hội đan xen ton tại"},{"id":"SACH-DO-HUB-Q063-O4","text":"Năng suất lao động thấp"}],"correctOptionId":"SACH-DO-HUB-Q063-O2","source":"Sách đỏ HUB (tài liệu lưu hành nội bộ)","explanation":"Việt Nam tiến lên chủ nghĩa xã hội trong điều kiện nền sản xuất nhỏ còn phổ biến và chưa trải qua sự phát triển tư bản chủ nghĩa đầy đủ. Đó là đặc điểm xuất phát có tính bao trùm, chi phối những khó khăn và yêu cầu phát triển lực lượng sản xuất trong thời kỳ quá độ.","topic":"Đề ôn theo sách đỏ HUB","examCode":"SACH-DO-HUB","answerStatus":"marked","basis":"Đáp án theo sách đỏ HUB"},{"id":"SACH-DO-HUB-Q064","chapter":0,"number":64,"question":"Thời kỳ quá độ lên CNXH diễn ra cuộc đấu tranh gay gắt giữa:","options":[{"id":"SACH-DO-HUB-Q064-O1","text":"giai cấp công nhân và nhân dân lao động vừa giành được chính quyền nhà nước với giai cấp bóc lột và các thê lực phản động mới bị đánh đổ."},{"id":"SACH-DO-HUB-Q064-O2","text":"giai cấp nông nhân và nhân dân lao động vừa giành được chính quyền nhà nước với giai cấp bóc lột và các thê lực phản động mới bị đánh đổ."},{"id":"SACH-DO-HUB-Q064-O3","text":"tầng lớp tiểu tư sản và nhân dân lao động vừa giành được chính quyền nhà nước với giai cấp bóc lột và các thê lực phản động mới bị đánh đổ."},{"id":"SACH-DO-HUB-Q064-O4","text":"giai cấp tư sản và nhân dân lao động vừa giành được chính quyền nhà nước với giai cấp bóc lột và các thê lực phản động mới bị đánh đổ."}],"correctOptionId":"SACH-DO-HUB-Q064-O1","source":"Sách đỏ HUB (tài liệu lưu hành nội bộ)","explanation":"Sau khi giành chính quyền, giai cấp công nhân và nhân dân lao động phải bảo vệ thành quả cách mạng và xây dựng quan hệ xã hội mới. Quá trình này diễn ra trong bối cảnh các giai cấp bóc lột cũ và lực lượng phản động chưa biến mất ngay, nên còn đấu tranh gay gắt.","topic":"Đề ôn theo sách đỏ HUB","examCode":"SACH-DO-HUB","answerStatus":"marked","basis":"Đáp án theo sách đỏ HUB"},{"id":"SACH-DO-HUB-Q065","chapter":0,"number":65,"question":"C. Mác và Ph. Ăngghen coi sự chuyển biến từ hình thái kinh tế - xã hội thấp lên hình thái kinh tế - xã hội cao là:","options":[{"id":"SACH-DO-HUB-Q065-O1","text":"Một quá trình lịch sử"},{"id":"SACH-DO-HUB-Q065-O2","text":"Một quá trình lịch sử - tự nhiên"},{"id":"SACH-DO-HUB-Q065-O3","text":"Một quá trình tự nhiên"},{"id":"SACH-DO-HUB-Q065-O4","text":"Một quá trình phát triển văn hóa - xã hội"}],"correctOptionId":"SACH-DO-HUB-Q065-O2","source":"Sách đỏ HUB (tài liệu lưu hành nội bộ)","explanation":"Theo chủ nghĩa duy vật lịch sử, các hình thái kinh tế - xã hội biến đổi theo quy luật khách quan nảy sinh từ sự vận động của lực lượng sản xuất và quan hệ sản xuất, nhưng vẫn diễn ra qua hoạt động thực tiễn của con người. Vì vậy, Mác và Ăngghen gọi đó là quá trình “lịch sử - tự nhiên”.","topic":"Đề ôn theo sách đỏ HUB","examCode":"SACH-DO-HUB","answerStatus":"marked","basis":"Đáp án theo sách đỏ HUB"},{"id":"SACH-DO-HUB-Q066","chapter":0,"number":66,"question":"“Sự xuất hiện của hình thái kinh tế - xã hội cộng sản chủ nghĩa từ những nước TBCN phát triển” là quan điểm của ai?","options":[{"id":"SACH-DO-HUB-Q066-O1","text":"Stalin"},{"id":"SACH-DO-HUB-Q066-O2","text":"Lênin"},{"id":"SACH-DO-HUB-Q066-O3","text":"C. Mác, Ph. Ăngghen"},{"id":"SACH-DO-HUB-Q066-O4","text":"Hồ Chí Minh"}],"correctOptionId":"SACH-DO-HUB-Q066-O3","source":"Sách đỏ HUB (tài liệu lưu hành nội bộ)","explanation":"Trong phân tích kinh điển của Mác và Ăngghen, hình thái cộng sản chủ nghĩa được luận giải từ những mâu thuẫn nảy sinh ở chủ nghĩa tư bản đã phát triển. Do đó, phương án ghi tên C. Mác và Ph. Ăngghen phù hợp với nhận định được trích dẫn.","topic":"Đề ôn theo sách đỏ HUB","examCode":"SACH-DO-HUB","answerStatus":"marked","basis":"Đáp án theo sách đỏ HUB"},{"id":"SACH-DO-HUB-Q067","chapter":0,"number":67,"question":"“Sự xuất hiện của hình thái kinh tế - xã hội cộng sản chủ nghĩa ở các nước tư bản có trình độ phát triển trung bình và những nước thuộc địa sau khi được giải phóng do giai cấp công nhân lãnh đạo” là quan điểm của ai?","options":[{"id":"SACH-DO-HUB-Q067-O1","text":"Hồ Chí Minh"},{"id":"SACH-DO-HUB-Q067-O2","text":"Ph. Ăngghen"},{"id":"SACH-DO-HUB-Q067-O3","text":"C. Mác"},{"id":"SACH-DO-HUB-Q067-O4","text":"Lênin"}],"correctOptionId":"SACH-DO-HUB-Q067-O4","source":"Sách đỏ HUB (tài liệu lưu hành nội bộ)","explanation":"Lênin phát triển lý luận cách mạng trong điều kiện chủ nghĩa tư bản phát triển không đều và phong trào giải phóng thuộc địa. Vì vậy, quan điểm về khả năng xuất hiện chế độ mới ở các nước tư bản trình độ trung bình hoặc nước thuộc địa được gắn với Lênin.","topic":"Đề ôn theo sách đỏ HUB","examCode":"SACH-DO-HUB","answerStatus":"marked","basis":"Đáp án theo sách đỏ HUB"},{"id":"SACH-DO-HUB-Q068","chapter":0,"number":68,"question":"Chọn phương án đúng cho cụm từ còn thiếu: “Giai cấp tư sản, trong quá trình thống trị giai cấp chưa đầy một thế kỷ, đã tạo ra những [.........] nhiều hơn và đồ sộ hơn [.........] của tất cả các thế hệ trước kia gộp lại” (C. Mác và Ph. Ăngghen: Tuyển tập. Tập 1. Nxb Sự thật, Hà Nội, 1980, tr.557)","options":[{"id":"SACH-DO-HUB-Q068-O1","text":"Lực lượng sản xuất"},{"id":"SACH-DO-HUB-Q068-O2","text":"Năng suất lao động"},{"id":"SACH-DO-HUB-Q068-O3","text":"Quan hệ sản xuất"},{"id":"SACH-DO-HUB-Q068-O4","text":"Cơ sở hạ tầng"}],"correctOptionId":"SACH-DO-HUB-Q068-O1","source":"Sách đỏ HUB (tài liệu lưu hành nội bộ)","explanation":"Câu trích nhấn mạnh sức phát triển rất lớn của nền sản xuất tư bản chủ nghĩa trong thời gian ngắn. “Lực lượng sản xuất” bao gồm người lao động, tư liệu sản xuất và năng lực kỹ thuật, là phạm trù phù hợp khi nói đến thành tựu vật chất mà giai cấp tư sản tạo ra.","topic":"Đề ôn theo sách đỏ HUB","examCode":"SACH-DO-HUB","answerStatus":"marked","basis":"Đáp án theo sách đỏ HUB"},{"id":"SACH-DO-HUB-Q069","chapter":0,"number":69,"question":"Theo Mác - Ăngghen, điểm giống nhau giữa các giai đoạn của hình thái kinh tế - xã hội cộng sản chủ nghĩa là:","options":[{"id":"SACH-DO-HUB-Q069-O1","text":"Đều không tồn tại nhà nước"},{"id":"SACH-DO-HUB-Q069-O2","text":"Déu dựa trên chế độ công hữu về tư liệu sản xuất"},{"id":"SACH-DO-HUB-Q069-O3","text":"Đều không còn đấu tranh giai cấp"},{"id":"SACH-DO-HUB-Q069-O4","text":"Đều không còn chế độ người bóc lột người"}],"correctOptionId":"SACH-DO-HUB-Q069-O2","source":"Sách đỏ HUB (tài liệu lưu hành nội bộ)","explanation":"Theo cách trình bày của giáo trình, các giai đoạn của hình thái kinh tế - xã hội cộng sản chủ nghĩa cùng hướng đến chế độ công hữu về tư liệu sản xuất. Mặc dù trình độ phát triển và hình thức phân phối có thể khác nhau, nền tảng sở hữu này là điểm chung được nhấn mạnh.","topic":"Đề ôn theo sách đỏ HUB","examCode":"SACH-DO-HUB","answerStatus":"marked","basis":"Đáp án theo sách đỏ HUB"},{"id":"SACH-DO-HUB-Q070","chapter":0,"number":70,"question":"Nhiệm vụ nào KHÔNG THUỘC nội dung kinh tế của thời kỳ quá độ lên CNXH?","options":[{"id":"SACH-DO-HUB-Q070-O1","text":"Sắp xếp, bố trí lại các lực lượng sản xuất hiện có"},{"id":"SACH-DO-HUB-Q070-O2","text":"Tiến hành công nghiệp hóa xã hội chủ nghĩa"},{"id":"SACH-DO-HUB-Q070-O3","text":"Xây dựng nền dân chủ xã hội chủ nghĩa"},{"id":"SACH-DO-HUB-Q070-O4","text":"Cải tạo quan hệ sản xuất cũ, xây dựng quan hệ sản xuất mới"}],"correctOptionId":"SACH-DO-HUB-Q070-O3","source":"Sách đỏ HUB (tài liệu lưu hành nội bộ)","explanation":"“Xây dựng nền dân chủ xã hội chủ nghĩa” thuộc lĩnh vực chính trị và thiết lập quyền lực của nhân dân, không phải nhiệm vụ kinh tế trực tiếp như bố trí lực lượng sản xuất hay cải tạo quan hệ sản xuất. Vì đề hỏi nội dung KHÔNG thuộc kinh tế nên chọn C.","topic":"Đề ôn theo sách đỏ HUB","examCode":"SACH-DO-HUB","answerStatus":"marked","basis":"Đáp án theo sách đỏ HUB"},{"id":"SACH-DO-HUB-Q071","chapter":0,"number":71,"question":"Nhiệm vụ nao KHÔNG THUỘC nội dung chính trị của thời kỳ quá độ lên CNXH?","options":[{"id":"SACH-DO-HUB-Q071-O1","text":"Khắc phục những tệ nạn xã hội do xã hội cũ để lại"},{"id":"SACH-DO-HUB-Q071-O2","text":"Xây dựng Đảng Cộng sản vững mạnh"},{"id":"SACH-DO-HUB-Q071-O3","text":"Đấu tranh chống lại các thế lực thù địch chống phá sự nghiệp xây dựng chủ nghĩa xã hội"},{"id":"SACH-DO-HUB-Q071-O4","text":"Xây dựng nén dân chủ xã hội chủ nghĩa"}],"correctOptionId":"SACH-DO-HUB-Q071-O1","source":"Sách đỏ HUB (tài liệu lưu hành nội bộ)","explanation":"Khắc phục tệ nạn xã hội do chế độ cũ để lại trực tiếp liên quan đời sống và quản lý xã hội, không phải nhiệm vụ chính trị trọng tâm như xây dựng Đảng, bảo vệ chính quyền hay thiết lập nền dân chủ. Vì thế, theo cách phân loại nội dung của thời kỳ quá độ, chọn A.","topic":"Đề ôn theo sách đỏ HUB","examCode":"SACH-DO-HUB","answerStatus":"marked","basis":"Đáp án theo sách đỏ HUB"},{"id":"SACH-DO-HUB-Q072","chapter":0,"number":72,"question":"Theo các nhà tư tưởng Hy Lạp cổ đại, phạm trù dân chủ - “demoskratos” được hiểu là:","options":[{"id":"SACH-DO-HUB-Q072-O1","text":"Nhân dân cai trị"},{"id":"SACH-DO-HUB-Q072-O2","text":"Quyền lực cho giai cấp chiếm số đông trong xã hội"},{"id":"SACH-DO-HUB-Q072-O3","text":"Quyền tự do của mỗi người"},{"id":"SACH-DO-HUB-Q072-O4","text":"Quyền lực cho giai cấp cầm quyền"}],"correctOptionId":"SACH-DO-HUB-Q072-O1","source":"Sách đỏ HUB (tài liệu lưu hành nội bộ)","explanation":"Thuật ngữ “demokratia” trong tiếng Hy Lạp cổ có gốc “demos” nghĩa là nhân dân và “kratos” nghĩa là quyền lực hoặc cai trị. Vì vậy, nghĩa cơ bản của dân chủ là nhân dân cai trị, nhân dân nắm quyền.","topic":"Đề ôn theo sách đỏ HUB","examCode":"SACH-DO-HUB","answerStatus":"marked","basis":"Đáp án theo sách đỏ HUB"},{"id":"SACH-DO-HUB-Q073","chapter":0,"number":73,"question":"Theo quan điểm của chủ nghĩa Mác — Lênin, về phương diện quyền lực, dân chủ được hiểu là:","options":[{"id":"SACH-DO-HUB-Q073-O1","text":"Quyền lực nhà nước thuộc về tầng lớp trí thức"},{"id":"SACH-DO-HUB-Q073-O2","text":"Quyền lực nhà nước thuộc giai cấp thống trị"},{"id":"SACH-DO-HUB-Q073-O3","text":"Quyền lực nhà nước thuộc tầng lớp tăng lữ"},{"id":"SACH-DO-HUB-Q073-O4","text":"Quyền lực nhà nước thuộc sở hữu của nhân dân, của xã hội"}],"correctOptionId":"SACH-DO-HUB-Q073-O4","source":"Sách đỏ HUB (tài liệu lưu hành nội bộ)","explanation":"Xét trên phương diện quyền lực, dân chủ trước hết đề cập ai là chủ thể nắm giữ và thực hiện quyền lực nhà nước. Theo quan điểm được hỏi, quyền lực ấy thuộc về nhân dân và xã hội, nên đáp án D nêu đúng nội hàm cốt lõi.","topic":"Đề ôn theo sách đỏ HUB","examCode":"SACH-DO-HUB","answerStatus":"marked","basis":"Đáp án theo sách đỏ HUB"},{"id":"SACH-DO-HUB-Q074","chapter":0,"number":74,"question":"Nền dân chủ CNXH là nền dân chủ:","options":[{"id":"SACH-DO-HUB-Q074-O1","text":"Tuyệt đối nhất trong lịch sử"},{"id":"SACH-DO-HUB-Q074-O2","text":"Cho mọi giai cấp"},{"id":"SACH-DO-HUB-Q074-O3","text":"Phát triển cao nhất so với các nền dân chủ khác trong lịch sử"},{"id":"SACH-DO-HUB-Q074-O4","text":"Không mang tính giai cấp"}],"correctOptionId":"SACH-DO-HUB-Q074-O3","source":"Sách đỏ HUB (tài liệu lưu hành nội bộ)","explanation":"Trong hệ thống lý luận của giáo trình, dân chủ xã hội chủ nghĩa được coi là giai đoạn phát triển cao hơn về phạm vi và điều kiện thực hiện quyền làm chủ của đông đảo nhân dân lao động. Vì vậy, phương án C phản ánh đánh giá đó khi so sánh với những hình thức dân chủ trước đây.","topic":"Đề ôn theo sách đỏ HUB","examCode":"SACH-DO-HUB","answerStatus":"marked","basis":"Đáp án theo sách đỏ HUB"},{"id":"SACH-DO-HUB-Q075","chapter":0,"number":75,"question":"Theo quan điểm của chủ nghĩa Mác — Lênin, với cách tiếp cận dân chủ là một hình thức hay hình thái nhà nước, dân chủ được hiểu là:","options":[{"id":"SACH-DO-HUB-Q075-O1","text":"Nguyên tắc dân chủ"},{"id":"SACH-DO-HUB-Q075-O2","text":"Chế độ dân chủ"},{"id":"SACH-DO-HUB-Q075-O3","text":"Gia trị dân chủ"},{"id":"SACH-DO-HUB-Q075-O4","text":"Thực hành dân chủ"}],"correctOptionId":"SACH-DO-HUB-Q075-O2","source":"Sách đỏ HUB (tài liệu lưu hành nội bộ)","explanation":"Khi xem dân chủ như một hình thức tổ chức quyền lực hoặc hình thái nhà nước, ta đang nói đến một “chế độ dân chủ” cụ thể. Cách hiểu này khác với dân chủ như một giá trị, nguyên tắc hoặc hoạt động thực hành.","topic":"Đề ôn theo sách đỏ HUB","examCode":"SACH-DO-HUB","answerStatus":"marked","basis":"Đáp án theo sách đỏ HUB"},{"id":"SACH-DO-HUB-Q076","chapter":0,"number":76,"question":"Nền dân chủ XHCN dựa trên hệ tư tưởng của:","options":[{"id":"SACH-DO-HUB-Q076-O1","text":"Tầng lớp trí thức"},{"id":"SACH-DO-HUB-Q076-O2","text":"Giai cấp địa chủ"},{"id":"SACH-DO-HUB-Q076-O3","text":"Giai cấp tư sản"},{"id":"SACH-DO-HUB-Q076-O4","text":"Giai cấp công nhân giác ngộ chủ nghĩa Mác — Lênin"}],"correctOptionId":"SACH-DO-HUB-Q076-O4","source":"Sách đỏ HUB (tài liệu lưu hành nội bộ)","explanation":"Theo giáo trình, nền dân chủ xã hội chủ nghĩa lấy chủ nghĩa Mác - Lênin làm nền tảng tư tưởng và phản ánh vai trò lãnh đạo của giai cấp công nhân đã giác ngộ lý luận đó. Do vậy, đáp án D xác định đúng hệ tư tưởng nền tảng được nhắc đến.","topic":"Đề ôn theo sách đỏ HUB","examCode":"SACH-DO-HUB","answerStatus":"marked","basis":"Đáp án theo sách đỏ HUB"},{"id":"SACH-DO-HUB-Q077","chapter":0,"number":77,"question":"Bản chất kinh tế của nền dân chủ XHCN là:","options":[{"id":"SACH-DO-HUB-Q077-O1","text":"Thực hiện chế độ cong hữu về tư liệu sản xuất chủ yếu và thực hiện chế độ phân phối lợi ích theo kết quả lao động là chủ yếu"},{"id":"SACH-DO-HUB-Q077-O2","text":"Thực hiện chế độ tư hữu về tư liệu sản xuất chủ yếu và thực hiện chế độ phân phối lợi ích theo kết quả lao động là chủ yếu"},{"id":"SACH-DO-HUB-Q077-O3","text":"Thực hiện chế độ công hữu về tư liệu sản xuất chủ yếu và thực hiện chế độ phân phối lợi ích theo mức độ đóng góp vôn là chủ yếu"},{"id":"SACH-DO-HUB-Q077-O4","text":"Thực hiện chế độ tư hữu về tư liệu sản xuất chủ yếu và thực hiện chế độ phân phối lợi ích theo mức độ đóng góp vôn là chủ yếu"}],"correctOptionId":"SACH-DO-HUB-Q077-O1","source":"Sách đỏ HUB (tài liệu lưu hành nội bộ)","explanation":"Trong khuôn khổ lý luận xã hội chủ nghĩa, nền tảng kinh tế của dân chủ xã hội chủ nghĩa gắn với công hữu tư liệu sản xuất chủ yếu và phân phối chủ yếu theo kết quả lao động. Quan hệ sở hữu và phân phối này được xem là cơ sở vật chất cho việc thực hiện quyền làm chủ.","topic":"Đề ôn theo sách đỏ HUB","examCode":"SACH-DO-HUB","answerStatus":"marked","basis":"Đáp án theo sách đỏ HUB"},{"id":"SACH-DO-HUB-Q078","chapter":0,"number":78,"question":"Lịch sử loài người đã từng xuất hiện các chế độ dân chủ nào?","options":[{"id":"SACH-DO-HUB-Q078-O1","text":"Chủ nô, phong kiến, tư sản, vô sản"},{"id":"SACH-DO-HUB-Q078-O2","text":"Chủ nô, tư sản, vô sản"},{"id":"SACH-DO-HUB-Q078-O3","text":"Nguyên thủy, chủ nô, phong kiến, tư sản, vô sản"},{"id":"SACH-DO-HUB-Q078-O4","text":"Chủ nô, phong kiến, tư sản."}],"correctOptionId":"SACH-DO-HUB-Q078-O2","source":"Sách đỏ HUB (tài liệu lưu hành nội bộ)","explanation":"Theo cách phân loại chế độ dân chủ theo bản chất giai cấp trong giáo trình, lịch sử xã hội có giai cấp lần lượt xuất hiện dân chủ chủ nô, dân chủ tư sản và dân chủ vô sản. Đó là ba kiểu chế độ dân chủ tương ứng với những điều kiện kinh tế - xã hội khác nhau.","topic":"Đề ôn theo sách đỏ HUB","examCode":"SACH-DO-HUB","answerStatus":"marked","basis":"Đáp án theo sách đỏ HUB"},{"id":"SACH-DO-HUB-Q079","chapter":0,"number":79,"question":"Sự khác biệt của Nhà nước pháp quyền XHCN Việt Nam với các nhà nước pháp quyền khác là:","options":[{"id":"SACH-DO-HUB-Q079-O1","text":"Mang bản chất giai cấp nông nhân, phục vụ lợi ích cho nhân dân; nhà nước là công cụ chủ yếu để Đảng Cộng sản Việt Nam định hướng đi lên chủ nghĩa xã hội"},{"id":"SACH-DO-HUB-Q079-O2","text":"Mang bản chất giai cấp nông dân, phục vụ lợi ích cho nông dân; nhà nước là công cụ chủ yếu để Đảng Cộng sản Việt Nam định hướng đi lên chủ nghĩa xã hội"},{"id":"SACH-DO-HUB-Q079-O3","text":"Mang bản chất giai cấp công nhân, phục vụ lợi ích cho nhân dân; nhà nước là công cụ chủ yếu dé Đảng Cộng sản Việt Nam định hướng di lên chủ nghĩa xã hội"},{"id":"SACH-DO-HUB-Q079-O4","text":"Mang bản chất giai cấp công nhân, phục vụ lợi ích cho công nhân; nhà nước là công cụ chủ yếu để Đảng Cộng sản Việt Nam định hướng đi lên chủ nghĩa xã hội"}],"correctOptionId":"SACH-DO-HUB-Q079-O3","source":"Sách đỏ HUB (tài liệu lưu hành nội bộ)","explanation":"Theo mô hình được trình bày trong giáo trình, Nhà nước pháp quyền xã hội chủ nghĩa Việt Nam mang bản chất giai cấp công nhân, hướng đến phục vụ lợi ích nhân dân và gắn với vai trò lãnh đạo của Đảng Cộng sản Việt Nam. Phương án C tổng hợp đúng ba đặc điểm mà câu hỏi yêu cầu.","topic":"Đề ôn theo sách đỏ HUB","examCode":"SACH-DO-HUB","answerStatus":"marked","basis":"Đáp án theo sách đỏ HUB"},{"id":"SACH-DO-HUB-Q080","chapter":0,"number":80,"question":"Theo Lênin, nhà nước “nửa nhà nước” là:","options":[{"id":"SACH-DO-HUB-Q080-O1","text":"Nhà nước chủ nô"},{"id":"SACH-DO-HUB-Q080-O2","text":"Nhà nước tư sản"},{"id":"SACH-DO-HUB-Q080-O3","text":"Nhà nước phong kiến"},{"id":"SACH-DO-HUB-Q080-O4","text":"Nhà nước xã hội chủ nghĩa"}],"correctOptionId":"SACH-DO-HUB-Q080-O4","source":"Sách đỏ HUB (tài liệu lưu hành nội bộ)","explanation":"Lênin dùng hình ảnh “nửa nhà nước” để chỉ nhà nước trong thời kỳ chuyển biến xã hội chủ nghĩa, khi chức năng cưỡng chế đối với số đông bị thay đổi về bản chất và nhà nước được cho là bắt đầu quá trình tiêu vong về lâu dài. Do đó, cách gọi trong tài liệu là nhà nước xã hội chủ nghĩa.","topic":"Đề ôn theo sách đỏ HUB","examCode":"SACH-DO-HUB","answerStatus":"marked","basis":"Đáp án theo sách đỏ HUB"},{"id":"SACH-DO-HUB-Q081","chapter":0,"number":81,"question":"Chọn phương án đúng cho cụm từ còn thiếu: Nhà nước XHCN vừa có bản chất giai cấp công nhân, vừa có tính nhân dân rộng rãi và tính [.........] sâu sắc.","options":[{"id":"SACH-DO-HUB-Q081-O1","text":"Dân tộc"},{"id":"SACH-DO-HUB-Q081-O2","text":"Nhân đạo"},{"id":"SACH-DO-HUB-Q081-O3","text":"Giai cấp"},{"id":"SACH-DO-HUB-Q081-O4","text":"Cộng đồng"}],"correctOptionId":"SACH-DO-HUB-Q081-O1","source":"Sách đỏ HUB (tài liệu lưu hành nội bộ)","explanation":"Theo quan niệm trong giáo trình, Nhà nước xã hội chủ nghĩa vừa thể hiện bản chất giai cấp công nhân, vừa đại diện lợi ích rộng rãi của nhân dân và cộng đồng dân tộc. Từ còn thiếu “dân tộc” làm trọn ý về tính dân tộc sâu sắc của nhà nước.","topic":"Đề ôn theo sách đỏ HUB","examCode":"SACH-DO-HUB","answerStatus":"marked","basis":"Đáp án theo sách đỏ HUB"},{"id":"SACH-DO-HUB-Q082","chapter":0,"number":82,"question":"Theo quan điểm của chủ nghĩa Mác — Lênin, dân chủ trên lĩnh vực nào là cơ sở của dân chủ XHCN?","options":[{"id":"SACH-DO-HUB-Q082-O1","text":"Chính trị"},{"id":"SACH-DO-HUB-Q082-O2","text":"Kinh tế"},{"id":"SACH-DO-HUB-Q082-O3","text":"Văn hóa, tư tưởng"},{"id":"SACH-DO-HUB-Q082-O4","text":"Xã hội"}],"correctOptionId":"SACH-DO-HUB-Q082-O2","source":"Sách đỏ HUB (tài liệu lưu hành nội bộ)","explanation":"Quyền làm chủ trên các lĩnh vực khác muốn được thực hiện bền vững cần dựa trên điều kiện vật chất và quan hệ kinh tế của xã hội. Vì vậy, giáo trình xác định dân chủ trong kinh tế là cơ sở của dân chủ xã hội chủ nghĩa.","topic":"Đề ôn theo sách đỏ HUB","examCode":"SACH-DO-HUB","answerStatus":"marked","basis":"Đáp án theo sách đỏ HUB"},{"id":"SACH-DO-HUB-Q083","chapter":0,"number":83,"question":"Dân chủ XHCN mang tính nhất nguyên về chính trị, được hiểu là:","options":[{"id":"SACH-DO-HUB-Q083-O1","text":"Nền dân chủ xã hội chủ nghĩa do Đảng Cộng sản lãnh đạo — đại biểu cho trí tuệ, lợi ích của riêng giai cấp công nhân và tầng lớp trí thức"},{"id":"SACH-DO-HUB-Q083-O2","text":"Nền dân chủ xã hội chủ nghĩa do Đảng Cộng sản lãnh đạo — đại biểu cho trí tuệ, lợi ích của riêng giai cấp công nhân và giai cấp nông dân"},{"id":"SACH-DO-HUB-Q083-O3","text":"Nền dân chủ xã hội chủ nghĩa do Đảng Cộng sản lãnh đạo — đại biểu cho trí tuệ, lợi ích của giai cấp công nhân, nhân dân lao động và toàn dân tộc"},{"id":"SACH-DO-HUB-Q083-O4","text":"Nền dân chủ xã hội chủ nghĩa do Đảng Cộng sản lãnh đạo — đại biểu cho trí tuệ, lợi ích của riêng giai cấp công nhân"}],"correctOptionId":"SACH-DO-HUB-Q083-O3","source":"Sách đỏ HUB (tài liệu lưu hành nội bộ)","explanation":"“Nhất nguyên về chính trị” trong cách trình bày của tài liệu gắn với sự lãnh đạo của một đảng là Đảng Cộng sản, được xác định đại diện cho lợi ích giai cấp công nhân, nhân dân lao động và toàn dân tộc. Phương án C thể hiện đầy đủ nội dung đó.","topic":"Đề ôn theo sách đỏ HUB","examCode":"SACH-DO-HUB","answerStatus":"marked","basis":"Đáp án theo sách đỏ HUB"},{"id":"SACH-DO-HUB-Q084","chapter":0,"number":84,"question":"“Chế độ dân chủ vô sản so với bat cứ chế độ dân chủ tư sản nào, cũng dân chủ hơn gap triệu lan” là quan điểm của ai?","options":[{"id":"SACH-DO-HUB-Q084-O1","text":"Hồ Chí Minh"},{"id":"SACH-DO-HUB-Q084-O2","text":"Các Mác"},{"id":"SACH-DO-HUB-Q084-O3","text":"Ph. Ăngghen"},{"id":"SACH-DO-HUB-Q084-O4","text":"Lênin"}],"correctOptionId":"SACH-DO-HUB-Q084-O4","source":"Sách đỏ HUB (tài liệu lưu hành nội bộ)","explanation":"Câu trích so sánh dân chủ vô sản với dân chủ tư sản là một nhận định của Lênin khi bàn về phạm vi quyền làm chủ của quần chúng lao động. Vì vậy, đáp án gắn tên Lênin với phát biểu này.","topic":"Đề ôn theo sách đỏ HUB","examCode":"SACH-DO-HUB","answerStatus":"marked","basis":"Đáp án theo sách đỏ HUB"},{"id":"SACH-DO-HUB-Q085","chapter":0,"number":85,"question":"Chọn phương án KHÔNG ĐÚNG về điểm khác biệt của nền dân chủ XHCN so với nền dân chủ tư sản:","options":[{"id":"SACH-DO-HUB-Q085-O1","text":"Không mang tính giai cấp"},{"id":"SACH-DO-HUB-Q085-O2","text":"Mang tính nhất nguyên về chính trị"},{"id":"SACH-DO-HUB-Q085-O3","text":"Dựa trên chế độ sở hữu xã hội về những tư liệu sản xuất chủ yếu của toàn xã hội"},{"id":"SACH-DO-HUB-Q085-O4","text":"Trước hết và chủ yếu được thực hiện bằng Nhà nước pháp quyền xã hội chủ nghĩa"}],"correctOptionId":"SACH-DO-HUB-Q085-O1","source":"Sách đỏ HUB (tài liệu lưu hành nội bộ)","explanation":"Theo quan điểm Mác - Lênin, mọi hình thức dân chủ trong xã hội có giai cấp đều mang dấu ấn lợi ích và quyền lực giai cấp. Do đó, nhận định “không mang tính giai cấp” không phải đặc điểm khác biệt của nền dân chủ xã hội chủ nghĩa; đề yêu cầu chọn phương án KHÔNG đúng.","topic":"Đề ôn theo sách đỏ HUB","examCode":"SACH-DO-HUB","answerStatus":"marked","basis":"Đáp án theo sách đỏ HUB"},{"id":"SACH-DO-HUB-Q086","chapter":0,"number":86,"question":"Về những đặc điểm của Nhà nước pháp quyền XHCN Việt Nam, phạm trù nào được đặt ở vị trí tối thượng dé điều chỉnh các quan hệ xã hội?","options":[{"id":"SACH-DO-HUB-Q086-O1","text":"Phong tục, tập quán"},{"id":"SACH-DO-HUB-Q086-O2","text":"Hiến pháp, pháp luật"},{"id":"SACH-DO-HUB-Q086-O3","text":"Đạo đức, tình cam"},{"id":"SACH-DO-HUB-Q086-O4","text":"Mối quan hệ thân hữu"}],"correctOptionId":"SACH-DO-HUB-Q086-O2","source":"Sách đỏ HUB (tài liệu lưu hành nội bộ)","explanation":"Nhà nước pháp quyền điều chỉnh các quan hệ xã hội bằng hệ thống quy phạm có hiệu lực chung, đặt Hiến pháp và pháp luật ở địa vị tối thượng. Vì vậy, việc tuân thủ Hiến pháp, pháp luật là nguyên tắc cơ bản, không thể thay bằng tập quán hay quan hệ cá nhân.","topic":"Đề ôn theo sách đỏ HUB","examCode":"SACH-DO-HUB","answerStatus":"marked","basis":"Đáp án theo sách đỏ HUB"},{"id":"SACH-DO-HUB-Q087","chapter":0,"number":87,"question":"Dân chủ với tư cách là một chế độ xã hội, ra đời đầu tiên ở hình thái kinh tế - xã hội nào?","options":[{"id":"SACH-DO-HUB-Q087-O1","text":"Phong kiến"},{"id":"SACH-DO-HUB-Q087-O2","text":"Công xã nguyên thủy"},{"id":"SACH-DO-HUB-Q087-O3","text":"Chiếm hữu nô lệ"},{"id":"SACH-DO-HUB-Q087-O4","text":"Tư bản chủ nghĩa"}],"correctOptionId":"SACH-DO-HUB-Q087-O3","source":"Sách đỏ HUB (tài liệu lưu hành nội bộ)","explanation":"Theo cách tiếp cận của giáo trình, chế độ dân chủ đầu tiên xuất hiện trong xã hội chiếm hữu nô lệ dưới hình thức dân chủ chủ nô. Quyền lực được tổ chức cho tầng lớp chủ nô, còn nô lệ không được thừa nhận là chủ thể bình đẳng của quyền lực.","topic":"Đề ôn theo sách đỏ HUB","examCode":"SACH-DO-HUB","answerStatus":"marked","basis":"Đáp án theo sách đỏ HUB"},{"id":"SACH-DO-HUB-Q088","chapter":0,"number":88,"question":"Bộ máy Nhà nước pháp quyền XHCN ở Việt Nam được tổ chức và hoạt động theo nguyên tắc:","options":[{"id":"SACH-DO-HUB-Q088-O1","text":"Pháp chế tư sản"},{"id":"SACH-DO-HUB-Q088-O2","text":"Tam quyền phân lập"},{"id":"SACH-DO-HUB-Q088-O3","text":"Dân chủ đa nguyên"},{"id":"SACH-DO-HUB-Q088-O4","text":"Tập trung dân chủ"}],"correctOptionId":"SACH-DO-HUB-Q088-O4","source":"Sách đỏ HUB (tài liệu lưu hành nội bộ)","explanation":"Nguyên tắc tập trung dân chủ kết hợp việc phát huy thảo luận, tham gia và trách nhiệm của các cơ quan với sự thống nhất, chấp hành quyết định chung. Đây là nguyên tắc tổ chức, hoạt động được nhấn mạnh đối với bộ máy nhà nước xã hội chủ nghĩa Việt Nam.","topic":"Đề ôn theo sách đỏ HUB","examCode":"SACH-DO-HUB","answerStatus":"marked","basis":"Đáp án theo sách đỏ HUB"},{"id":"SACH-DO-HUB-Q089","chapter":0,"number":89,"question":"Đặc điểm nào KHÔNG THUỘC ban chất của nền dân chủ XHCN?","options":[{"id":"SACH-DO-HUB-Q089-O1","text":"Đa nguyên về chính trị"},{"id":"SACH-DO-HUB-Q089-O2","text":"Do Đảng Cộng sản của giai cấp công nhân lãnh đạo"},{"id":"SACH-DO-HUB-Q089-O3","text":"Cơ sở kinh tế là chế độ công hữu về các tư liệu sản xuất chủ yếu"},{"id":"SACH-DO-HUB-Q089-O4","text":"Quyền lực thuộc về nhân dân"}],"correctOptionId":"SACH-DO-HUB-Q089-O1","source":"Sách đỏ HUB (tài liệu lưu hành nội bộ)","explanation":"Theo mô hình chính trị xã hội chủ nghĩa được giáo trình mô tả, tính nhất nguyên về chính trị gắn với vai trò lãnh đạo của Đảng Cộng sản. Vì vậy, “đa nguyên về chính trị” không thuộc những đặc điểm bản chất mà tài liệu xác định; câu hỏi yêu cầu chọn phương án KHÔNG thuộc.","topic":"Đề ôn theo sách đỏ HUB","examCode":"SACH-DO-HUB","answerStatus":"marked","basis":"Đáp án theo sách đỏ HUB"},{"id":"SACH-DO-HUB-Q090","chapter":0,"number":90,"question":"Theo Nghị quyết Đại hội đại biểu toàn quốc lần thứ XIII (2021) của Đảng, dé thực hành và phát huy rộng rãi quyền làm chủ của nhân dân và vai trò chủ thê của nhân dân, cần thực hiện hiệu quả phương châm nào?","options":[{"id":"SACH-DO-HUB-Q090-O1","text":"Dân biết, dân bàn, dân giám sát, dân thụ hưởng"},{"id":"SACH-DO-HUB-Q090-O2","text":"Dân biết, dân làm, dân kiểm tra, dân thụ hưởng"},{"id":"SACH-DO-HUB-Q090-O3","text":"Dân biết, dân bàn, dân làm, dân kiểm tra, dân giám sát, dân thụ hưởng"},{"id":"SACH-DO-HUB-Q090-O4","text":"Dân bàn, dân làm, dân giám sát, dân thụ hưởng"}],"correctOptionId":"SACH-DO-HUB-Q090-O3","source":"Sách đỏ HUB (tài liệu lưu hành nội bộ)","explanation":"Phương châm Đại hội XIII bổ sung và nhấn mạnh đầy đủ sáu khâu: dân biết, dân bàn, dân làm, dân kiểm tra, dân giám sát, dân thụ hưởng. Các khâu nối tiếp từ tiếp cận thông tin đến tham gia quyết định, thực hiện, kiểm soát và hưởng thành quả.","topic":"Đề ôn theo sách đỏ HUB","examCode":"SACH-DO-HUB","answerStatus":"marked","basis":"Đáp án theo sách đỏ HUB"},{"id":"SACH-DO-HUB-Q091","chapter":0,"number":91,"question":"Đặc điểm nào KHÔNG phản ánh đặc trưng của nhà nước XHCN?","options":[{"id":"SACH-DO-HUB-Q091-O1","text":"Đặt dưới sự lãnh đạo của Đảng Cộng sản"},{"id":"SACH-DO-HUB-Q091-O2","text":"Là “Nhà nước không còn nguyên nghĩa”, là “Nửa nhà nước”"},{"id":"SACH-DO-HUB-Q091-O3","text":"Mang bản chất của giai cấp công nhân"},{"id":"SACH-DO-HUB-Q091-O4","text":"Tổ chức và hoạt động theo nguyên tắc tam quyền phân lập"}],"correctOptionId":"SACH-DO-HUB-Q091-O4","source":"Sách đỏ HUB (tài liệu lưu hành nội bộ)","explanation":"Tổ chức theo nguyên tắc “tam quyền phân lập” được nhắc đến trong lý luận về mô hình phân chia quyền lực nhà nước, nhưng không phải nguyên tắc tổ chức bộ máy nhà nước xã hội chủ nghĩa Việt Nam theo giáo trình. Vì câu hỏi chọn đặc điểm KHÔNG phản ánh, đáp án là D.","topic":"Đề ôn theo sách đỏ HUB","examCode":"SACH-DO-HUB","answerStatus":"marked","basis":"Đáp án theo sách đỏ HUB"},{"id":"SACH-DO-HUB-Q092","chapter":0,"number":92,"question":"Chọn phương án KHÔNG ĐÚNG về tính tất yếu của việc xây dựng nhà nước XHCN:","options":[{"id":"SACH-DO-HUB-Q092-O1","text":"Để xây dựng nền dân chủ xã hội chủ nghĩa"},{"id":"SACH-DO-HUB-Q092-O2","text":"Đảm bảo sự lãnh đạo của giai cấp công nhân đối với toàn xã hội"},{"id":"SACH-DO-HUB-Q092-O3","text":"Thể hiện sức mạnh của nhà nước xã hội chủ nghĩa"},{"id":"SACH-DO-HUB-Q092-O4","text":"Để trấn áp các thế lực đi ngược lại lợi ích của nhân dân"}],"correctOptionId":"SACH-DO-HUB-Q092-O3","source":"Sách đỏ HUB (tài liệu lưu hành nội bộ)","explanation":"Xây dựng nhà nước xã hội chủ nghĩa được lý giải bằng nhu cầu thực hiện dân chủ, tổ chức quyền lực và bảo vệ lợi ích của nhân dân lao động. Cụm “thể hiện sức mạnh” chỉ là mô tả chung, chưa nêu một lý do tất yếu có nội dung cụ thể, nên sách chọn C cho phương án KHÔNG đúng.","topic":"Đề ôn theo sách đỏ HUB","examCode":"SACH-DO-HUB","answerStatus":"marked","basis":"Đáp án theo sách đỏ HUB"},{"id":"SACH-DO-HUB-Q093","chapter":0,"number":93,"question":"Trong thời kỳ quá độ lên chủ nghĩa xã hội ở Việt Nam, nội dung chính trị của liên minh giai cấp, tầng lớp thể hiện thông qua việc:","options":[{"id":"SACH-DO-HUB-Q093-O1","text":"Giữ vững lập trường chính trị - tư tưởng của đội ngũ doanh nhân, đồng thời giữ vững vai trò lãnh đạo của Công đoàn đối với khối liên minh và đối với toàn xã hội"},{"id":"SACH-DO-HUB-Q093-O2","text":"Giữ vững lập trường chính trị - tư tưởng của giai cấp nông nhân, đồng thời giữ vững vai trò lãnh đạo của Nhà nước pháp quyền xã hội chủ nghĩa đối với khối liên minh và đối với toàn xã hội"},{"id":"SACH-DO-HUB-Q093-O3","text":"Giữ vững lập trường chính trị - tư tưởng của tầng lớp trí thức, đồng thời giữ vững vai trò lãnh đạo của Chính phủ đối với khối liên minh và đối với toàn xã hội"},{"id":"SACH-DO-HUB-Q093-O4","text":"Giữ vững lập trường chính trị - tư tưởng của giai cấp công nhân, đồng thời giữ vững vai trò lãnh đạo của Đảng Cộng sản Việt Nam doi với khối liên minh và đối với toàn xã hội"}],"correctOptionId":"SACH-DO-HUB-Q093-O4","source":"Sách đỏ HUB (tài liệu lưu hành nội bộ)","explanation":"Liên minh giai cấp, tầng lớp ở Việt Nam trên phương diện chính trị đòi hỏi sự thống nhất về định hướng, mục tiêu và tổ chức lãnh đạo. Vì vậy, giữ vững lập trường chính trị - tư tưởng của giai cấp công nhân và vai trò lãnh đạo của Đảng Cộng sản Việt Nam được coi là nội dung then chốt.","topic":"Đề ôn theo sách đỏ HUB","examCode":"SACH-DO-HUB","answerStatus":"marked","basis":"Đáp án theo sách đỏ HUB"},{"id":"SACH-DO-HUB-Q094","chapter":0,"number":94,"question":"Loại hình cơ cấu xã hội nào liên quan trực tiếp đến các đảng phái chính trị và nhà nước; đến quyền sở hữu tư liệu sản xuất, quản lý tổ chức lao động, vấn đề phân phối thu nhập trong một hệ thống sản xuất nhất định?","options":[{"id":"SACH-DO-HUB-Q094-O1","text":"Cơ cấu xã hội — giai cấp"},{"id":"SACH-DO-HUB-Q094-O2","text":"Cơ cấu xã hội — nghề nghiệp"},{"id":"SACH-DO-HUB-Q094-O3","text":"Co cấu xã hội - tôn giáo"},{"id":"SACH-DO-HUB-Q094-O4","text":"Cơ cấu xã hội — dân tộc"}],"correctOptionId":"SACH-DO-HUB-Q094-O1","source":"Sách đỏ HUB (tài liệu lưu hành nội bộ)","explanation":"Cơ cấu xã hội - giai cấp phản ánh vị trí các giai cấp trong quan hệ sở hữu, tổ chức lao động và phân phối sản phẩm. Những quan hệ đó liên hệ trực tiếp đến lợi ích chính trị, đảng phái và nhà nước, nên đáp án A phù hợp với mô tả trong câu hỏi.","topic":"Đề ôn theo sách đỏ HUB","examCode":"SACH-DO-HUB","answerStatus":"marked","basis":"Đáp án theo sách đỏ HUB"},{"id":"SACH-DO-HUB-Q095","chapter":0,"number":95,"question":"Trong cơ cấu xã hội, loại hình cơ cấu nào là cơ bản và có vị trí quyết định, chỉ phối các loại hình cơ cấu xã hội khác?","options":[{"id":"SACH-DO-HUB-Q095-O1","text":"Cơ cấu xã hội — giai cấp"},{"id":"SACH-DO-HUB-Q095-O2","text":"Cơ cau xã hội — nghề nghiệp"},{"id":"SACH-DO-HUB-Q095-O3","text":"Cơ cấu xã hội — dân cư"},{"id":"SACH-DO-HUB-Q095-O4","text":"Co cấu xã hội — dân tộc"}],"correctOptionId":"SACH-DO-HUB-Q095-O1","source":"Sách đỏ HUB (tài liệu lưu hành nội bộ)","explanation":"Địa vị kinh tế và quan hệ lợi ích giữa các giai cấp ảnh hưởng sâu sắc tới quyền lực, cấu trúc nghề nghiệp, đời sống và các mối quan hệ xã hội khác. Vì thế, trong cách phân tích của giáo trình, cơ cấu xã hội - giai cấp giữ vị trí cơ bản và có tác động chi phối.","topic":"Đề ôn theo sách đỏ HUB","examCode":"SACH-DO-HUB","answerStatus":"marked","basis":"Đáp án theo sách đỏ HUB"},{"id":"SACH-DO-HUB-Q096","chapter":0,"number":96,"question":"“Trong mọi thời đại lịch sử, sản xuất kinh tế và cơ cấu xã hội - cơ cấu này tất yếu phải do sản xuất kinh tế mà ra - cả hai cái đó cấu thành cơ sở của lịch sử chính trị và lịch sử tư tưởng của thời đại ấy” là quan điểm của ai?","options":[{"id":"SACH-DO-HUB-Q096-O1","text":"Các Mác"},{"id":"SACH-DO-HUB-Q096-O2","text":"Ph. Ăngghen"},{"id":"SACH-DO-HUB-Q096-O3","text":"Lênin"},{"id":"SACH-DO-HUB-Q096-O4","text":"Tôn Trung Son"}],"correctOptionId":"SACH-DO-HUB-Q096-O2","source":"Sách đỏ HUB (tài liệu lưu hành nội bộ)","explanation":"Ph. Ăngghen nhấn mạnh vai trò nền tảng của sản xuất kinh tế và cơ cấu xã hội trong việc lý giải lịch sử chính trị, tư tưởng. Câu trích thuộc lập trường duy vật lịch sử, lấy điều kiện sản xuất và kết cấu xã hội làm điểm xuất phát để nghiên cứu lịch sử.","topic":"Đề ôn theo sách đỏ HUB","examCode":"SACH-DO-HUB","answerStatus":"marked","basis":"Đáp án theo sách đỏ HUB"},{"id":"SACH-DO-HUB-Q097","chapter":0,"number":97,"question":"Trong cơ cấu xã hội — giai cấp ở thời kỳ quá độ từ chủ nghĩa tư bản lên CNXH, giai cấp nào là lực lượng tiêu biểu cho phương thức sản xuất mới giữ vai trò chủ đạo, tiên phong trong quá trình công nghiệp hóa, hiện đại hóa đất nước?","options":[{"id":"SACH-DO-HUB-Q097-O1","text":"Tư sản"},{"id":"SACH-DO-HUB-Q097-O2","text":"Nông dân"},{"id":"SACH-DO-HUB-Q097-O3","text":"Công nhân"},{"id":"SACH-DO-HUB-Q097-O4","text":"Địa chủ"}],"correctOptionId":"SACH-DO-HUB-Q097-O3","source":"Sách đỏ HUB (tài liệu lưu hành nội bộ)","explanation":"Theo lý luận về thời kỳ quá độ, giai cấp công nhân gắn với phương thức sản xuất mới và được xem là lực lượng chủ đạo của công nghiệp hóa, hiện đại hóa. Vì vậy, trong cơ cấu xã hội - giai cấp, tài liệu xác định công nhân giữ vai trò lãnh đạo, tiên phong.","topic":"Đề ôn theo sách đỏ HUB","examCode":"SACH-DO-HUB","answerStatus":"marked","basis":"Đáp án theo sách đỏ HUB"},{"id":"SACH-DO-HUB-Q098","chapter":0,"number":98,"question":"“Xây dựng khối liên minh dé các lực lượng dưới sự lãnh đạo của Đảng cùng nhau xây một nền văn hóa tiên tiến, đậm đà bản sắc dân tộc, đồng thời tiếp thu những tỉnh hoa, giá trị văn hóa của nhân loại và thời đại” là nội dung nào của liên minh giai cấp, tầng lớp trong thời kỳ quá độ lên CNXH?","options":[{"id":"SACH-DO-HUB-Q098-O1","text":"Nội dung chính trị"},{"id":"SACH-DO-HUB-Q098-O2","text":"Nội dung văn hóa — xã hội"},{"id":"SACH-DO-HUB-Q098-O3","text":"Nội dung kinh tế"},{"id":"SACH-DO-HUB-Q098-O4","text":"Nội dung tư tưởng"}],"correctOptionId":"SACH-DO-HUB-Q098-O2","source":"Sách đỏ HUB (tài liệu lưu hành nội bộ)","explanation":"Việc cùng nhau xây dựng nền văn hóa tiên tiến, giữ gìn bản sắc dân tộc và tiếp thu tinh hoa nhân loại liên quan trực tiếp đến đời sống tinh thần và sự phát triển xã hội. Do đó, đây là nội dung văn hóa - xã hội của liên minh giai cấp, tầng lớp.","topic":"Đề ôn theo sách đỏ HUB","examCode":"SACH-DO-HUB","answerStatus":"marked","basis":"Đáp án theo sách đỏ HUB"},{"id":"SACH-DO-HUB-Q099","chapter":0,"number":99,"question":"Trong thời kỳ quá độ lên CNXH ở Việt Nam, cơ cấu xã hội — giai cấp gồm có những giai cấp, tầng lớp cơ bản nào?","options":[{"id":"SACH-DO-HUB-Q099-O1","text":"Giai cấp công nhân, giai cấp nông dân, giai cấp địa chủ phong kiến, tầng lớp trí thức"},{"id":"SACH-DO-HUB-Q099-O2","text":"Giai cấp công nhân, giai cấp nông dân, đội ngũ doanh nhân, tầng lớp trí thức"},{"id":"SACH-DO-HUB-Q099-O3","text":"Giai cấp công nhân, giai cấp nông dân, giai cấp tư sản, giai cấp địa chủ phong kiên"},{"id":"SACH-DO-HUB-Q099-O4","text":"Giai cấp công nhân, giai cấp nông dân, giai cấp tư sản, tầng lớp trí thức"}],"correctOptionId":"SACH-DO-HUB-Q099-O2","source":"Sách đỏ HUB (tài liệu lưu hành nội bộ)","explanation":"Ở thời kỳ quá độ, cơ cấu xã hội - giai cấp Việt Nam có nhiều lực lượng cùng tham gia lao động và phát triển đất nước. Phương án B liệt kê các lực lượng cơ bản được câu hỏi nhấn mạnh: công nhân, nông dân, doanh nhân và trí thức.","topic":"Đề ôn theo sách đỏ HUB","examCode":"SACH-DO-HUB","answerStatus":"marked","basis":"Đáp án theo sách đỏ HUB"},{"id":"SACH-DO-HUB-Q100","chapter":0,"number":100,"question":"Nội dung chính trị của liên minh giai cấp, tầng lớp trong thời kỳ quá độ lên CNXH ở Việt Nam là:","options":[{"id":"SACH-DO-HUB-Q100-O1","text":"Giữ vững lập trường tư tưởng của giai cấp công nhân, giữ vững vai trò lãnh đạo của Đảng Cộng sản"},{"id":"SACH-DO-HUB-Q100-O2","text":"Đây mạnh công nghiệp hóa, hiện đại hóa đất nước gắn với phát triển kinh tế tri thức, phát triển bên vững"},{"id":"SACH-DO-HUB-Q100-O3","text":"Tăng trưởng kinh tế kết hợp với phát triển văn hóa, tiến bộ, công bằng xã hội"},{"id":"SACH-DO-HUB-Q100-O4","text":"Xây một nền văn hóa tiên tiến, đậm đà bản sắc dân tộc, đồng thời tiếp thu những tinh hoa, giá trị văn hóa của nhân loại và thời đại"}],"correctOptionId":"SACH-DO-HUB-Q100-O1","source":"Sách đỏ HUB (tài liệu lưu hành nội bộ)","explanation":"Nội dung chính trị của liên minh tập trung vào mục tiêu, định hướng và lực lượng lãnh đạo, không phải hoạt động sản xuất hay chính sách văn hóa đơn lẻ. Vì vậy, giữ vững lập trường của giai cấp công nhân và vai trò lãnh đạo của Đảng Cộng sản là nội dung chính trị trọng tâm.","topic":"Đề ôn theo sách đỏ HUB","examCode":"SACH-DO-HUB","answerStatus":"marked","basis":"Đáp án theo sách đỏ HUB"},{"id":"SACH-DO-HUB-Q101","chapter":0,"number":101,"question":"Nội dung kinh tế của liên minh giai cấp, tầng lớp trong thời kỳ quá độ lên CNXH ở Việt Nam là:","options":[{"id":"SACH-DO-HUB-Q101-O1","text":"Day mạnh công nghiệp hóa, hiện đại hóa đất nước gan với phát triển kinh tế tri thức, phát triển bên vững"},{"id":"SACH-DO-HUB-Q101-O2","text":"Giữ vững lập trường tư tưởng của giai cấp công nhân, giữ vững vai trò lãnh đạo của Đảng"},{"id":"SACH-DO-HUB-Q101-O3","text":"Tăng trưởng kinh tế kết hợp với phát triển văn hóa, tiền bộ, công bằng xã hội"},{"id":"SACH-DO-HUB-Q101-O4","text":"Xây một nền văn hóa tiên tiến, đậm đà bản sắc dân tộc, đồng thời tiếp thu những tinh hoa, giá trị văn hóa của nhân loại và thời đại"}],"correctOptionId":"SACH-DO-HUB-Q101-O1","source":"Sách đỏ HUB (tài liệu lưu hành nội bộ)","explanation":"Công nghiệp hóa, hiện đại hóa gắn với kinh tế tri thức và phát triển bền vững là định hướng trực tiếp nâng cao lực lượng sản xuất và hiệu quả kinh tế. Nó tạo cơ sở lợi ích chung cho sự hợp tác giữa công nhân, nông dân, trí thức và các lực lượng xã hội khác.","topic":"Đề ôn theo sách đỏ HUB","examCode":"SACH-DO-HUB","answerStatus":"marked","basis":"Đáp án theo sách đỏ HUB"},{"id":"SACH-DO-HUB-Q102","chapter":0,"number":102,"question":"Theo C. Mác và Ph. Ăngghen, nguyên nhân that bại chủ yếu của nhiều cuộc đấu tranh của giai cấp công nhân ở chau Au, nhât là ở nước Anh và nước Pháp từ giữa thế kỷ XIX là:","options":[{"id":"SACH-DO-HUB-Q102-O1","text":"Giai cấp công nhân không tổ chức liên minh với giai cấp địa chủ"},{"id":"SACH-DO-HUB-Q102-O2","text":"Giai cấp công nhân không tổ chức liên minh với giai cấp tư sản"},{"id":"SACH-DO-HUB-Q102-O3","text":"Giai cấp công nhân không tổ chức liên minh với giai cấp nông dan"},{"id":"SACH-DO-HUB-Q102-O4","text":"Giai cấp công nhân không tổ chức liên minh với tầng lớp tiểu tư sản"}],"correctOptionId":"SACH-DO-HUB-Q102-O3","source":"Sách đỏ HUB (tài liệu lưu hành nội bộ)","explanation":"Trong các cuộc đấu tranh công nhân thế kỷ XIX, thiếu sự liên minh với nông dân khiến lực lượng cách mạng khó tập hợp được đa số nhân dân lao động và thiếu hậu thuẫn xã hội rộng lớn. Theo cách giải thích của giáo trình, đây là một nguyên nhân chủ yếu dẫn đến thất bại của nhiều cuộc đấu tranh.","topic":"Đề ôn theo sách đỏ HUB","examCode":"SACH-DO-HUB","answerStatus":"marked","basis":"Đáp án theo sách đỏ HUB"},{"id":"SACH-DO-HUB-Q103","chapter":0,"number":103,"question":"Lue lượng lao động sáng tạo đặc biệt quan trong để thực hiện công nghiệp hóa — hiện đại hóa đất nước trong thời kỳ quá độ lên CNXH ở Việt Nam là:","options":[{"id":"SACH-DO-HUB-Q103-O1","text":"Giai cấp nông dân"},{"id":"SACH-DO-HUB-Q103-O2","text":"Đội ngũ doanh nhân"},{"id":"SACH-DO-HUB-Q103-O3","text":"Tầng lớp trí thức"},{"id":"SACH-DO-HUB-Q103-O4","text":"Giai cấp công nhân"}],"correctOptionId":"SACH-DO-HUB-Q103-O3","source":"Sách đỏ HUB (tài liệu lưu hành nội bộ)","explanation":"Trí thức là lực lượng có vai trò đặc biệt trong nghiên cứu, sáng tạo và ứng dụng tri thức khoa học - công nghệ vào sản xuất và quản lý. Vì vậy, họ được xác định là nguồn lao động sáng tạo rất quan trọng đối với công nghiệp hóa và hiện đại hóa đất nước.","topic":"Đề ôn theo sách đỏ HUB","examCode":"SACH-DO-HUB","answerStatus":"marked","basis":"Đáp án theo sách đỏ HUB"},{"id":"SACH-DO-HUB-Q104","chapter":0,"number":104,"question":"Chủ thể của quá trình phát triển, xây dựng nông thôn mới gắn với xây dựng các cơ sở công nghiệp, dịch vụ và phát triển đô thị trong thời kỳ quá độ lên CNXH ở Việt Nam là:","options":[{"id":"SACH-DO-HUB-Q104-O1","text":"Tầng lớp trí thức"},{"id":"SACH-DO-HUB-Q104-O2","text":"Đội ngũ doanh nhân"},{"id":"SACH-DO-HUB-Q104-O3","text":"Giai cấp công nhân"},{"id":"SACH-DO-HUB-Q104-O4","text":"Giai cấp nông dân"}],"correctOptionId":"SACH-DO-HUB-Q104-O4","source":"Sách đỏ HUB (tài liệu lưu hành nội bộ)","explanation":"Nông dân gắn trực tiếp với sản xuất nông nghiệp và đời sống nông thôn, nên vừa là đối tượng thụ hưởng vừa là chủ thể tham gia xây dựng nông thôn mới. Vai trò này đặt họ vào trung tâm của quá trình phát triển và cải thiện các điều kiện sống ở nông thôn.","topic":"Đề ôn theo sách đỏ HUB","examCode":"SACH-DO-HUB","answerStatus":"marked","basis":"Đáp án theo sách đỏ HUB"},{"id":"SACH-DO-HUB-Q105","chapter":0,"number":105,"question":"Rường cột của nước nhà, chủ nhân tương lai của đất nước, lực lượng xung kích xây dựng và bảo vệ Tổ quốc trong thời kỳ quá độ lên CNXH ở Việt Nam là:","options":[{"id":"SACH-DO-HUB-Q105-O1","text":"Tầng lớp trí thức"},{"id":"SACH-DO-HUB-Q105-O2","text":"Thanh niên"},{"id":"SACH-DO-HUB-Q105-O3","text":"Đội ngũ doanh nhân"},{"id":"SACH-DO-HUB-Q105-O4","text":"Người Việt Nam ở nước ngoài"}],"correctOptionId":"SACH-DO-HUB-Q105-O2","source":"Sách đỏ HUB (tài liệu lưu hành nội bộ)","explanation":"Thanh niên là lớp người đang và sẽ đảm nhận phần lớn nhiệm vụ lao động, sáng tạo, phát triển và bảo vệ đất nước trong tương lai. Vì vậy, tài liệu dùng những cụm “rường cột”, “chủ nhân tương lai”, “lực lượng xung kích” để nhấn mạnh vai trò của thanh niên.","topic":"Đề ôn theo sách đỏ HUB","examCode":"SACH-DO-HUB","answerStatus":"marked","basis":"Đáp án theo sách đỏ HUB"},{"id":"SACH-DO-HUB-Q106","chapter":0,"number":106,"question":"Hai lực lượng xã hội cơ bản đối lập lợi ích trong cơ cấu xã hội — giai cấp của xã hội TBCN là:","options":[{"id":"SACH-DO-HUB-Q106-O1","text":"tư sản và địa chủ"},{"id":"SACH-DO-HUB-Q106-O2","text":"tư sản và trí thức"},{"id":"SACH-DO-HUB-Q106-O3","text":"tư sản và vô sản"},{"id":"SACH-DO-HUB-Q106-O4","text":"nông dân và tư sản"}],"correctOptionId":"SACH-DO-HUB-Q106-O3","source":"Sách đỏ HUB (tài liệu lưu hành nội bộ)","explanation":"Trong xã hội tư bản chủ nghĩa, giai cấp tư sản sở hữu tư liệu sản xuất chủ yếu còn giai cấp vô sản phải bán sức lao động để sinh sống. Vị trí khác nhau trong quan hệ sản xuất làm nảy sinh lợi ích đối lập cơ bản giữa hai giai cấp này.","topic":"Đề ôn theo sách đỏ HUB","examCode":"SACH-DO-HUB","answerStatus":"marked","basis":"Đáp án theo sách đỏ HUB"},{"id":"SACH-DO-HUB-Q107","chapter":0,"number":107,"question":"Về chính trị, quy luật mang tính pho biến và là động lực lớn cho sự phát triển của các xã hội có giai cấp là:","options":[{"id":"SACH-DO-HUB-Q107-O1","text":"Giai cấp ở vị trí trung tâm phải tìm cách tách biệt các giai cấp, tầng lớp xã hội khác có những lợi ích phù hợp với mình dé tập trung thực hiện những nhu câu và lợi ích riêng"},{"id":"SACH-DO-HUB-Q107-O2","text":"Giai cấp ở vị trí trung tâm phải tìm cách liên mình với các giai cấp, tầng lớp xã hội khác có những lợi ích phù hợp với mình dé tập hợp lực lượng thực hiện những nhu cầu và lợi ích chung"},{"id":"SACH-DO-HUB-Q107-O3","text":"Giai cấp ở vị trí trung tâm phải tìm cách xóa bỏ với các giai cấp, tầng lớp xã hội khác có những lợi ích phù hợp với mình đề tập trung thực hiện những nhu câu và lợi ích riêng"},{"id":"SACH-DO-HUB-Q107-O4","text":"Giai cấp ở vị trí trung tâm phải tìm cách liên minh với các giai cấp, tầng lớp xã hội khác có những lợi ích phù hợp với minh đề tập hợp lực lượng thực hiện những nhu câu và lợi ích riêng của giai cấp đó"}],"correctOptionId":"SACH-DO-HUB-Q107-O2","source":"Sách đỏ HUB (tài liệu lưu hành nội bộ)","explanation":"Liên minh giai cấp được hình thành khi những lực lượng khác nhau nhận ra các nhu cầu và lợi ích chung, từ đó phối hợp hành động để tạo sức mạnh lớn hơn. Vì vậy, theo giáo trình, giai cấp giữ vai trò trung tâm cần xây dựng liên minh với các lực lượng có lợi ích phù hợp.","topic":"Đề ôn theo sách đỏ HUB","examCode":"SACH-DO-HUB","answerStatus":"marked","basis":"Đáp án theo sách đỏ HUB"},{"id":"SACH-DO-HUB-Q108","chapter":0,"number":108,"question":"Chọn phương án KHÔNG ĐÚNG về nội dung kinh tế của liên minh giữa công nhân với nông dân và các tầng lớp lao động khác trong cách mạng XHCN:","options":[{"id":"SACH-DO-HUB-Q108-O1","text":"Xây dựng hệ thống chính sách an sinh xã hội"},{"id":"SACH-DO-HUB-Q108-O2","text":"Ứng dụng khoa học kỹ thuật vào sản xuất nông nghiệp"},{"id":"SACH-DO-HUB-Q108-O3","text":"Xây dựng hệ thống chính sách phát triển nông nghiệp, nông dân, nông thôn"},{"id":"SACH-DO-HUB-Q108-O4","text":"Thực hiện hợp đồng kinh tế giữa doanh nghiệp nhà nước và nông dân"}],"correctOptionId":"SACH-DO-HUB-Q108-O1","source":"Sách đỏ HUB (tài liệu lưu hành nội bộ)","explanation":"Các biện pháp như phát triển sản xuất nông nghiệp, ứng dụng khoa học kỹ thuật và hợp tác kinh tế thuộc nội dung kinh tế của liên minh. Còn chính sách an sinh xã hội trực tiếp hướng đến phúc lợi và đời sống xã hội, nên theo cách phân loại của đề, đây là phương án KHÔNG đúng về nội dung kinh tế.","topic":"Đề ôn theo sách đỏ HUB","examCode":"SACH-DO-HUB","answerStatus":"marked","basis":"Đáp án theo sách đỏ HUB"},{"id":"SACH-DO-HUB-Q109","chapter":0,"number":109,"question":"Nội dung chính trị của liên minh giữa công nhân với nông dân và các tầng lớp lao động khác trong cách mạng XHCN dựa trên nguyên tắc nào?","options":[{"id":"SACH-DO-HUB-Q109-O1","text":"Giữ vững lập trường chính trị - tư tưởng của giai cấp công nhân"},{"id":"SACH-DO-HUB-Q109-O2","text":"Kết hợp về chính trị - tư tưởng của địa chủ, nông dân và tư sản"},{"id":"SACH-DO-HUB-Q109-O3","text":"Giữ vững lập trường chính trị - tư tưởng của tầng lớp trí thức"},{"id":"SACH-DO-HUB-Q109-O4","text":"Kết hợp về chính trị - tư tưởng của công nhân, nông dân và trí thức 9S"}],"correctOptionId":"SACH-DO-HUB-Q109-O1","source":"Sách đỏ HUB (tài liệu lưu hành nội bộ)","explanation":"Về chính trị, liên minh công nhân với nông dân và các tầng lớp lao động khác cần có định hướng tư tưởng và mục tiêu chung. Vì vậy, việc giữ vững lập trường chính trị - tư tưởng của giai cấp công nhân được xác định là nguyên tắc nền tảng.","topic":"Đề ôn theo sách đỏ HUB","examCode":"SACH-DO-HUB","answerStatus":"marked","basis":"Đáp án theo sách đỏ HUB"},{"id":"SACH-DO-HUB-Q110","chapter":0,"number":110,"question":"Theo Lênin, nguyên tắc cao nhất của chuyên chính vô sản là:","options":[{"id":"SACH-DO-HUB-Q110-O1","text":"Hạn chế khối liên minh giữa giai cấp vô sản và nông dân để giai cấp vô sản có thê giữ được vai trò lãnh đạo và chính quyền nhà nước"},{"id":"SACH-DO-HUB-Q110-O2","text":"Duy trì khối liên minh giữa giai cấp vô sản và nông dân để giai cấp nông dân có thê giữ được vai trò lãnh đạo và chính quyền nhà nước"},{"id":"SACH-DO-HUB-Q110-O3","text":"Duy trì khối liên mình giữa giai cấp vô sản và nông dân dé giai cấp vô sản có thê giữ được vai trò lãnh đạo và chính quyền nhà nước"},{"id":"SACH-DO-HUB-Q110-O4","text":"Hạn chế khối liên minh giữa giai cấp vô sản và nông dân để giai cấp nông dân có thê giữ được vai trò lãnh đạo và chính quyền nhà nước"}],"correctOptionId":"SACH-DO-HUB-Q110-O3","source":"Sách đỏ HUB (tài liệu lưu hành nội bộ)","explanation":"Lênin nhấn mạnh liên minh công - nông vì đây là cơ sở xã hội rộng lớn để giai cấp vô sản duy trì vai trò lãnh đạo và chính quyền sau cách mạng. Sự liên minh này giúp kết nối lợi ích công nhân với đông đảo nông dân, tạo nền tảng chính trị và xã hội cho chế độ mới.","topic":"Đề ôn theo sách đỏ HUB","examCode":"SACH-DO-HUB","answerStatus":"marked","basis":"Đáp án theo sách đỏ HUB"},{"id":"SACH-DO-HUB-Q111","chapter":0,"number":111,"question":"Chọn phương án KHÔNG ĐÚNG về nội dung văn hóa, xã hội của liên minh giữa công nhân với nông dân và các tầng lớp lao động khác trong cách mạng XHCN:","options":[{"id":"SACH-DO-HUB-Q111-O1","text":"Nâng cao trình độ văn hóa cho nhân dân"},{"id":"SACH-DO-HUB-Q111-O2","text":"Xây dựng nên quốc phòng toàn dân"},{"id":"SACH-DO-HUB-Q111-O3","text":"Xây dựng nền văn hóa phát triển của nhân dân"},{"id":"SACH-DO-HUB-Q111-O4","text":"Xây dựng con người mới xã hội chủ nghĩa"}],"correctOptionId":"SACH-DO-HUB-Q111-O2","source":"Sách đỏ HUB (tài liệu lưu hành nội bộ)","explanation":"Xây dựng nền quốc phòng toàn dân thuộc lĩnh vực quốc phòng, an ninh, không trực tiếp là hoạt động phát triển văn hóa, giáo dục hoặc xây dựng con người. Vì đề yêu cầu chọn nội dung KHÔNG đúng về phương diện văn hóa - xã hội của liên minh, đáp án là B.","topic":"Đề ôn theo sách đỏ HUB","examCode":"SACH-DO-HUB","answerStatus":"marked","basis":"Đáp án theo sách đỏ HUB"},{"id":"SACH-DO-HUB-Q112","chapter":0,"number":112,"question":"Nội dung quan trọng nhất trong liên minh giữa công nhân với nông dân và các tầng lớp lao động khác khi tiến hành xây dựng CNXH là:","options":[{"id":"SACH-DO-HUB-Q112-O1","text":"Nội dung tư tưởng"},{"id":"SACH-DO-HUB-Q112-O2","text":"Nội dung chính trị"},{"id":"SACH-DO-HUB-Q112-O3","text":"Nội dung văn hóa- xã hội"},{"id":"SACH-DO-HUB-Q112-O4","text":"Nội dung kinh tế"}],"correctOptionId":"SACH-DO-HUB-Q112-O4","source":"Sách đỏ HUB (tài liệu lưu hành nội bộ)","explanation":"Theo lý luận về liên minh giai cấp, lợi ích kinh tế tạo ra cơ sở vật chất và động lực thường xuyên để các lực lượng gắn bó lâu dài với nhau. Vì thế, nội dung kinh tế được coi là quan trọng nhất, đồng thời làm nền tảng cho hợp tác chính trị và văn hóa - xã hội.","topic":"Đề ôn theo sách đỏ HUB","examCode":"SACH-DO-HUB","answerStatus":"marked","basis":"Đáp án theo sách đỏ HUB"},{"id":"SACH-DO-HUB-Q113","chapter":0,"number":113,"question":"Khi xã hội có giai cấp, xét về mặt kết cấu thì:","options":[{"id":"SACH-DO-HUB-Q113-O1","text":"Chỉ có các giai cấp đối kháng nhau"},{"id":"SACH-DO-HUB-Q113-O2","text":"Chỉ có những giai cấp cơ bản"},{"id":"SACH-DO-HUB-Q113-O3","text":"Có giai cấp nhưng không đối kháng nhau"},{"id":"SACH-DO-HUB-Q113-O4","text":"Có những giai cấp cơ bản và giai cấp không cơ bản"}],"correctOptionId":"SACH-DO-HUB-Q113-O4","source":"Sách đỏ HUB (tài liệu lưu hành nội bộ)","explanation":"Cơ cấu giai cấp của một xã hội không chỉ có những giai cấp gắn trực tiếp với phương thức sản xuất thống trị mà còn có các giai cấp không cơ bản tồn tại do lịch sử và sự đan xen quan hệ sản xuất. Vì vậy, phải phân biệt cả hai loại khi mô tả kết cấu xã hội.","topic":"Đề ôn theo sách đỏ HUB","examCode":"SACH-DO-HUB","answerStatus":"marked","basis":"Đáp án theo sách đỏ HUB"},{"id":"SACH-DO-HUB-Q114","chapter":0,"number":114,"question":"Theo quan điểm của chủ nghĩa Mác — Lênin, nguyên nhân quyết định sự biến đối của cộng đồng dân tộc là:","options":[{"id":"SACH-DO-HUB-Q114-O1","text":"Sự biến đổi của thời tiết, khí hậu"},{"id":"SACH-DO-HUB-Q114-O2","text":"Sự biến đổi của phương thức sản xuất"},{"id":"SACH-DO-HUB-Q114-O3","text":"Sự và chạm giữa các nền văn minh"},{"id":"SACH-DO-HUB-Q114-O4","text":"Sự biến đối di truyền của con người"}],"correctOptionId":"SACH-DO-HUB-Q114-O2","source":"Sách đỏ HUB (tài liệu lưu hành nội bộ)","explanation":"Theo chủ nghĩa duy vật lịch sử, sự biến đổi phương thức sản xuất làm thay đổi cách con người tổ chức lao động, cư trú và liên kết cộng đồng. Từ đó, hình thức cộng đồng dân tộc cũng chuyển biến, nên phương thức sản xuất được xem là nguyên nhân quyết định.","topic":"Đề ôn theo sách đỏ HUB","examCode":"SACH-DO-HUB","answerStatus":"marked","basis":"Đáp án theo sách đỏ HUB"},{"id":"SACH-DO-HUB-Q115","chapter":0,"number":115,"question":"Yếu tố nào thể hiện chủ quyền thiêng liêng của một dân tộc trong tương quan với các quốc gia — dân tộc khác?","options":[{"id":"SACH-DO-HUB-Q115-O1","text":"Lãnh thổ"},{"id":"SACH-DO-HUB-Q115-O2","text":"Nén kinh té"},{"id":"SACH-DO-HUB-Q115-O3","text":"Văn hóa"},{"id":"SACH-DO-HUB-Q115-O4","text":"Thé ché chinh tri"}],"correctOptionId":"SACH-DO-HUB-Q115-O1","source":"Sách đỏ HUB (tài liệu lưu hành nội bộ)","explanation":"Lãnh thổ là không gian xác định phạm vi tồn tại, quản lý và thực thi chủ quyền của một quốc gia - dân tộc. Vì vậy, khi đề hỏi yếu tố thể hiện chủ quyền trong quan hệ với quốc gia khác, lãnh thổ là đáp án trực tiếp nhất.","topic":"Đề ôn theo sách đỏ HUB","examCode":"SACH-DO-HUB","answerStatus":"marked","basis":"Đáp án theo sách đỏ HUB"},{"id":"SACH-DO-HUB-Q116","chapter":0,"number":116,"question":"Dân tộc, hiểu theo nghĩa hẹp là:","options":[{"id":"SACH-DO-HUB-Q116-O1","text":"Bộ lạc"},{"id":"SACH-DO-HUB-Q116-O2","text":"Quốc gia"},{"id":"SACH-DO-HUB-Q116-O3","text":"Tộc người"},{"id":"SACH-DO-HUB-Q116-O4","text":"Bộ tộc"}],"correctOptionId":"SACH-DO-HUB-Q116-O3","source":"Sách đỏ HUB (tài liệu lưu hành nội bộ)","explanation":"“Dân tộc” theo nghĩa hẹp chỉ cộng đồng tộc người có những yếu tố gắn kết về lịch sử, văn hóa, ngôn ngữ và ý thức cộng đồng. Nghĩa này khác với “dân tộc” theo nghĩa rộng, dùng để chỉ quốc gia - dân tộc.","topic":"Đề ôn theo sách đỏ HUB","examCode":"SACH-DO-HUB","answerStatus":"marked","basis":"Đáp án theo sách đỏ HUB"},{"id":"SACH-DO-HUB-Q117","chapter":0,"number":117,"question":"Theo nghĩa rộng, dân tộc là:","options":[{"id":"SACH-DO-HUB-Q117-O1","text":"Tộc người"},{"id":"SACH-DO-HUB-Q117-O2","text":"Quốc gia"},{"id":"SACH-DO-HUB-Q117-O3","text":"Thị tộc"},{"id":"SACH-DO-HUB-Q117-O4","text":"Bộ tộc"}],"correctOptionId":"SACH-DO-HUB-Q117-O2","source":"Sách đỏ HUB (tài liệu lưu hành nội bộ)","explanation":"“Dân tộc” theo nghĩa rộng là cộng đồng quốc gia có lãnh thổ, nền kinh tế, đời sống chính trị và ý thức cộng đồng chung. Do vậy, đáp án “quốc gia” phản ánh cách hiểu rộng, phân biệt với “tộc người” theo nghĩa hẹp.","topic":"Đề ôn theo sách đỏ HUB","examCode":"SACH-DO-HUB","answerStatus":"marked","basis":"Đáp án theo sách đỏ HUB"},{"id":"SACH-DO-HUB-Q118","chapter":0,"number":118,"question":"Nguyên nhân dẫn đến các cộng đồng dân cư muốn tách ra để hình thành cộng đồng dân tộc độc lập là:","options":[{"id":"SACH-DO-HUB-Q118-O1","text":"sự thức tỉnh, trưởng thành về ý thức dân tộc, ý thức về quyền sống cua mình."},{"id":"SACH-DO-HUB-Q118-O2","text":"chủ nghĩa tư bản đã phát triển thành chủ nghĩa dé quốc."},{"id":"SACH-DO-HUB-Q118-O3","text":"các quốc gia bị áp bức."},{"id":"SACH-DO-HUB-Q118-O4","text":"các quốc gia muốn độc lập."}],"correctOptionId":"SACH-DO-HUB-Q118-O1","source":"Sách đỏ HUB (tài liệu lưu hành nội bộ)","explanation":"Khi ý thức dân tộc và ý thức về quyền sống, quyền tự quyết của cộng đồng phát triển, người dân có xu hướng đòi hỏi độc lập và tự tổ chức thành một cộng đồng chính trị riêng. Đây là động lực chủ quan trực tiếp mà câu hỏi đang nói đến.","topic":"Đề ôn theo sách đỏ HUB","examCode":"SACH-DO-HUB","answerStatus":"marked","basis":"Đáp án theo sách đỏ HUB"},{"id":"SACH-DO-HUB-Q119","chapter":0,"number":119,"question":"Các dân tộc trong mỗi quốc gia và ở nhiều quốc gia muốn liên hiệp lại với nhau — là xu hướng nồi lên trong giai đoạn nào?","options":[{"id":"SACH-DO-HUB-Q119-O1","text":"Chủ nghĩa tư bản độc quyền"},{"id":"SACH-DO-HUB-Q119-O2","text":"Chủ nghĩa tư bản tự do cạnh tranh"},{"id":"SACH-DO-HUB-Q119-O3","text":"Chủ nghĩa tư bản đã phát triển thành chủ nghĩa dé quốc"},{"id":"SACH-DO-HUB-Q119-O4","text":"Tích lũy nguyên thủy của chủ nghĩa tư bản"}],"correctOptionId":"SACH-DO-HUB-Q119-O3","source":"Sách đỏ HUB (tài liệu lưu hành nội bộ)","explanation":"Trong giai đoạn chủ nghĩa tư bản phát triển thành chủ nghĩa đế quốc, sự liên hệ kinh tế và chính trị giữa các dân tộc tăng lên, thúc đẩy xu hướng liên hiệp và hợp tác vượt ra ngoài phạm vi một quốc gia. Vì thế, phương án C phù hợp với xu hướng được nêu trong đề.","topic":"Đề ôn theo sách đỏ HUB","examCode":"SACH-DO-HUB","answerStatus":"marked","basis":"Đáp án theo sách đỏ HUB"},{"id":"SACH-DO-HUB-Q120","chapter":0,"number":120,"question":"Chọn phương án đúng cho cụm từ còn thiếu: Các dân tộc đều có [.........] và quyền lợi ngang nhau trên tất cả các lĩnh vực của đời sống xã hội, không một dân tộc nào được giữ [.........], đặc lợi về kinh tế, chính trị, văn hóa.","options":[{"id":"SACH-DO-HUB-Q120-O1","text":"Nghĩa vụ/ quyền lợi"},{"id":"SACH-DO-HUB-Q120-O2","text":"Nghĩa vụ/ đặc quyền"},{"id":"SACH-DO-HUB-Q120-O3","text":"Lợi ích/ quyền lo"},{"id":"SACH-DO-HUB-Q120-O4","text":"Lợi ích/ đặc quyền"}],"correctOptionId":"SACH-DO-HUB-Q120-O2","source":"Sách đỏ HUB (tài liệu lưu hành nội bộ)","explanation":"Câu hoàn chỉnh theo sách là: các dân tộc có “nghĩa vụ” và quyền lợi ngang nhau, không dân tộc nào được giữ “đặc quyền”, đặc lợi. Hai cụm này diễn đạt yêu cầu bình đẳng về quyền, trách nhiệm và sự phản đối đặc quyền giữa các dân tộc.","topic":"Đề ôn theo sách đỏ HUB","examCode":"SACH-DO-HUB","answerStatus":"marked","basis":"Đáp án theo sách đỏ HUB"},{"id":"SACH-DO-HUB-Q121","chapter":0,"number":121,"question":"Nội dung chủ yếu và giải pháp quan trọng để Cương lĩnh dân tộc trở thành một chỉnh thê là:","options":[{"id":"SACH-DO-HUB-Q121-O1","text":"Liên hiệp công nhân tất cả các dân tộc"},{"id":"SACH-DO-HUB-Q121-O2","text":"Các dân tộc có quyền bình đảng"},{"id":"SACH-DO-HUB-Q121-O3","text":"Các dân tộc có quyền tự quyết"},{"id":"SACH-DO-HUB-Q121-O4","text":"Các dân tộc có quyền lợi riêng"}],"correctOptionId":"SACH-DO-HUB-Q121-O1","source":"Sách đỏ HUB (tài liệu lưu hành nội bộ)","explanation":"“Liên hiệp công nhân tất cả các dân tộc” kết nối yêu cầu bình đẳng và quyền tự quyết với đoàn kết quốc tế của người lao động. Vì vậy, trong Cương lĩnh dân tộc của Lênin, nội dung này là giải pháp thống nhất các mục tiêu thành một chỉnh thể.","topic":"Đề ôn theo sách đỏ HUB","examCode":"SACH-DO-HUB","answerStatus":"marked","basis":"Đáp án theo sách đỏ HUB"},{"id":"SACH-DO-HUB-Q122","chapter":0,"number":122,"question":"Nội dung nào trong Cương lĩnh dân tộc của Lênin phản ánh sự thống nhất và gắn bó chặt chẽ giữa giải phóng dân tộc và giải phóng giai cấp; giữa chủ nghĩa yêu nước và chủ nghĩa quốc tế chân chính?","options":[{"id":"SACH-DO-HUB-Q122-O1","text":"Các dân tộc có quyền tự quyết"},{"id":"SACH-DO-HUB-Q122-O2","text":"Các dân tộc có quyền bình đắng"},{"id":"SACH-DO-HUB-Q122-O3","text":"Liên hiệp công nhân tất cả các dân tộc"},{"id":"SACH-DO-HUB-Q122-O4","text":"Các dân tộc có quyền tự lựa chọn chế độ chính trị và con đường phát triển"}],"correctOptionId":"SACH-DO-HUB-Q122-O3","source":"Sách đỏ HUB (tài liệu lưu hành nội bộ)","explanation":"Liên hiệp công nhân tất cả các dân tộc thể hiện sự gắn bó giữa mục tiêu giải phóng dân tộc và giải phóng giai cấp, đồng thời thống nhất tinh thần yêu nước với chủ nghĩa quốc tế của giai cấp công nhân. Đây là lý do nội dung đó được câu hỏi nhấn mạnh.","topic":"Đề ôn theo sách đỏ HUB","examCode":"SACH-DO-HUB","answerStatus":"marked","basis":"Đáp án theo sách đỏ HUB"},{"id":"SACH-DO-HUB-Q123","chapter":0,"number":123,"question":"Theo chủ nghĩa Mác - Lênin, cơ sở để thực hiện quyền dân tộc tự quyết và xây dựng mối quan hệ hữu nghị, hợp tác giữa các dân tộc là:","options":[{"id":"SACH-DO-HUB-Q123-O1","text":"Các dân tộc có quyền tự lựa chọn chế độ chính trị và con đường phát triển"},{"id":"SACH-DO-HUB-Q123-O2","text":"Các dân tộc bị áp bức liên kết lại với nhau"},{"id":"SACH-DO-HUB-Q123-O3","text":"Liên hiệp công nhân tất cả các dân tộc"},{"id":"SACH-DO-HUB-Q123-O4","text":"Quyền bình đẳng giữa các dân tộc"}],"correctOptionId":"SACH-DO-HUB-Q123-O4","source":"Sách đỏ HUB (tài liệu lưu hành nội bộ)","explanation":"Quyền bình đẳng là điều kiện nền tảng để mỗi dân tộc có thể thực hiện quyền tự quyết mà không bị phân biệt đối xử hoặc áp đặt bởi dân tộc khác. Trên cơ sở bình đẳng mới có thể xây dựng quan hệ hữu nghị và hợp tác tự nguyện, bền vững.","topic":"Đề ôn theo sách đỏ HUB","examCode":"SACH-DO-HUB","answerStatus":"marked","basis":"Đáp án theo sách đỏ HUB"},{"id":"SACH-DO-HUB-Q124","chapter":0,"number":124,"question":"Nội dung cốt lõi của công tác tôn giáo ở nước ta trong giai đoạn hiện nay là:","options":[{"id":"SACH-DO-HUB-Q124-O1","text":"Các tôn giáo được tự do truyền đạo và hành đạo"},{"id":"SACH-DO-HUB-Q124-O2","text":"Cho phép mọi tôn giáo hoạt động"},{"id":"SACH-DO-HUB-Q124-O3","text":"Công tác vận động quần chúng"},{"id":"SACH-DO-HUB-Q124-O4","text":"Cho phép thành lập các tôn giáo mới"}],"correctOptionId":"SACH-DO-HUB-Q124-O3","source":"Sách đỏ HUB (tài liệu lưu hành nội bộ)","explanation":"Theo quan điểm của chính sách tôn giáo được trình bày trong tài liệu, trọng tâm là vận động quần chúng để tạo đồng thuận, tôn trọng nhu cầu tín ngưỡng và phát huy những đóng góp tích cực của người có đạo. Vì vậy, công tác vận động quần chúng được xác định là nội dung cốt lõi.","topic":"Đề ôn theo sách đỏ HUB","examCode":"SACH-DO-HUB","answerStatus":"marked","basis":"Đáp án theo sách đỏ HUB"},{"id":"SACH-DO-HUB-Q125","chapter":0,"number":125,"question":"Nguồn gốc hình thành tôn giáo là:","options":[{"id":"SACH-DO-HUB-Q125-O1","text":"Thượng dé ban cho nhân loại"},{"id":"SACH-DO-HUB-Q125-O2","text":"Tự nhiên, kinh tế - xã hội; Nhận thức; Tâm lý"},{"id":"SACH-DO-HUB-Q125-O3","text":"Mối quan hệ giữa thần thánh và con người"},{"id":"SACH-DO-HUB-Q125-O4","text":"Niềm tin vào cái siêu nhiên"}],"correctOptionId":"SACH-DO-HUB-Q125-O2","source":"Sách đỏ HUB (tài liệu lưu hành nội bộ)","explanation":"Theo giáo trình, tôn giáo hình thành từ nhiều nguồn gốc: điều kiện tự nhiên và kinh tế - xã hội mà con người chưa làm chủ; giới hạn nhận thức trước thế giới; và nhu cầu tâm lý, tình cảm. Phương án B bao quát cả ba nhóm nguyên nhân, không thu hẹp vào một yếu tố đơn lẻ.","topic":"Đề ôn theo sách đỏ HUB","examCode":"SACH-DO-HUB","answerStatus":"marked","basis":"Đáp án theo sách đỏ HUB"},{"id":"SACH-DO-HUB-Q126","chapter":0,"number":126,"question":"Chọn phương án đúng cho cụm từ còn thiếu: Giải quyết mối quan hệ [.........] và tôn giáo phải đảm bảo quyền tự do [.........], tôn giáo của nhân dân, quyền các dân tộc thiểu số.","options":[{"id":"SACH-DO-HUB-Q126-O1","text":"Tín ngưỡng/ dân tộc"},{"id":"SACH-DO-HUB-Q126-O2","text":"Dân tộc/ tín ngưỡng"},{"id":"SACH-DO-HUB-Q126-O3","text":"Tôn giáo/dân tộc"},{"id":"SACH-DO-HUB-Q126-O4","text":"Dân tộc/tôn giáo"}],"correctOptionId":"SACH-DO-HUB-Q126-O2","source":"Sách đỏ HUB (tài liệu lưu hành nội bộ)","explanation":"Đoạn điền khuyết yêu cầu đặt quan hệ dân tộc và tôn giáo trong sự gắn bó, đồng thời tôn trọng tự do tín ngưỡng, tôn giáo của nhân dân. Cặp từ “dân tộc / tín ngưỡng” ghép thành nội dung phù hợp với nguyên tắc chính sách được nêu.","topic":"Đề ôn theo sách đỏ HUB","examCode":"SACH-DO-HUB","answerStatus":"marked","basis":"Đáp án theo sách đỏ HUB"},{"id":"SACH-DO-HUB-Q127","chapter":0,"number":127,"question":"Nguyên nhân nào làm cho các dân tộc ở Việt Nam phân tán, xen kẽ, không có lãnh thô tộc người riêng?","options":[{"id":"SACH-DO-HUB-Q127-O1","text":"Văn hóa cư trú khác nhau của mỗi dân tộc"},{"id":"SACH-DO-HUB-Q127-O2","text":"Chính sách “chia dé trị” dé chủ nghĩa thực dân"},{"id":"SACH-DO-HUB-Q127-O3","text":"Việt Nam là nơi có các đợt chuyển cư kéo dài"},{"id":"SACH-DO-HUB-Q127-O4","text":"Điều kiện tự nhiên thay đổi"}],"correctOptionId":"SACH-DO-HUB-Q127-O3","source":"Sách đỏ HUB (tài liệu lưu hành nội bộ)","explanation":"Các đợt di cư và chuyển cư lâu dài khiến nhiều cộng đồng tộc người cùng cư trú, xen kẽ trên các vùng lãnh thổ Việt Nam. Điều đó giải thích đặc điểm phân bố không hoàn toàn tách biệt thành những lãnh thổ riêng của từng dân tộc.","topic":"Đề ôn theo sách đỏ HUB","examCode":"SACH-DO-HUB","answerStatus":"marked","basis":"Đáp án theo sách đỏ HUB"},{"id":"SACH-DO-HUB-Q128","chapter":0,"number":128,"question":"Chọn phương án KHÔNG ĐÚNG về chính sách của Dang và Nhà nước ta về tăng cường, củng cố khối đại đoàn kết dân tộc hiện nay:","options":[{"id":"SACH-DO-HUB-Q128-O1","text":"Tôn trọng và phát huy lợi ích, truyền thống, văn hoá của các dân tộc"},{"id":"SACH-DO-HUB-Q128-O2","text":"Phát triển kinh tế hàng hoá ở các vùng dân tộc thiểu sé."},{"id":"SACH-DO-HUB-Q128-O3","text":"Phân lập các dân tộc thiểu số thành các quốc gia độc lập"},{"id":"SACH-DO-HUB-Q128-O4","text":"Tăng cường bồi dưỡng, dao tạo đội ngũ cán bộ là người dân tộc thiêu số."}],"correctOptionId":"SACH-DO-HUB-Q128-O3","source":"Sách đỏ HUB (tài liệu lưu hành nội bộ)","explanation":"Chính sách đại đoàn kết dân tộc hướng tới bình đẳng, hỗ trợ phát triển và củng cố sự thống nhất của cộng đồng các dân tộc Việt Nam. Việc phân lập các dân tộc thiểu số thành quốc gia độc lập đi ngược mục tiêu đoàn kết, thống nhất ấy; vì thế là phương án KHÔNG đúng.","topic":"Đề ôn theo sách đỏ HUB","examCode":"SACH-DO-HUB","answerStatus":"marked","basis":"Đáp án theo sách đỏ HUB"},{"id":"SACH-DO-HUB-Q129","chapter":0,"number":129,"question":"_ Về chính trị, đặc trưng nỗi bật trong quan hệ dân tộc ở nước ta là:","options":[{"id":"SACH-DO-HUB-Q129-O1","text":"sự cố kết dân tộc, hoà hợp dân tộc trong một cộng đông thống nhất"},{"id":"SACH-DO-HUB-Q129-O2","text":"sự phân bố đan xen nhau, không một dân tộc nào có lãnh thổ riêng"},{"id":"SACH-DO-HUB-Q129-O3","text":"có sự chênh lệch về trình độ phát triển kinh tế - xã hội giữa các dân tộc"},{"id":"SACH-DO-HUB-Q129-O4","text":"các dân tộc có bản sắc văn hoá riêng, đa dạng, phong phú"}],"correctOptionId":"SACH-DO-HUB-Q129-O1","source":"Sách đỏ HUB (tài liệu lưu hành nội bộ)","explanation":"Xét về chính trị, quan hệ giữa các dân tộc ở Việt Nam được tài liệu nhấn mạnh ở sự gắn bó, hòa hợp và đoàn kết trong cộng đồng quốc gia thống nhất. Đó là đặc trưng phản ánh yêu cầu cùng tham gia xây dựng và bảo vệ đất nước.","topic":"Đề ôn theo sách đỏ HUB","examCode":"SACH-DO-HUB","answerStatus":"marked","basis":"Đáp án theo sách đỏ HUB"},{"id":"SACH-DO-HUB-Q130","chapter":0,"number":130,"question":"Yếu tố nào là cơ sở gắn kết các bộ phận, các thành viên của dân tộc, tao nên nền tảng vững chắc cho cộng đồng dân tộc?","options":[{"id":"SACH-DO-HUB-Q130-O1","text":"Có chung một vùng lãnh thổ ồn định"},{"id":"SACH-DO-HUB-Q130-O2","text":"Có chung một phương thức sinh hoạt kinh tế"},{"id":"SACH-DO-HUB-Q130-O3","text":"Có chung một ngôn ngữ làm công cụ giao tiếp"},{"id":"SACH-DO-HUB-Q130-O4","text":"Có chung một nền văn hóa và tâm lý"}],"correctOptionId":"SACH-DO-HUB-Q130-O2","source":"Sách đỏ HUB (tài liệu lưu hành nội bộ)","explanation":"Cùng một phương thức sinh hoạt kinh tế giúp các thành viên cộng đồng có các mối quan hệ sản xuất, trao đổi và phụ thuộc lẫn nhau tương đối ổn định. Theo cách tiếp cận duy vật lịch sử, sự gắn kết kinh tế là nền tảng vật chất quan trọng cho cộng đồng dân tộc.","topic":"Đề ôn theo sách đỏ HUB","examCode":"SACH-DO-HUB","answerStatus":"marked","basis":"Đáp án theo sách đỏ HUB"},{"id":"SACH-DO-HUB-Q131","chapter":0,"number":131,"question":"Tôn giáo có những tính chất nào?","options":[{"id":"SACH-DO-HUB-Q131-O1","text":"Đền bù hư ảo, thế giới quan, điều chỉnh hành vi, giao tiếp, liên kết cộng đồng"},{"id":"SACH-DO-HUB-Q131-O2","text":"Tính lịch sử, tính quần chúng, tính chính trị và đền bù hư ảo"},{"id":"SACH-DO-HUB-Q131-O3","text":"Tinh lịch sử, tính quan chúng và tính chính trị"},{"id":"SACH-DO-HUB-Q131-O4","text":"Triết lý, đền bù hư ảo, thế giới quan, điều chỉnh hành vi, giao tiếp, liên kết cộng đông"}],"correctOptionId":"SACH-DO-HUB-Q131-O3","source":"Sách đỏ HUB (tài liệu lưu hành nội bộ)","explanation":"Tôn giáo xuất hiện và biến đổi trong những điều kiện lịch sử nhất định, có sự tham gia của đông đảo quần chúng và có thể liên hệ với quyền lực, lợi ích xã hội. Vì vậy, giáo trình khái quát ba tính chất là lịch sử, quần chúng và chính trị.","topic":"Đề ôn theo sách đỏ HUB","examCode":"SACH-DO-HUB","answerStatus":"marked","basis":"Đáp án theo sách đỏ HUB"},{"id":"SACH-DO-HUB-Q132","chapter":0,"number":132,"question":"Tôn giáo có những chức năng nào?","options":[{"id":"SACH-DO-HUB-Q132-O1","text":"Đền bù hư ảo, thế giới quan, điều chỉnh hành vi"},{"id":"SACH-DO-HUB-Q132-O2","text":"Đền bù hư ảo, thế giới quan, điều chỉnh hành vi, giao tiếp"},{"id":"SACH-DO-HUB-Q132-O3","text":"Đền bù hư ảo, thế giới quan, điều chỉnh hành vi, giao tiếp, liên kết cộng đồng"},{"id":"SACH-DO-HUB-Q132-O4","text":"Đền bù hư ảo, thế giới quan, điều chỉnh hành vi, giao tiép, liên kết cộng đồng, giáo dục"}],"correctOptionId":"SACH-DO-HUB-Q132-O3","source":"Sách đỏ HUB (tài liệu lưu hành nội bộ)","explanation":"Tôn giáo không chỉ giải thích thế giới theo hệ thống niềm tin mà còn an ủi về mặt tinh thần, định hướng hành vi, tạo giao tiếp và gắn kết những người cùng tín ngưỡng. Phương án C bao quát đủ các chức năng được liệt kê trong tài liệu.","topic":"Đề ôn theo sách đỏ HUB","examCode":"SACH-DO-HUB","answerStatus":"marked","basis":"Đáp án theo sách đỏ HUB"},{"id":"SACH-DO-HUB-Q133","chapter":0,"number":133,"question":"Thai độ của những người cộng sản đối với tôn giáo là:","options":[{"id":"SACH-DO-HUB-Q133-O1","text":"Xem thường những nhu cầu tín ngưỡng, tôn giáo của nhân dân"},{"id":"SACH-DO-HUB-Q133-O2","text":"Tôn trọng quyền tự do tín ngưỡng, theo hoặc không theo tôn giáo của nhân dân"},{"id":"SACH-DO-HUB-Q133-O3","text":"Trấn áp những nhu cầu tín ngưỡng, tôn giáo của nhân dân"},{"id":"SACH-DO-HUB-Q133-O4","text":"Đả kích những nhu cầu tín ngưỡng, tôn giáo của nhân dân"}],"correctOptionId":"SACH-DO-HUB-Q133-O2","source":"Sách đỏ HUB (tài liệu lưu hành nội bộ)","explanation":"Theo nguyên tắc được nêu, quyền theo hoặc không theo tôn giáo là quyền tự do của mỗi người. Thái độ tôn trọng lựa chọn tín ngưỡng của nhân dân phù hợp với mục tiêu đoàn kết xã hội và bảo đảm quyền tự do tín ngưỡng.","topic":"Đề ôn theo sách đỏ HUB","examCode":"SACH-DO-HUB","answerStatus":"marked","basis":"Đáp án theo sách đỏ HUB"},{"id":"SACH-DO-HUB-Q134","chapter":0,"number":134,"question":"Chức năng nào thể hiện tôn giáo là ngọn cờ tập hợp các lực lượng đấu tranh chống áp bức, bóc lột, chống lại các thế lực chính trị - xã hội phản tiến bộ đương thời?","options":[{"id":"SACH-DO-HUB-Q134-O1","text":"Đền bù hư ảo"},{"id":"SACH-DO-HUB-Q134-O2","text":"Liên kết cộng dong"},{"id":"SACH-DO-HUB-Q134-O3","text":"Thế giới quan"},{"id":"SACH-DO-HUB-Q134-O4","text":"Điều chỉnh hành vi"}],"correctOptionId":"SACH-DO-HUB-Q134-O2","source":"Sách đỏ HUB (tài liệu lưu hành nội bộ)","explanation":"Tôn giáo có thể tạo ra sự đồng nhất về niềm tin, chuẩn mực và sinh hoạt, giúp người cùng cộng đồng tập hợp và phối hợp hành động. Khi niềm tin được sử dụng làm biểu tượng chung cho một phong trào, chức năng “liên kết cộng đồng” được thể hiện rõ.","topic":"Đề ôn theo sách đỏ HUB","examCode":"SACH-DO-HUB","answerStatus":"marked","basis":"Đáp án theo sách đỏ HUB"},{"id":"SACH-DO-HUB-Q135","chapter":0,"number":135,"question":"Gia đình là hình thức cộng đồng đặc biệt, mà con người chung sống với nhau bởi hai môi quan hệ cơ bản là:","options":[{"id":"SACH-DO-HUB-Q135-O1","text":"Quan hệ hôn nhân và quan hệ huyết thống"},{"id":"SACH-DO-HUB-Q135-O2","text":"Quan hệ hôn nhân và quan hệ nuôi dưỡng"},{"id":"SACH-DO-HUB-Q135-O3","text":"Quan hệ nuôi dưỡng và quan hệ huyết thống"},{"id":"SACH-DO-HUB-Q135-O4","text":"Quan hệ huyết thống và giáo dục con cái"}],"correctOptionId":"SACH-DO-HUB-Q135-O1","source":"Sách đỏ HUB (tài liệu lưu hành nội bộ)","explanation":"Gia đình được hình thành và duy trì chủ yếu từ hai quan hệ nền tảng: hôn nhân giữa vợ chồng và huyết thống giữa các thế hệ, người thân. Những mối quan hệ ấy tạo ra cộng đồng sinh hoạt và trách nhiệm đặc thù của gia đình.","topic":"Đề ôn theo sách đỏ HUB","examCode":"SACH-DO-HUB","answerStatus":"marked","basis":"Đáp án theo sách đỏ HUB"},{"id":"SACH-DO-HUB-Q136","chapter":0,"number":136,"question":"Chọn phương án đúng cho cụm từ còn thiếu: “những trật tự xã hội, là do hai loại sản xuất quyết định: một mặt là do trình độ phát triển của lao động và mặt khác là do trình độ phát triển của [......]” (C. Mác & Ph. Ăngghen: Toàn tap. Tap 3. Nxb Chính tri quốc gia, Hà Nội, 2005, tr.41)","options":[{"id":"SACH-DO-HUB-Q136-O1","text":"Doanh nghiệp"},{"id":"SACH-DO-HUB-Q136-O2","text":"Xã hội"},{"id":"SACH-DO-HUB-Q136-O3","text":"Hợp tác xã"},{"id":"SACH-DO-HUB-Q136-O4","text":"Gia đình"}],"correctOptionId":"SACH-DO-HUB-Q136-O4","source":"Sách đỏ HUB (tài liệu lưu hành nội bộ)","explanation":"Trong trích dẫn của Mác và Ăngghen, hai loại sản xuất gồm sản xuất tư liệu sinh hoạt và sản xuất ra chính con người, gắn với sự phát triển của gia đình. Vì thế, từ cần điền là “gia đình”, phản ánh quan hệ giữa tái sản xuất con người và trật tự xã hội.","topic":"Đề ôn theo sách đỏ HUB","examCode":"SACH-DO-HUB","answerStatus":"marked","basis":"Đáp án theo sách đỏ HUB"},{"id":"SACH-DO-HUB-Q137","chapter":0,"number":137,"question":"Cộng đồng xã hội đầu tiên đáp ứng nhu cầu quan hệ xã hội của mỗi cá nhân và cũng là môi trường đầu tiên mà mỗi cá nhân học và thực hiện quan hệ xã hội, là:","options":[{"id":"SACH-DO-HUB-Q137-O1","text":"Trường học"},{"id":"SACH-DO-HUB-Q137-O2","text":"Gia đình"},{"id":"SACH-DO-HUB-Q137-O3","text":"Doanh nghiệp"},{"id":"SACH-DO-HUB-Q137-O4","text":"Khu phố"}],"correctOptionId":"SACH-DO-HUB-Q137-O2","source":"Sách đỏ HUB (tài liệu lưu hành nội bộ)","explanation":"Gia đình thường là môi trường đầu tiên mà cá nhân được chăm sóc, giao tiếp, học chuẩn mực và xây dựng các quan hệ xã hội. Do đó, nó được coi là cộng đồng xã hội đầu tiên và là nơi diễn ra quá trình xã hội hóa ban đầu.","topic":"Đề ôn theo sách đỏ HUB","examCode":"SACH-DO-HUB","answerStatus":"marked","basis":"Đáp án theo sách đỏ HUB"},{"id":"SACH-DO-HUB-Q138","chapter":0,"number":138,"question":"Chức năng nào của gia đình đảm bảo tái sản xuất nguồn lao động và sức lao động cho xã hội?","options":[{"id":"SACH-DO-HUB-Q138-O1","text":"Chức năng nuôi dưỡng, giáo dục"},{"id":"SACH-DO-HUB-Q138-O2","text":"Chức năng kinh tế"},{"id":"SACH-DO-HUB-Q138-O3","text":"Chức năng tái sản xuất ra con người"},{"id":"SACH-DO-HUB-Q138-O4","text":"Chức năng thỏa mãn các nhu cầu tâm sinh lý, duy trì tình cảm"}],"correctOptionId":"SACH-DO-HUB-Q138-O3","source":"Sách đỏ HUB (tài liệu lưu hành nội bộ)","explanation":"Chức năng tái sản xuất ra con người gắn với sinh đẻ, duy trì các thế hệ và nguồn nhân lực kế tiếp. Bởi vậy, khi hỏi chức năng bảo đảm tái sản xuất nguồn lao động và sức lao động cho xã hội, tài liệu chọn chức năng này.","topic":"Đề ôn theo sách đỏ HUB","examCode":"SACH-DO-HUB","answerStatus":"marked","basis":"Đáp án theo sách đỏ HUB"},{"id":"SACH-DO-HUB-Q139","chapter":0,"number":139,"question":"Chức năng nào của gia đình thực hiện việc tái sản xuất, duy trì nòi giống, nuôi dưỡng nâng cao thê lực, trí lực?","options":[{"id":"SACH-DO-HUB-Q139-O1","text":"Chức năng tái sản xuất ra con người"},{"id":"SACH-DO-HUB-Q139-O2","text":"Chức năng duy trì quyền thừa kế"},{"id":"SACH-DO-HUB-Q139-O3","text":"Chức năng kinh tế và tổ chức đời sống gia đình"},{"id":"SACH-DO-HUB-Q139-O4","text":"Chức năng giáo dục"}],"correctOptionId":"SACH-DO-HUB-Q139-O1","source":"Sách đỏ HUB (tài liệu lưu hành nội bộ)","explanation":"Câu hỏi gom các hoạt động duy trì nòi giống, tái sản xuất con người và bảo đảm sự tiếp nối các thế hệ. Trong hệ thống phân loại của sách đỏ, đây là nội dung của chức năng tái sản xuất ra con người, nên đáp án A được đánh dấu.","topic":"Đề ôn theo sách đỏ HUB","examCode":"SACH-DO-HUB","answerStatus":"marked","basis":"Đáp án theo sách đỏ HUB"},{"id":"SACH-DO-HUB-Q140","chapter":0,"number":140,"question":"Chọn phương án KHÔNG PHẢI quan hệ huyết thống trong gia đình:","options":[{"id":"SACH-DO-HUB-Q140-O1","text":"Quan hệ giữa anh chị em trong gia đình"},{"id":"SACH-DO-HUB-Q140-O2","text":"Quan hệ giữa ông bà và cháu"},{"id":"SACH-DO-HUB-Q140-O3","text":"Quan hệ giữa vợ và chồng"},{"id":"SACH-DO-HUB-Q140-O4","text":"Quan hệ giữa cha mẹ và con cái"}],"correctOptionId":"SACH-DO-HUB-Q140-O3","source":"Sách đỏ HUB (tài liệu lưu hành nội bộ)","explanation":"Quan hệ vợ chồng được thiết lập trên cơ sở hôn nhân, không phải quan hệ huyết thống. Trong khi đó, quan hệ cha mẹ - con, ông bà - cháu và anh chị em thuộc mạng lưới quan hệ huyết thống; vì vậy đề chọn C cho phương án KHÔNG phải.","topic":"Đề ôn theo sách đỏ HUB","examCode":"SACH-DO-HUB","answerStatus":"marked","basis":"Đáp án theo sách đỏ HUB"},{"id":"SACH-DO-HUB-Q141","chapter":0,"number":141,"question":"Gia đình phải thực hiện chức năng nào dé đám bảo nguồn sinh sống, đáp ứng nhu cầu vat chat, tinh than?","options":[{"id":"SACH-DO-HUB-Q141-O1","text":"Chức năng kinh tế, tổ chức tiêu dùng"},{"id":"SACH-DO-HUB-Q141-O2","text":"Chức năng tái sản xuất con người"},{"id":"SACH-DO-HUB-Q141-O3","text":"Chức năng nuôi dưỡng, giáo dục"},{"id":"SACH-DO-HUB-Q141-O4","text":"Chức năng thỏa mãn các nhu cầu tâm sinh lý, duy trì tình cảm"}],"correctOptionId":"SACH-DO-HUB-Q141-O1","source":"Sách đỏ HUB (tài liệu lưu hành nội bộ)","explanation":"Chức năng kinh tế và tổ chức tiêu dùng bao gồm tạo nguồn thu nhập, phân bổ chi tiêu và sử dụng nguồn lực để bảo đảm đời sống gia đình. Nhờ đó, gia đình đáp ứng được nhu cầu vật chất và tạo điều kiện cho các nhu cầu tinh thần.","topic":"Đề ôn theo sách đỏ HUB","examCode":"SACH-DO-HUB","answerStatus":"marked","basis":"Đáp án theo sách đỏ HUB"},{"id":"SACH-DO-HUB-Q142","chapter":0,"number":142,"question":"Chức năng nào của gia đình ảnh hưởng lâu dài và toàn diện đối với mỗi cá nhân trong cuộc đòi?","options":[{"id":"SACH-DO-HUB-Q142-O1","text":"Chức năng cầu nối giữa cá nhân với xã hội"},{"id":"SACH-DO-HUB-Q142-O2","text":"Chức năng nuôi dưỡng, giáo dục"},{"id":"SACH-DO-HUB-Q142-O3","text":"Chức năng tái sản xuất con người"},{"id":"SACH-DO-HUB-Q142-O4","text":"Chức năng thỏa mãn các nhu cầu tâm sinh lý, duy trì tình cảm"}],"correctOptionId":"SACH-DO-HUB-Q142-O2","source":"Sách đỏ HUB (tài liệu lưu hành nội bộ)","explanation":"Gia đình nuôi dưỡng, giáo dục mỗi người từ nhỏ và tác động lâu dài đến nhân cách, giá trị, thói quen, cách ứng xử. Vì thế, chức năng nuôi dưỡng, giáo dục có ảnh hưởng toàn diện và bền vững đối với từng cá nhân.","topic":"Đề ôn theo sách đỏ HUB","examCode":"SACH-DO-HUB","answerStatus":"marked","basis":"Đáp án theo sách đỏ HUB"},{"id":"SACH-DO-HUB-Q143","chapter":0,"number":143,"question":"\"Nếu không giải phóng phụ nữ là xây dựng chủ nghĩa xã hội chỉ một nửa\" là quan điểm của ai?","options":[{"id":"SACH-DO-HUB-Q143-O1","text":"Lênin"},{"id":"SACH-DO-HUB-Q143-O2","text":"Cac Mac"},{"id":"SACH-DO-HUB-Q143-O3","text":"Hồ Chi Minh"},{"id":"SACH-DO-HUB-Q143-O4","text":"Ph. Ăngghen"}],"correctOptionId":"SACH-DO-HUB-Q143-O3","source":"Sách đỏ HUB (tài liệu lưu hành nội bộ)","explanation":"Câu nói nhấn mạnh rằng việc xây dựng chủ nghĩa xã hội sẽ không đầy đủ nếu phụ nữ chưa được giải phóng và tham gia bình đẳng. Trong tài liệu, quan điểm này được gắn với Chủ tịch Hồ Chí Minh.","topic":"Đề ôn theo sách đỏ HUB","examCode":"SACH-DO-HUB","answerStatus":"marked","basis":"Đáp án theo sách đỏ HUB"},{"id":"SACH-DO-HUB-Q144","chapter":0,"number":144,"question":"Gia đình thực hiện chức năng nào dé góp phan to lớn vào việc đào tao thế hệ tương lai của xã hội, giúp duy trì sự trường tồn của xã hội và xã hội hóa cá nhân?","options":[{"id":"SACH-DO-HUB-Q144-O1","text":"Chức năng tái sản xuất ra con người"},{"id":"SACH-DO-HUB-Q144-O2","text":"Chức năng nuôi dưỡng, giáo dục"},{"id":"SACH-DO-HUB-Q144-O3","text":"Chức năng kinh tế và tổ chức tiêu dung"},{"id":"SACH-DO-HUB-Q144-O4","text":"Chức năng thỏa mãn nhu cầu tâm sinh lý, duy trì tình cảm gia đình"}],"correctOptionId":"SACH-DO-HUB-Q144-O2","source":"Sách đỏ HUB (tài liệu lưu hành nội bộ)","explanation":"Gia đình truyền đạt kiến thức, kỹ năng, chuẩn mực, đạo đức và cách ứng xử cho các thế hệ sau. Hoạt động nuôi dưỡng, giáo dục giúp hình thành con người cho xã hội và tạo môi trường xã hội hóa ban đầu, nên đáp án B phù hợp.","topic":"Đề ôn theo sách đỏ HUB","examCode":"SACH-DO-HUB","answerStatus":"marked","basis":"Đáp án theo sách đỏ HUB"},{"id":"SACH-DO-HUB-Q145","chapter":0,"number":145,"question":"Trong khi thực hiện chức năng kinh tế và tổ chức tiêu dùng, đặc thù của gia đình mà các đơn vị kinh tế khác không có được là:","options":[{"id":"SACH-DO-HUB-Q145-O1","text":"Gia đình là đơn vị duy nhất sản xuất và tái sản xuất ra tư liệu sản xuất cho xã hội"},{"id":"SACH-DO-HUB-Q145-O2","text":"Gia đình là đơn vị duy nhất sản xuất và tái sản xuất ra tư liệu tiêu dùng cho xã hội"},{"id":"SACH-DO-HUB-Q145-O3","text":"Gia đình là đơn vị duy nhất sản xuất và tải sản xuất ra sức lao động cho xã hội"},{"id":"SACH-DO-HUB-Q145-O4","text":"Gia đình là đơn vị duy nhất sản xuất và tái sản xuất ra của cải cho xã hội"}],"correctOptionId":"SACH-DO-HUB-Q145-O3","source":"Sách đỏ HUB (tài liệu lưu hành nội bộ)","explanation":"Khác với doanh nghiệp chủ yếu sản xuất hàng hóa hoặc cung cấp dịch vụ, gia đình còn đảm nhận việc duy trì các thế hệ và góp phần tái sản xuất sức lao động cho xã hội. Vì thế, câu hỏi nhấn mạnh đặc thù của gia đình trong sản xuất và tái sản xuất sức lao động.","topic":"Đề ôn theo sách đỏ HUB","examCode":"SACH-DO-HUB","answerStatus":"marked","basis":"Đáp án theo sách đỏ HUB"},{"id":"SACH-DO-HUB-Q146","chapter":0,"number":146,"question":"Chọn phương án KHÔNG ĐÚNG khi bàn về vị trí của gia đình:","options":[{"id":"SACH-DO-HUB-Q146-O1","text":"Gia đình là yếu tố quan trọng nhất trong lực lượng sản xuất"},{"id":"SACH-DO-HUB-Q146-O2","text":"Gia đình là tế bào của xã hội"},{"id":"SACH-DO-HUB-Q146-O3","text":"Gia đình là tổ 4m thân yêu của mỗi người"},{"id":"SACH-DO-HUB-Q146-O4","text":"Gia đình là cầu nối giữa cá nhân và xã hội"}],"correctOptionId":"SACH-DO-HUB-Q146-O1","source":"Sách đỏ HUB (tài liệu lưu hành nội bộ)","explanation":"Gia đình là tế bào của xã hội, là môi trường gắn kết cá nhân với cộng đồng, nhưng không thể coi là “yếu tố quan trọng nhất trong lực lượng sản xuất” theo cách phân tích kinh tế học. Vì câu hỏi chọn phương án KHÔNG đúng về vị trí gia đình, đáp án là A.","topic":"Đề ôn theo sách đỏ HUB","examCode":"SACH-DO-HUB","answerStatus":"marked","basis":"Đáp án theo sách đỏ HUB"},{"id":"SACH-DO-HUB-Q147","chapter":0,"number":147,"question":"Xu hướng biến đối về quy mô của gia đình Việt Nam hiện nay là:","options":[{"id":"SACH-DO-HUB-Q147-O1","text":"thu nhỏ lại"},{"id":"SACH-DO-HUB-Q147-O2","text":"tăng lên"},{"id":"SACH-DO-HUB-Q147-O3","text":"ôn định không thay đối so với trước đây"},{"id":"SACH-DO-HUB-Q147-O4","text":"vừa tăng lên vừa thu nhỏ lại"}],"correctOptionId":"SACH-DO-HUB-Q147-O1","source":"Sách đỏ HUB (tài liệu lưu hành nội bộ)","explanation":"Xu hướng phổ biến của quy mô hộ gia đình Việt Nam trong thời kỳ hiện đại là giảm số thành viên và tăng tỷ lệ gia đình hạt nhân. Thay đổi về nghề nghiệp, đô thị hóa và điều kiện cư trú là các yếu tố góp phần vào xu hướng thu nhỏ ấy.","topic":"Đề ôn theo sách đỏ HUB","examCode":"SACH-DO-HUB","answerStatus":"marked","basis":"Đáp án theo sách đỏ HUB"},{"id":"SACH-DO-HUB-Q148","chapter":0,"number":148,"question":"Voi chức năng chính trị, gia đình là:","options":[{"id":"SACH-DO-HUB-Q148-O1","text":"nơi lưu giữ truyền thống văn hóa của dân tộc cũng như tộc người"},{"id":"SACH-DO-HUB-Q148-O2","text":"câu nối của mối quan hệ giữa nhà nước với công dân"},{"id":"SACH-DO-HUB-Q148-O3","text":"nơi đáp ứng nhu cầu tâm, sinh lý tự nhiên của con người, duy trì nòi giống"},{"id":"SACH-DO-HUB-Q148-O4","text":"nơi nuôi dưỡng, dạy dỗ con cái trở thành người có ích"}],"correctOptionId":"SACH-DO-HUB-Q148-O2","source":"Sách đỏ HUB (tài liệu lưu hành nội bộ)","explanation":"Gia đình vừa tiếp nhận, thực hiện chính sách pháp luật của nhà nước vừa phản ánh nhu cầu, ý kiến của các thành viên trong xã hội. Vì vậy, ở phương diện chính trị, gia đình đóng vai trò cầu nối giữa nhà nước với công dân.","topic":"Đề ôn theo sách đỏ HUB","examCode":"SACH-DO-HUB","answerStatus":"marked","basis":"Đáp án theo sách đỏ HUB"},{"id":"SACH-DO-HUB-Q149","chapter":0,"number":149,"question":"Theo Ph. Ăngghen, cơ sở nào làm cho hôn nhân được thực hiện dựa trên cơ sở tình yêu chứ không phải vì lý do kinh tế, địa vị xã hội hay một sự tính toán nào khác?","options":[{"id":"SACH-DO-HUB-Q149-O1","text":"Sự phát triển của lực lượng sản xuất"},{"id":"SACH-DO-HUB-Q149-O2","text":"Tư liệu sản xuất chuyển thành tài sản chung"},{"id":"SACH-DO-HUB-Q149-O3","text":"Gia đình trực tiếp sản xuất và tái sản xuất ra của cải vật chất và sức lao động"},{"id":"SACH-DO-HUB-Q149-O4","text":"Gia đình sử dụng hợp lý thu nhập của các thành viên vào việc đảm bảo đời sống"}],"correctOptionId":"SACH-DO-HUB-Q149-O2","source":"Sách đỏ HUB (tài liệu lưu hành nội bộ)","explanation":"Theo cách lập luận được nêu trong giáo trình về Ăngghen, khi tư liệu sản xuất trở thành tài sản chung và cơ sở kinh tế của hôn nhân vì tài sản suy giảm, quan hệ hôn nhân có điều kiện dựa nhiều hơn trên tình yêu tự nguyện. Vì vậy, đáp án nhấn mạnh sự thay đổi chế độ sở hữu.","topic":"Đề ôn theo sách đỏ HUB","examCode":"SACH-DO-HUB","answerStatus":"marked","basis":"Đáp án theo sách đỏ HUB"},{"id":"SACH-DO-HUB-Q150","chapter":0,"number":150,"question":"Chọn phương án đúng cho cụm từ còn thiếu: Theo Lênin, muốn giải phóng hoàn toàn và thật sự cho phụ nữ, cần thay thế nền kinh tế gia đình cá thể bằng nền kinh tế [......] quy mô lớn.","options":[{"id":"SACH-DO-HUB-Q150-O1","text":"Xã hội hóa"},{"id":"SACH-DO-HUB-Q150-O2","text":"Tư nhân hóa"},{"id":"SACH-DO-HUB-Q150-O3","text":"Quốc hữu hóa"},{"id":"SACH-DO-HUB-Q150-O4","text":"Tư bản hóa"}],"correctOptionId":"SACH-DO-HUB-Q150-O1","source":"Sách đỏ HUB (tài liệu lưu hành nội bộ)","explanation":"Lênin cho rằng giải phóng phụ nữ không chỉ bằng tuyên bố bình đẳng pháp lý mà còn cần giải phóng họ khỏi gánh nặng lao động gia đình cá thể. “Xã hội hóa” nền kinh tế gia đình với quy mô lớn tạo điều kiện tổ chức dịch vụ và lao động xã hội, giúp phụ nữ tham gia bình đẳng hơn.","topic":"Đề ôn theo sách đỏ HUB","examCode":"SACH-DO-HUB","answerStatus":"marked","basis":"Đáp án theo sách đỏ HUB"},{"id":"SACH-DO-HUB-Q151","chapter":0,"number":151,"question":"Quan hệ nào là cơ sở pháp lý cho sự tồn tại của mỗi gia đình?","options":[{"id":"SACH-DO-HUB-Q151-O1","text":"Nuôi dưỡng"},{"id":"SACH-DO-HUB-Q151-O2","text":"Huyết thống"},{"id":"SACH-DO-HUB-Q151-O3","text":"Hôn nhân"},{"id":"SACH-DO-HUB-Q151-O4","text":"Kinh tế"}],"correctOptionId":"SACH-DO-HUB-Q151-O3","source":"Sách đỏ HUB (tài liệu lưu hành nội bộ)","explanation":"Hôn nhân là quan hệ được pháp luật thừa nhận, xác lập quyền và nghĩa vụ giữa vợ và chồng, đồng thời là cơ sở hình thành nhiều quan hệ gia đình. Vì thế, trong cách hỏi về căn cứ pháp lý, “hôn nhân” là đáp án được chọn.","topic":"Đề ôn theo sách đỏ HUB","examCode":"SACH-DO-HUB","answerStatus":"marked","basis":"Đáp án theo sách đỏ HUB"},{"id":"SACH-DO-HUB-Q152","chapter":0,"number":152,"question":"Quan hệ nào nảy sinh từ quan hệ hôn nhân và là mối quan hệ tự nhiên, là yếu tố mạnh mẽ nhất gắn kết các thành viên trong gia đình?","options":[{"id":"SACH-DO-HUB-Q152-O1","text":"Nuôi dưỡng"},{"id":"SACH-DO-HUB-Q152-O2","text":"Hôn nhân"},{"id":"SACH-DO-HUB-Q152-O3","text":"Huyết thống"},{"id":"SACH-DO-HUB-Q152-O4","text":"Chính trị"}],"correctOptionId":"SACH-DO-HUB-Q152-O3","source":"Sách đỏ HUB (tài liệu lưu hành nội bộ)","explanation":"Quan hệ huyết thống là mối liên hệ giữa những người có chung nguồn gốc sinh học, thường phát sinh và được mở rộng qua các thế hệ từ quan hệ hôn nhân. Nó tạo ra sự gắn bó tự nhiên và trách nhiệm giữa ông bà, cha mẹ, con cháu.","topic":"Đề ôn theo sách đỏ HUB","examCode":"SACH-DO-HUB","answerStatus":"marked","basis":"Đáp án theo sách đỏ HUB"},{"id":"SACH-DO-HUB-Q153","chapter":0,"number":153,"question":"Chọn phương án KHÔNG ĐÚNG về điều kiện của chế độ hôn nhân tiến bộ:","options":[{"id":"SACH-DO-HUB-Q153-O1","text":"Hôn nhân được đảm bảo về pháp lý"},{"id":"SACH-DO-HUB-Q153-O2","text":"Hôn nhân một vợ một chồng, vợ chồng bình đăng"},{"id":"SACH-DO-HUB-Q153-O3","text":"Hôn nhân tự nguyện"},{"id":"SACH-DO-HUB-Q153-O4","text":"Hôn nhân vì mục dich vụ lợi"}],"correctOptionId":"SACH-DO-HUB-Q153-O4","source":"Sách đỏ HUB (tài liệu lưu hành nội bộ)","explanation":"Hôn nhân tiến bộ nhấn mạnh sự tự nguyện, bình đẳng, một vợ một chồng và được pháp luật bảo đảm. Kết hôn chỉ vì mục đích vụ lợi không phù hợp với các giá trị đó, nên đây là điều kiện KHÔNG đúng mà đề yêu cầu chọn.","topic":"Đề ôn theo sách đỏ HUB","examCode":"SACH-DO-HUB","answerStatus":"marked","basis":"Đáp án theo sách đỏ HUB"},{"id":"SACH-DO-HUB-Q154","chapter":0,"number":154,"question":"Theo chủ nghĩa Mác - Lênin, trong các xã hội dựa trên chế độ tư hữu, thực chất của chế độ một vợ một chồng đối với người phụ nữ, là:","options":[{"id":"SACH-DO-HUB-Q154-O1","text":"Chế độ một vợ một chồng sinh ra từ sự tập trung nhiều của cải vào người đàn ông, và nguyện vọng chuyển của cải cho con cái của người đàn ông ấy"},{"id":"SACH-DO-HUB-Q154-O2","text":"Chế độ một vợ một chồng sinh ra từ sự tình yêu chân chính và bình đẳng của cả người nam và người nữ"},{"id":"SACH-DO-HUB-Q154-O3","text":"Chế độ một vợ một chồng sinh ra từ sự đấu tranh của người phụ nữ"},{"id":"SACH-DO-HUB-Q154-O4","text":"Chế độ một vợ một chồng sinh ra từ phong tục, tập quán"}],"correctOptionId":"SACH-DO-HUB-Q154-O1","source":"Sách đỏ HUB (tài liệu lưu hành nội bộ)","explanation":"Trong phân tích lịch sử của chủ nghĩa Mác - Lênin về xã hội dựa trên tư hữu, sự tích lũy tài sản vào tay người đàn ông và mong muốn truyền tài sản cho con đẻ góp phần định hình chế độ hôn nhân một vợ một chồng đối với phụ nữ. Đây là cách giải thích nguồn gốc kinh tế - xã hội của chế độ ấy trong tài liệu.","topic":"Đề ôn theo sách đỏ HUB","examCode":"SACH-DO-HUB","answerStatus":"marked","basis":"Đáp án theo sách đỏ HUB"},{"id":"SACH-DO-HUB-Q155","chapter":0,"number":155,"question":"Điểm tương đồng giữa giáo dục gia đình truyền thống và giáo dục của xã hội mới là:","options":[{"id":"SACH-DO-HUB-Q155-O1","text":"Đầu tư mạnh mẽ về tài chính cho giáo dục con cái"},{"id":"SACH-DO-HUB-Q155-O2","text":"Hướng đến giáo dục kiến thức khoa học hiện đại, trang bị công cụ hội nhập quốc tế"},{"id":"SACH-DO-HUB-Q155-O3","text":"Nhấn mạnh sự hi sinh của cá nhân cho cộng đồng"},{"id":"SACH-DO-HUB-Q155-O4","text":"Nặng về giáo dục đạo đức, ứng xử trong gia đình, dòng họ, làng xã"}],"correctOptionId":"SACH-DO-HUB-Q155-O3","source":"Sách đỏ HUB (tài liệu lưu hành nội bộ)","explanation":"Theo cách khái quát của sách đỏ, cả giáo dục gia đình truyền thống và giáo dục trong xã hội mới đều đề cao trách nhiệm của cá nhân đối với cộng đồng. Vì vậy, quan niệm về sự hy sinh, đóng góp vì lợi ích chung là điểm tương đồng được câu hỏi nhấn mạnh.","topic":"Đề ôn theo sách đỏ HUB","examCode":"SACH-DO-HUB","answerStatus":"marked","basis":"Đáp án theo sách đỏ HUB"}];
